package com.wikiitemhelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class WikiClientTest
{
	@Test
	public void itemSearchKeepsOnlyMainNamespaceTitlesContainingSearchTerm()
	{
		String json = "{"
			+ "\"query\":{\"search\":["
			+ "{\"ns\":0,\"title\":\"Dragon dagger\"},"
			+ "{\"ns\":0,\"title\":\"Dragon longsword\"},"
			+ "{\"ns\":0,\"title\":\"Shield left half\"},"
			+ "{\"ns\":14,\"title\":\"Category:Dragon items\"},"
			+ "{\"ns\":0,\"title\":\"Dragon/Strategies\"},"
			+ "{\"ns\":0,\"title\":\"Dragon Slayer I\"},"
			+ "{\"ns\":0,\"title\":\"Dragon guide\"}"
			+ "]}}";

		List<String> itemNames = WikiClient.parseItemSearchResponse("Dragon", json);

		assertEquals(Arrays.asList("Dragon dagger", "Dragon longsword"), itemNames);
	}

	@Test
	public void itemSearchRequiresAllSearchWordsInTitle()
	{
		String json = "{"
			+ "\"query\":{\"search\":["
			+ "{\"ns\":0,\"title\":\"Dragon dagger\"},"
			+ "{\"ns\":0,\"title\":\"Dragon dagger (cr)\"},"
			+ "{\"ns\":0,\"title\":\"Dragon claws\"},"
			+ "{\"ns\":0,\"title\":\"Rune dagger\"}"
			+ "]}}";

		List<String> itemNames = WikiClient.parseItemSearchResponse("Dragon dagger", json);

		assertEquals(Arrays.asList("Dragon dagger", "Dragon dagger (cr)"), itemNames);
	}

	@Test
	public void itemSearchHandlesMissingSearchResults()
	{
		List<String> itemNames = WikiClient.parseItemSearchResponse("Dragon", "{\"query\":{}}");

		assertEquals(0, itemNames.size());
	}

	@Test
	public void itemLookupUrlEncodesPlusSignsLiterally()
	{
		String encodedQuery = WikiClient.buildItemLookupUrl("Antidote++").encodedQuery();

		assertTrue(encodedQuery.contains("titles=Antidote%2B%2B"));
	}

	@Test
	public void sourceLocationParserReadsInfoboxLocations()
	{
		String wikiText = "{{Infobox Monster\n"
			+ "|name = Brutal black dragon\n"
			+ "|location = [[Catacombs of Kourend]]\n"
			+ "}}\n";

		List<String> locations = WikiClient.parseLocationNames(wikiText);

		assertEquals(Arrays.asList("Catacombs of Kourend"), locations);
	}

	@Test
	public void sourceLocationResponseBuildsResult()
	{
		String json = "{"
			+ "\"query\":{\"pages\":[{\"title\":\"Kurask\",\"revisions\":[{\"content\":\"|location = [[Fremennik Slayer Dungeon]], [[Iorwerth Dungeon]]\"}]}]}"
			+ "}";

		LocationLookupResult result = WikiClient.parseSourceLocationResponse("Kurask", json);

		assertEquals("Kurask", result.getSourceName());
		assertEquals("Kurask", result.getSourceWikiPageTitle());
		assertEquals(Arrays.asList("Fremennik Slayer Dungeon", "Iorwerth Dungeon"), result.getLocationNames());
		assertEquals("https://oldschool.runescape.wiki/w/Kurask", result.getWikiUrl());
	}

	@Test
	public void locationImageParserPrefersMapContext()
	{
		String html = "<div class=\"infobox\">"
			+ "<img src=\"/images/Lizardman_shaman.png\" alt=\"Lizardman shaman combat render\">"
			+ "</div>"
			+ "<h2>Locations</h2>"
			+ "<figure><a class=\"image\"><img src=\"//oldschool.runescape.wiki/images/thumb/Shayzien_map.png/300px-Shayzien_map.png\" alt=\"Shayzien canyon map\"></a>"
			+ "<figcaption>Map of the Lizardman shaman canyon safespots.</figcaption></figure>";

		assertEquals(
			"https://oldschool.runescape.wiki/images/thumb/Shayzien_map.png/300px-Shayzien_map.png",
			WikiClient.parseBestLocationImageUrl(html)
		);
		assertEquals("Map of the Lizardman shaman canyon safespots.", WikiClient.parseBestLocationImageCaption(html));
	}

	@Test
	public void locationImageParserIgnoresUnrelatedIcons()
	{
		String html = "<table><tr><td><img src=\"/images/thumb/Dragon_spear.png/32px-Dragon_spear.png\" alt=\"Inventory icon\"></td></tr></table>";

		assertEquals(null, WikiClient.parseBestLocationImageUrl(html));
	}

	@Test
	public void locationImageParserRejectsMembersStarAndGenericDungeonIcon()
	{
		String html = "<h2>Locations</h2>"
			+ "<img src=\"//oldschool.runescape.wiki/images/thumb/Members_icon.png/30px-Members_icon.png\" alt=\"Members star\" width=\"30\" height=\"30\">"
			+ "<figure><img src=\"//oldschool.runescape.wiki/images/thumb/God_Wars_Dungeon_icon.png/64px-God_Wars_Dungeon_icon.png\" alt=\"God Wars Dungeon icon\" width=\"64\" height=\"64\">"
			+ "<figcaption>God Wars Dungeon symbol</figcaption></figure>";

		assertEquals(null, WikiClient.parseBestLocationImageUrl(html));
	}

	@Test
	public void locationImageParserRejectsKourendCrestWhenNoMapExists()
	{
		String html = "<h2>Locations</h2>"
			+ "<figure><img src=\"//oldschool.runescape.wiki/images/thumb/Kourend_Crest.png/120px-Kourend_Crest.png\" alt=\"Kourend crest\" width=\"120\" height=\"116\">"
			+ "<figcaption>Kourend logo</figcaption></figure>";

		assertEquals(null, WikiClient.parseBestLocationImageUrl(html));
	}

	@Test
	public void locationImageParserPrefersSafespotMapOverCrest()
	{
		String html = "<h2>Locations</h2>"
			+ "<figure><img src=\"//oldschool.runescape.wiki/images/thumb/Kourend_Crest.png/120px-Kourend_Crest.png\" alt=\"Kourend crest\" width=\"120\" height=\"116\">"
			+ "<figcaption>Kourend logo</figcaption></figure>"
			+ "<figure><img src=\"//oldschool.runescape.wiki/images/thumb/Lizardman_shaman_safespot_map.png/300px-Lizardman_shaman_safespot_map.png\" alt=\"Lizardman shaman safespot map\" width=\"300\" height=\"220\">"
			+ "<figcaption>Safespot location map for Lizardman shamans.</figcaption></figure>";

		assertEquals(
			"https://oldschool.runescape.wiki/images/thumb/Lizardman_shaman_safespot_map.png/300px-Lizardman_shaman_safespot_map.png",
			WikiClient.parseBestLocationImageUrl(html)
		);
	}

	@Test
	public void fullscreenMapParserBuildsTileUrlFromShowMapLink()
	{
		String html = "<td><a class=\"mw-kartographer-maplink\" data-mw-kartographer=\"\" data-zoom=\"2\""
			+ " data-lat=\"3711\" data-lon=\"1429\" data-mapid=\"0\" data-plane=\"0\""
			+ " data-overlays=\"[&quot;pins&quot;]\">Show map</a></td>";

		assertEquals(
			"https://maps.runescape.wiki/osrs/versions/2026-03-04_a/tiles/rendered/0/2/0_22_57.png",
			WikiClient.parseFullscreenMapImageUrl(html, "2026-03-04_a")
		);
	}

	@Test
	public void fullscreenMapParserZoomsOutWhenRelatedLinksShareOneLowerZoomTile()
	{
		String html = "<td><a class=\"mw-kartographer-maplink\" data-mw-kartographer=\"\" data-zoom=\"2\""
			+ " data-lat=\"9663\" data-lon=\"2633\" data-mapid=\"25\" data-plane=\"0\">Show map</a></td>"
			+ "<td><a class=\"mw-kartographer-maplink\" data-mw-kartographer=\"\" data-zoom=\"2\""
			+ " data-lat=\"9663\" data-lon=\"2689\" data-mapid=\"25\" data-plane=\"0\">Show map</a></td>";

		assertEquals(
			"https://maps.runescape.wiki/osrs/versions/2026-03-04_a/tiles/rendered/25/0/0_10_37.png",
			WikiClient.parseFullscreenMapImageUrl(html, "2026-03-04_a")
		);
	}

	@Test
	public void fullscreenMapParserIgnoresPlainFragmentLinks()
	{
		String html = "<a href=\"#mapFullscreen\">Show map</a>";

		assertEquals(null, WikiClient.parseFullscreenMapImageUrl(html, "2026-03-04_a"));
	}

	@Test
	public void mapVersionParserReadsWikiMessage()
	{
		String json = "{\"query\":{\"allmessages\":[{\"name\":\"kartographer-map-version\",\"content\":\"2026-03-04_a\"}]}}";

		assertEquals("2026-03-04_a", WikiClient.parseMapVersionResponse(json));
	}
}

package com.wikiitemhelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;

public class PinnedItemsManagerTest
{
	@Test
	public void parsePreservesItemNamesWithSymbols()
	{
		List<String> pinnedItems = PinnedItemsManager.parse("Pharaoh's sceptre\nAntidote++\nWeapon poison(++)\nDragon dagger(p++)");

		assertEquals("Pharaoh's sceptre", pinnedItems.get(0));
		assertEquals("Antidote++", pinnedItems.get(1));
		assertEquals("Weapon poison(++)", pinnedItems.get(2));
		assertEquals("Dragon dagger(p++)", pinnedItems.get(3));
	}

	@Test
	public void serializeUsesNewlineDelimitedItems()
	{
		List<String> pinnedItems = new ArrayList<>();
		pinnedItems.add("Pharaoh's sceptre");
		pinnedItems.add("Antidote++");
		pinnedItems.add("Weapon poison(++)");

		assertEquals("[Favorites]\nPharaoh's sceptre\nAntidote++\nWeapon poison(++)", PinnedItemsManager.serialize(pinnedItems));
	}

	@Test
	public void managerDeduplicatesCaseInsensitiveButKeepsOriginalDisplayName()
	{
		AtomicReference<String> savedItems = new AtomicReference<>("");
		PinnedItemsManager manager = new PinnedItemsManager(savedItems::get, savedItems::set);

		assertTrue(manager.addPinnedItem("Dragon dagger(p++)"));
		assertFalse(manager.addPinnedItem("dragon dagger(p++)"));

		assertEquals("[Favorites]\nDragon dagger(p++)", savedItems.get());
		assertTrue(manager.isPinned("DRAGON DAGGER(P++)"));
	}

	@Test
	public void removeUpdatesSavedConfigImmediately()
	{
		AtomicReference<String> savedItems = new AtomicReference<>("Antidote++\nWeapon poison(++)");
		PinnedItemsManager manager = new PinnedItemsManager(savedItems::get, savedItems::set);

		assertTrue(manager.removePinnedItem("antidote++"));

		assertEquals("[Favorites]\nWeapon poison(++)", savedItems.get());
		assertFalse(manager.isPinned("Antidote++"));
	}

	@Test
	public void groupedPinsRoundTripAndKeepLegacyPinsInFavorites()
	{
		List<PinnedItemsManager.PinnedItemGroup> groups = PinnedItemsManager.parseGroups("Dragon dagger\n[Clues]\nSpade\nAntidote++");

		assertEquals("Favorites", groups.get(0).getName());
		assertEquals("Dragon dagger", groups.get(0).getItems().get(0));
		assertEquals("Clues", groups.get(1).getName());
		assertEquals("Spade", groups.get(1).getItems().get(0));
		assertEquals("Antidote++", groups.get(1).getItems().get(1));
	}

	@Test
	public void canAddPinnedItemToNamedGroup()
	{
		AtomicReference<String> savedItems = new AtomicReference<>("");
		PinnedItemsManager manager = new PinnedItemsManager(savedItems::get, savedItems::set);

		assertTrue(manager.addPinnedItem("Clues", "Spade"));

		assertEquals("[Clues]\nSpade", savedItems.get());
	}

	@Test
	public void emptyGroupsCanBeSavedBeforeItemsAreAdded()
	{
		AtomicReference<String> savedItems = new AtomicReference<>("");
		PinnedItemsManager manager = new PinnedItemsManager(savedItems::get, savedItems::set);

		assertTrue(manager.addGroup("Alchs"));

		assertEquals("[Alchs]", savedItems.get());
		assertEquals("Alchs", manager.getPinnedGroups().get(0).getName());
		assertTrue(manager.getPinnedGroups().get(0).getItems().isEmpty());
	}
}

package com.wikiitemhelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class MaterialsChecklistBuilderTest
{
	private final WikiItemParser parser = new WikiItemParser();
	private final MaterialsChecklistBuilder builder = new MaterialsChecklistBuilder();

	@Test
	public void buildsRuneLongswordChecklistForSelectedRecipeOutput()
	{
		WikiItemSummary summary = parser.parse("== Creation ==\n"
			+ "{{Recipe\n"
			+ "|skill1 = Smithing\n"
			+ "|skill1lvl = 91\n"
			+ "|tools = Hammer\n"
			+ "|facilities = Anvil\n"
			+ "|mat1 = Runite bar\n"
			+ "|mat1quantity = 2\n"
			+ "|output1 = Rune longsword\n"
			+ "}}\n");

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Rune longsword", summary.getCreationRecipes());

		assertFalse(checklist.isEmpty());
		MaterialsChecklistBuilder.RecipeChecklist recipe = checklist.getRecipes().get(0);
		assertEquals("91 Smithing", recipe.getTitle());
		assertEquals("Runite bar x2", recipe.getEntries().get(0).toPlainText());
		assertEquals("Hammer", recipe.getEntries().get(1).toPlainText());
		assertEquals("Anvil", recipe.getEntries().get(2).toPlainText());
	}

	@Test
	public void buildsSuperCombatPotionChecklistWhenOutputHasDoseSuffix()
	{
		WikiItemSummary summary = parser.parse("== Creation ==\n"
			+ "{{Recipe\n"
			+ "|skill1 = Herblore\n"
			+ "|skill1lvl = 90\n"
			+ "|mat1 = Super attack(4)\n"
			+ "|mat2 = Super defence(4)\n"
			+ "|mat3 = Super strength(4)\n"
			+ "|mat4 = Torstol\n"
			+ "|output1 = Super combat potion(4)\n"
			+ "}}\n");

		assertEquals("Level 90 Herblore\n  Materials: Super attack(4), Super defence(4), Super strength(4), Torstol\n  Output: Super combat potion(4)", summary.getCreation());

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Super combat potion", summary.getCreationRecipes());

		assertFalse(checklist.isEmpty());
		MaterialsChecklistBuilder.RecipeChecklist recipe = checklist.getRecipes().get(0);
		assertEquals("90 Herblore", recipe.getTitle());
		assertEquals("Super attack(4) x1", recipe.getEntries().get(0).toPlainText());
		assertEquals("Super defence(4) x1", recipe.getEntries().get(1).toPlainText());
		assertEquals("Super strength(4) x1", recipe.getEntries().get(2).toPlainText());
		assertEquals("Torstol x1", recipe.getEntries().get(3).toPlainText());
	}

	@Test
	public void keepsPestleAndMortarAsOneTool()
	{
		WikiItemSummary summary = parser.parse("== Creation ==\n"
			+ "{{Recipe\n"
			+ "|tools = Pestle and mortar\n"
			+ "|mat1 = Desert goat horn\n"
			+ "|output1 = Goat horn dust\n"
			+ "}}\n");

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Goat horn dust", summary.getCreationRecipes());
		List<MaterialsChecklistBuilder.ChecklistEntry> entries = checklist.getRecipes().get(0).getEntries();

		assertEquals(2, entries.size());
		assertEquals("Desert goat horn x1", entries.get(0).toPlainText());
		assertEquals("Pestle and mortar", entries.get(1).toPlainText());
	}

	@Test
	public void collapsesNearDuplicateSuperCombatPotionChecklistRecipes()
	{
		WikiItemSummary summary = parser.parse("== Creation ==\n"
			+ "{{Recipe\n"
			+ "|skill1 = Herblore\n"
			+ "|skill1lvl = 90\n"
			+ "|mat1 = Super attack(4)\n"
			+ "|mat2 = Super defence(4)\n"
			+ "|mat3 = Super strength(4)\n"
			+ "|mat4 = Torstol potion (unf)\n"
			+ "|output1 = Super combat potion(4)\n"
			+ "}}\n"
			+ "{{Recipe\n"
			+ "|skill1 = Herblore\n"
			+ "|skill1lvl = 90\n"
			+ "|mat1 = Super attack(4)\n"
			+ "|mat2 = Super defence(4)\n"
			+ "|mat3 = Super strength(4)\n"
			+ "|mat4 = Torstol\n"
			+ "|output1 = Super combat potion(4)\n"
			+ "}}\n");

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Super combat potion", summary.getCreationRecipes(), summary.getCreation());
		List<MaterialsChecklistBuilder.ChecklistEntry> entries = checklist.getRecipes().get(0).getEntries();

		assertEquals(1, checklist.getRecipes().size());
		assertEquals("Super attack(4) x1", entries.get(0).toPlainText());
		assertEquals("Super defence(4) x1", entries.get(1).toPlainText());
		assertEquals("Super strength(4) x1", entries.get(2).toPlainText());
		assertEquals("Torstol x1", entries.get(3).toPlainText());
	}

	@Test
	public void splitsCommaSeparatedPotionMaterialsWithoutSplittingDoseParentheses()
	{
		WikiItemSummary summary = parser.parse("== Creation ==\n"
			+ "{{Recipe\n"
			+ "|skill1 = Herblore\n"
			+ "|skill1lvl = 90\n"
			+ "|mat1 = Super attack(4), Super defence(4), Super strength(4), Torstol\n"
			+ "|output1 = Super combat potion(4)\n"
			+ "}}\n");

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Super combat potion", summary.getCreationRecipes());
		List<MaterialsChecklistBuilder.ChecklistEntry> entries = checklist.getRecipes().get(0).getEntries();

		assertEquals(4, entries.size());
		assertEquals("Super attack(4) x1", entries.get(0).toPlainText());
		assertEquals("Super defence(4) x1", entries.get(1).toPlainText());
		assertEquals("Super strength(4) x1", entries.get(2).toPlainText());
		assertEquals("Torstol x1", entries.get(3).toPlainText());
	}

	@Test
	public void canBuildFromDisplayedCreationTextWhenStructuredRecipeIsUnavailable()
	{
		String creationText = "Level 90 Herblore\n"
			+ "  Materials: Super attack(4), Super defence(4), Super strength(4), Torstol\n"
			+ "  Output: Super combat potion(4)";

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Super combat potion", Collections.emptyList(), creationText);
		List<MaterialsChecklistBuilder.ChecklistEntry> entries = checklist.getRecipes().get(0).getEntries();

		assertEquals("90 Herblore", checklist.getRecipes().get(0).getTitle());
		assertEquals("Super attack(4) x1", entries.get(0).toPlainText());
		assertEquals("Super defence(4) x1", entries.get(1).toPlainText());
		assertEquals("Super strength(4) x1", entries.get(2).toPlainText());
		assertEquals("Torstol x1", entries.get(3).toPlainText());
	}

	@Test
	public void buildsDragonDaggerVariantChecklistOnlyWhenVariantIsSelected()
	{
		WikiItemSummary summary = parser.parse("== Creation ==\n"
			+ dragonDaggerRecipe("Weapon poison", "Dragon dagger(p)")
			+ dragonDaggerRecipe("Weapon poison(+)", "Dragon dagger(p+)")
			+ dragonDaggerRecipe("Weapon poison(++)", "Dragon dagger(p++)"));

		assertTrue(builder.build("Dragon dagger", summary.getCreationRecipes()).isEmpty());

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Dragon dagger(p+)", summary.getCreationRecipes());
		List<MaterialsChecklistBuilder.ChecklistEntry> entries = checklist.getRecipes().get(0).getEntries();
		assertEquals("Dragon dagger x1", entries.get(0).toPlainText());
		assertEquals("Weapon poison(+) x1", entries.get(1).toPlainText());
	}

	@Test
	public void buildsDragonDaggerDoublePlusVariantChecklistWhenSelected()
	{
		WikiItemSummary summary = parser.parse("== Creation ==\n"
			+ dragonDaggerRecipe("Weapon poison", "Dragon dagger(p)")
			+ dragonDaggerRecipe("Weapon poison(+)", "Dragon dagger(p+)")
			+ dragonDaggerRecipe("Weapon poison(++)", "Dragon dagger(p++)"));

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Dragon dagger(p++)", summary.getCreationRecipes());
		List<MaterialsChecklistBuilder.ChecklistEntry> entries = checklist.getRecipes().get(0).getEntries();

		assertEquals("Dragon dagger x1", entries.get(0).toPlainText());
		assertEquals("Weapon poison(++) x1", entries.get(1).toPlainText());
	}

	@Test
	public void buildsAntidotePlusChecklistWithLiteralPlusPreserved()
	{
		WikiItemSummary summary = parser.parse("== Creation ==\n"
			+ "{{Recipe\n"
			+ "|skill1 = Herblore\n"
			+ "|skill1lvl = 68\n"
			+ "|mat1 = Antidote+ (unf)\n"
			+ "|mat2 = Yew roots\n"
			+ "|output1 = Antidote+(4)\n"
			+ "}}\n");

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Antidote+", summary.getCreationRecipes(), summary.getCreation());
		List<MaterialsChecklistBuilder.ChecklistEntry> entries = checklist.getRecipes().get(0).getEntries();

		assertEquals("68 Herblore", checklist.getRecipes().get(0).getTitle());
		assertEquals("Antidote+ (unf) x1", entries.get(0).toPlainText());
		assertEquals("Yew roots x1", entries.get(1).toPlainText());
	}

	@Test
	public void buildsAntidoteDoublePlusChecklistFromCreationSubsections()
	{
		WikiItemSummary summary = parser.parse("==Creation==\n"
			+ "===Unfinished recipe===\n"
			+ "{{Recipe\n"
			+ "|skill1 = Herblore\n"
			+ "|skill1lvl = 79\n"
			+ "|mat1 = Antidote++ (unf)\n"
			+ "|mat2 = Magic roots\n"
			+ "|output1 = Antidote++(4)\n"
			+ "}}\n"
			+ "===Full recipe===\n"
			+ "{{Recipe\n"
			+ "|skill1 = Herblore\n"
			+ "|skill1lvl = 79\n"
			+ "|mat1 = Coconut milk\n"
			+ "|mat2 = Irit leaf\n"
			+ "|mat3 = Magic roots\n"
			+ "|output1 = Antidote++(4)\n"
			+ "}}\n");

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Antidote++", summary.getCreationRecipes(), summary.getCreation());
		List<MaterialsChecklistBuilder.ChecklistEntry> firstRecipe = checklist.getRecipes().get(0).getEntries();

		assertEquals(2, checklist.getRecipes().size());
		assertEquals("79 Herblore", checklist.getRecipes().get(0).getTitle());
		assertEquals("Antidote++ (unf) x1", firstRecipe.get(0).toPlainText());
		assertEquals("Magic roots x1", firstRecipe.get(1).toPlainText());
	}

	@Test
	public void buildsWeaponPoisonDoublePlusChecklistWithLiteralPlusPreserved()
	{
		WikiItemSummary summary = parser.parse("== Creation ==\n"
			+ "{{Recipe\n"
			+ "|skill1 = Herblore\n"
			+ "|skill1lvl = 82\n"
			+ "|mat1 = Weapon poison+ (unf)\n"
			+ "|mat2 = Nightshade\n"
			+ "|output1 = Weapon poison(++)\n"
			+ "}}\n");

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Weapon poison(++)", summary.getCreationRecipes(), summary.getCreation());
		List<MaterialsChecklistBuilder.ChecklistEntry> entries = checklist.getRecipes().get(0).getEntries();

		assertEquals("Weapon poison+ (unf) x1", entries.get(0).toPlainText());
		assertEquals("Nightshade x1", entries.get(1).toPlainText());
	}

	@Test
	public void returnsMultipleMatchingRecipesCompactly()
	{
		WikiItemSummary summary = parser.parse("== Creation ==\n"
			+ "{{Recipe|skill1 = Crafting|skill1lvl = 1|mat1 = Ball of wool|output1 = Toy}}\n"
			+ "{{Recipe|skill1 = Crafting|skill1lvl = 2|mat1 = Thread|output1 = Toy}}\n");

		MaterialsChecklistBuilder.MaterialsChecklist checklist = builder.build("Toy", summary.getCreationRecipes());

		assertEquals(2, checklist.getRecipes().size());
		assertEquals("1 Crafting", checklist.getRecipes().get(0).getTitle());
		assertEquals("2 Crafting", checklist.getRecipes().get(1).getTitle());
	}

	private static String dragonDaggerRecipe(String poison, String output)
	{
		return "{{Recipe\n"
			+ "|mat1 = Dragon dagger\n"
			+ "|mat1quantity = 1\n"
			+ "|mat2 = " + poison + "\n"
			+ "|mat2quantity = 1\n"
			+ "|output1 = " + output + "\n"
			+ "}}\n";
	}
}

package com.wikiitemhelper;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import org.junit.Test;

public class WikiItemResultTest
{
	private final WikiItemParser parser = new WikiItemParser();

	@Test
	public void ironmanDisplayFiltersTradeStyleLines()
	{
