package com.wikiitemhelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import org.junit.Test;

public class BestSourceBuilderTest
{
	private final BestSourceBuilder builder = new BestSourceBuilder();

	@Test
	public void highlightsCompactCreationShopAndBestDrops()
	{
		WikiItemSummary summary = new WikiItemSummary(
			"Level 91 Smithing\n  Materials: 2 Runite bar\n  Tools: Hammer\n  Output: Rune longsword\n  XP: 150",
			"Drop source table found on wiki for Rune longsword.",
			"Zanaris\nWarriors' Guild",
			"",
			Arrays.asList(
				drop("Kurask", "1/41.33"),
				drop("King Black Dragon", "1/12.8"),
				drop("Reward casket (hard)", "1/5")
			),
			"A rune longsword.",
			true
		);

		String bestSources = builder.build(summary, false);

		assertTrue(bestSources.startsWith("Best sources:"));
		assertTrue(bestSources.contains("Crafting:\n  Level 91 Smithing\n  Materials: 2 Runite bar\n  Tools: Hammer"));
		assertFalse(bestSources.contains("Output: Rune longsword"));
		assertTrue(bestSources.contains("Shop:\n  Zanaris"));
		assertTrue(bestSources.contains("Warriors' Guild"));
		assertTrue(bestSources.indexOf("King Black Dragon - 1/12.8") < bestSources.indexOf("Kurask - 1/41.33"));
		assertTrue(bestSources.indexOf("Kurask - 1/41.33") < bestSources.indexOf("Reward casket (hard) - 1/5"));
	}

	@Test
	public void parsesCommonRarityFormats()
	{
		assertEquals(128D, BestSourceBuilder.parseRarityScore("1/128"), 0.001D);
		assertEquals(12.8D, BestSourceBuilder.parseRarityScore("1/12.8"), 0.001D);
		assertEquals(17D, BestSourceBuilder.parseRarityScore("~1/17"), 0.001D);
		assertEquals(76D / 3D, BestSourceBuilder.parseRarityScore("3 x 1/76"), 0.001D);
		assertEquals(71.1D, BestSourceBuilder.parseRarityScore("1/71.96; 1/71.1"), 0.001D);
	}

	@Test
	public void unknownRarityFormatsDoNotCrashAndSortAfterParseableDrops()
	{
		WikiItemSummary summary = new WikiItemSummary(
			"",
			"",
			"",
			"",
			Arrays.asList(
				drop("Unknown-rate monster", "Very rare"),
				drop("Lizardman shaman", "1/5000")
			),
			"",
			true
		);

		String bestSources = builder.build(summary, false);

		assertTrue(bestSources.indexOf("Lizardman shaman - 1/5000") < bestSources.indexOf("Unknown-rate monster - Very rare"));
	}

	@Test
	public void ironmanTitleAndTradeFilteringAreApplied()
	{
		WikiItemSummary summary = new WikiItemSummary(
			"Made with a pestle and mortar.",
			"",
			"Zanaris\nGrand Exchange",
			"",
			Arrays.asList(drop("Grand Exchange", "1/1"), drop("Tormented Demon", "~1/17")),
			"",
			true
		);

		String bestSources = builder.build(summary, true);

		assertTrue(bestSources.startsWith("Best Ironman sources:"));
		assertTrue(bestSources.contains("Zanaris"));
		assertTrue(bestSources.contains("Tormented Demon - ~1/17"));
		assertFalse(bestSources.contains("Grand Exchange"));
	}

	@Test
	public void promotedStructuredDropsAreRemovedFromRemainingDrops()
	{
		WikiItemSummary summary = new WikiItemSummary(
			"",
			"",
			"",
			"",
			Arrays.asList(drop("Lizardman shaman", "1/3,000")),
			"",
			true
		);

		BestSourceBuilder.BestSourceResult bestSources = builder.buildResult(summary, true);

		assertTrue(bestSources.includesDrop(summary.getDropSources().get(0)));
		assertTrue(BestSourceBuilder.removeBestDropSources(summary.getDropSources(), bestSources).isEmpty());
	}

	@Test
	public void displayTextShowsOtherDropsWithoutRepeatingOnlyBestDrop()
	{
		WikiItemSummary summary = new WikiItemSummary(
			"",
			"",
			"",
			"Lizardman shaman\n  Level: 150\n  Qty: 1\n  Rarity: 1/3,000",
			Arrays.asList(drop("Lizardman shaman", "1/3,000")),
			"",
			true
		);
		WikiItemResult result = new WikiItemResult("Dragon warhammer", "https://example.test", summary);

		String displayText = result.toDisplayText(true, null);

		assertTrue(displayText.contains("Best Ironman sources:"));
		assertTrue(displayText.contains("Lizardman shaman - 1/3,000"));
		assertTrue(displayText.contains("Other drops:\nNo additional drops found"));
		assertFalse(displayText.contains("Level: 150"));
	}

	@Test
	public void baseItemVariantRecipesAreExcludedFromBestSourcesAndMainCreation()
	{
		WikiItemSummary summary = new WikiItemSummary(
			dragonDaggerVariantRecipes(),
			"",
			"Zanaris",
			"",
			Arrays.asList(drop("Tormented Demon", "~1/17")),
			"",
			true
		);

		BestSourceBuilder.BestSourceResult bestSources = builder.buildResult(summary, "Dragon dagger", false);
		BestSourceBuilder.CreationSplit creationSplit = BestSourceBuilder.splitCreation(summary.getCreation(), "Dragon dagger", false);
		WikiItemResult result = new WikiItemResult("Dragon dagger", "https://example.test", summary);
		String displayText = result.toDisplayText(false, null);

		assertTrue(bestSources.getCreationEntries().isEmpty());
		assertEquals(WikiItemSummary.NO_CLEAR_DATA_FOUND, creationSplit.getNormalCreationText());
		assertEquals(3, creationSplit.getVariantRecipes().size());
		assertTrue(displayText.contains("Variant recipes available: 3"));
		assertFalse(displayText.contains("Dragon dagger(p): Dragon dagger + Weapon poison"));
		assertFalse(displayText.contains("Crafting:"));
	}

	@Test
	public void selectedVariantCreationRecipeIsShownNormally()
	{
		WikiItemSummary summary = new WikiItemSummary(
			"Materials: Dragon dagger, Weapon poison(+)\n  Output: Dragon dagger(p+)",
			"",
			"",
			"",
			Arrays.asList(drop("Tormented Demon", "~1/17")),
			"",
			true
		);

		BestSourceBuilder.BestSourceResult bestSources = builder.buildResult(summary, "Dragon dagger(p+)", false);
		BestSourceBuilder.CreationSplit creationSplit = BestSourceBuilder.splitCreation(summary.getCreation(), "Dragon dagger(p+)", false);

		assertFalse(bestSources.getCreationEntries().isEmpty());
		assertFalse(WikiItemSummary.NO_CLEAR_DATA_FOUND.equals(creationSplit.getNormalCreationText()));
		assertFalse(creationSplit.hasVariantRecipes());
		assertTrue(bestSources.toDisplayText().contains("Crafting:"));
		assertTrue(bestSources.toDisplayText().contains("Materials: Dragon dagger, Weapon poison(+)"));
	}

	@Test
	public void bestSourcesCollapseNearDuplicatePotionRecipes()
	{
		WikiItemSummary summary = new WikiItemSummary(
			"Level 90 Herblore\n"
				+ "  Materials: Super attack(4), Super defence(4), Super strength(4), Torstol potion (unf)\n"
				+ "  Output: Super combat potion(4)\n\n"
				+ "Level 90 Herblore\n"
				+ "  Materials: Super attack(4), Super defence(4), Super strength(4), Torstol\n"
				+ "  Output: Super combat potion(4)",
			"",
			"",
			"",
			Arrays.asList(drop("Tormented Demon", "~1/17")),
			"",
			true
		);

		String bestSources = builder.buildResult(summary, "Super combat potion", true).toDisplayText();
		BestSourceBuilder.BestSourceResult result = builder.buildResult(summary, "Super combat potion", true);
		String remainingCreation = BestSourceBuilder.removeBestCreation(summary.getCreation(), result, "Super combat potion", true);

		assertEquals(1, result.getCreationEntries().size());
		assertTrue(bestSources.contains("Materials: Super attack(4), Super defence(4), Super strength(4), Torstol"));
		assertFalse(bestSources.contains("Torstol potion (unf)"));
		assertEquals(WikiItemSummary.NO_CLEAR_DATA_FOUND, remainingCreation);
	}

	@Test
	public void antidoteDoublePlusCreationIsNotHiddenAsVariantForExactSelectedItem()
	{
		WikiItemSummary summary = new WikiItemSummary(
			"Level 79 Herblore\n"
				+ "  Materials: Antidote++ (unf), Magic roots\n"
				+ "  Output: Antidote++(4)",
			"",
			"",
			"",
			Arrays.asList(drop("Zulrah", "1/128")),
			"",
			true
		);

		BestSourceBuilder.BestSourceResult bestSources = builder.buildResult(summary, "Antidote++", true);
		BestSourceBuilder.CreationSplit creationSplit = BestSourceBuilder.splitCreation(summary.getCreation(), "Antidote++", true);

		assertFalse(bestSources.getCreationEntries().isEmpty());
		assertFalse(creationSplit.hasVariantRecipes());
		assertTrue(bestSources.toDisplayText().contains("Materials: Antidote++ (unf), Magic roots"));
	}

	private static DropSource drop(String sourceName, String rarity)
	{
		return new DropSource(sourceName, sourceName, sourceName + "\n  Level: 100\n  Qty: 1\n  Rarity: " + rarity);
	}

	private static String dragonDaggerVariantRecipes()
	{
		return "Materials: Dragon dagger, Weapon poison\n  Output: Dragon dagger(p)\n\n"
			+ "Materials: Dragon dagger, Weapon poison(+)\n  Output: Dragon dagger(p+)\n\n"
			+ "Materials: Dragon dagger, Weapon poison(++)\n  Output: Dragon dagger(p++)";
	}
}

