package com.wikiitemhelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import org.junit.Test;

public class ItemSearchSelectorTest
{
	private final ItemSearchSelector selector = new ItemSearchSelector();

	@Test
	public void superStrengthPotionPrefersBaseItemOverDivineVariant()
	{
		ItemSearchSelector.SearchDecision decision = selector.decide(
			"Super Strength Potion",
			Arrays.asList("Divine super strength potion", "Super strength")
		);

		assertTrue(decision.shouldDirectOpen());
		assertEquals("Super strength", decision.getDirectOpenTitle());
	}

	@Test
	public void divineSuperStrengthOpensDivinePotion()
	{
		ItemSearchSelector.SearchDecision decision = selector.decide(
			"divine super strength",
			Arrays.asList("Super strength", "Divine super strength potion")
		);

		assertTrue(decision.shouldDirectOpen());
		assertEquals("Divine super strength potion", decision.getDirectOpenTitle());
	}

	@Test
	public void broadDragonSearchShowsSelectionList()
	{
		ItemSearchSelector.SearchDecision decision = selector.decide(
			"Dragon",
			Arrays.asList("Dragon dagger", "Dragon warhammer")
		);

		assertFalse(decision.shouldDirectOpen());
		assertEquals(Arrays.asList("Dragon dagger", "Dragon warhammer"), decision.getSelectionTitles());
	}

	@Test
	public void exactDragonWarhammerOpensDirectly()
	{
		ItemSearchSelector.SearchDecision decision = selector.decide(
			"Dragon warhammer",
			Arrays.asList("Dragon dagger", "Dragon warhammer")
		);

		assertTrue(decision.shouldDirectOpen());
		assertEquals("Dragon warhammer", decision.getDirectOpenTitle());
	}

	@Test
	public void poisonedVariantCanBeFoundWithUserSpacing()
	{
		ItemSearchSelector.SearchDecision decision = selector.decide(
			"dragon dagger p++",
			Arrays.asList("Dragon dagger", "Dragon dagger(p++)")
		);

		assertTrue(decision.shouldDirectOpen());
		assertEquals("Dragon dagger(p++)", decision.getDirectOpenTitle());
	}
}

