import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import javax.inject.Singleton;

@Singleton
public class SimpleLocationResolver implements LocationResolver
{
	private static final List<SourceLocation> KNOWN_LOCATIONS = Arrays.asList(
		new SourceLocation("Lumbridge Castle", "Early-game castle in Lumbridge."),
		new SourceLocation("Varrock", "Central Misthalin city with many shops and low-level routes."),
		new SourceLocation("Falador", "Asgarnia city near the Mining Guild and White Knights' Castle."),
		new SourceLocation("Al Kharid", "Desert border city east of Lumbridge."),
		new SourceLocation("Karamja", "Island south of Asgarnia and Misthalin."),
		new SourceLocation("Wilderness", "Dangerous PvP area north of Edgeville and Varrock."),
		new SourceLocation("Slayer Tower", "Slayer dungeon north-west of Canifis."),
		new SourceLocation("God Wars Dungeon", "High-level dungeon north of Trollheim."),
		new SourceLocation("Chambers of Xeric", "Raid in Mount Quidamortem on Great Kourend."),
		new SourceLocation("Theatre of Blood", "Raid in Ver Sinhaza, Morytania."),
		new SourceLocation("Tombs of Amascut", "Raid in the Kharidian Desert necropolis."),
		new SourceLocation("Zul-Andra", "Island boss area reached by charter or fairy ring."),
		new SourceLocation("Vorkath", "Boss encounter on Ungael after Dragon Slayer II."),
		new SourceLocation("Barrows", "Morytania minigame east of Mort'ton."),
		new SourceLocation("Warriors' Guild", "Guild west of Burthorpe for melee defenders.")
	);

	@Override
	public List<SourceLocation> resolve(WikiItemSummary summary)
	{
		String searchableText = String.join("\n",
			summary.getGeneralSummary(),
			summary.getCreation(),
			summary.getSources(),
			summary.getShops(),
			summary.getDrops()
		).toLowerCase(Locale.ENGLISH);

		List<SourceLocation> matches = new ArrayList<>();
		for (SourceLocation location : KNOWN_LOCATIONS)
		{
			if (searchableText.contains(location.getName().toLowerCase(Locale.ENGLISH)))
			{
				matches.add(location);
			}
		}

		return matches;
	}
}

package com.wikiitemhelper;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class CreationRecipe
{
	private final String skill;
	private final String level;
	private final List<Entry> materials;
	private final List<Entry> tools;
	private final List<Entry> facilities;
	private final List<Entry> outputs;
	private final String xp;

	public CreationRecipe(String skill, String level, List<Entry> materials, List<Entry> tools, List<Entry> facilities, List<Entry> outputs, String xp)
	{
		this.skill = blankToNull(skill);
		this.level = blankToNull(level);
		this.materials = immutableCopy(materials);
		this.tools = immutableCopy(tools);
		this.facilities = immutableCopy(facilities);
		this.outputs = immutableCopy(outputs);
		this.xp = blankToNull(xp);
	}

	public String getSkill()
	{
		return skill;
	}

	public String getLevel()
	{
		return level;
	}

	public List<Entry> getMaterials()
	{
		return materials;
	}

	public List<Entry> getTools()
	{
		return tools;
	}

	public List<Entry> getFacilities()
	{
		return facilities;
	}

	public List<Entry> getOutputs()
	{
		return outputs;
	}

	public String getXp()
	{
		return xp;
	}

	private static List<Entry> immutableCopy(List<Entry> entries)
	{
		return Collections.unmodifiableList(new ArrayList<>(entries == null ? Collections.emptyList() : entries));
	}

	private static String blankToNull(String value)
	{
		return value == null || value.trim().isEmpty() ? null : value.trim();
	}

	public static class Entry
	{
		private final String name;
		private final String quantity;

		public Entry(String name, String quantity)
		{
			this.name = blankToNull(name);
			this.quantity = blankToNull(quantity);
		}

		public String getName()
		{
			return name;
		}

		public String getQuantity()
		{
			return quantity;
		}
	}
}

package com.wikiitemhelper;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@PluginDescriptor(
	name = "Item Lookup",
	description = "Looks up OSRS item summaries from the Old School RuneScape Wiki",
	tags = {"wiki", "item", "items", "lookup"}
)
public class WikiItemHelperPlugin extends Plugin
{
	private static final String LOOKUP_OPTION = "Lookup item";
	private static final String PIN_OPTION = "Pin item";

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private WikiItemHelperPanel panel;

	@Inject
	private WikiItemHelperConfig config;

	private NavigationButton navigationButton;

	@Override
	protected void startUp()
	{
		navigationButton = NavigationButton.builder()
			.tooltip("Item Lookup")
			.icon(createPanelIcon())
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navigationButton);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navigationButton);
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.showRightClickOptions() || event.getItemId() <= 0)
		{
			return;
		}

		MenuEntry sourceEntry = event.getMenuEntry();
		if (LOOKUP_OPTION.equals(sourceEntry.getOption()) || PIN_OPTION.equals(sourceEntry.getOption()))
		{
			return;
		}

		if (containsPluginItemEntry(event.getItemId()))
		{
			return;
		}

		ItemComposition itemComposition = client.getItemDefinition(event.getItemId());
		String itemName = cleanItemName(itemComposition == null ? "" : itemComposition.getMembersName());
		if (itemName.isEmpty())
		{
			return;
		}

		client.createMenuEntry(-1)
			.setOption(LOOKUP_OPTION)
			.setTarget(sourceEntry.getTarget())
			.setType(MenuAction.RUNELITE)
			.setItemId(event.getItemId())
			.onClick(menuEntry -> SwingUtilities.invokeLater(() ->
			{
				clientToolbar.openPanel(navigationButton);
				panel.lookupItemFromMenu(itemName);
			}));

		client.createMenuEntry(-1)
			.setOption(PIN_OPTION)
			.setTarget(sourceEntry.getTarget())
			.setType(MenuAction.RUNELITE)
			.setItemId(event.getItemId())
			.onClick(menuEntry -> SwingUtilities.invokeLater(() -> panel.pinItemFromMenu(itemName)));
	}

	@Provides
	WikiItemHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WikiItemHelperConfig.class);
	}

	private static BufferedImage createPanelIcon()
	{
		BufferedImage image = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(new Color(67, 141, 201));
		graphics.fillOval(3, 3, 26, 26);
		graphics.setColor(Color.WHITE);
		graphics.fillRect(9, 9, 14, 4);
		graphics.fillRect(9, 15, 14, 3);
		graphics.fillRect(9, 20, 9, 3);
		graphics.dispose();
		return image;
	}

	private boolean containsPluginItemEntry(int itemId)
	{
		for (MenuEntry menuEntry : client.getMenuEntries())
		{
			if (menuEntry.getItemId() == itemId
				&& (LOOKUP_OPTION.equals(menuEntry.getOption()) || PIN_OPTION.equals(menuEntry.getOption())))
			{
				return true;
			}
		}

		return false;
	}

	private static String cleanItemName(String itemName)
	{
		return itemName == null ? "" : itemName.replace('\u00A0', ' ').trim();
	}
}

