package com.wikiitemhelper;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

public class MaterialAcquisitionHintBuilder
{
	private static final Pattern DOSE_SUFFIX = Pattern.compile("(?i).*\\([1-4]\\)\\s*$");
	private static final Set<String> HERBS = new HashSet<>(Arrays.asList(
		"guam leaf", "marrentill", "tarromin", "harralander", "ranarr weed", "toadflax",
		"irit leaf", "avantoe", "kwuarm", "snapdragon", "cadantine", "lantadyme",
		"dwarf weed", "torstol", "rogue's purse", "clean guam leaf", "clean marrentill",
		"clean tarromin", "clean harralander", "clean ranarr weed", "clean toadflax",
		"clean irit leaf", "clean avantoe", "clean kwuarm", "clean snapdragon",
		"clean cadantine", "clean lantadyme", "clean dwarf weed", "clean torstol"
	));
	private static final Set<String> GEMS = new HashSet<>(Arrays.asList(
		"opal", "jade", "red topaz", "sapphire", "emerald", "ruby", "diamond",
		"dragonstone", "onyx", "zenyte", "uncut opal", "uncut jade", "uncut red topaz",
		"uncut sapphire", "uncut emerald", "uncut ruby", "uncut diamond", "uncut dragonstone",
		"uncut onyx", "uncut zenyte"
	));
	private static final Set<String> FISH_AND_FOOD = new HashSet<>(Arrays.asList(
		"shrimp", "anchovies", "sardine", "herring", "trout", "salmon", "tuna", "lobster",
		"swordfish", "monkfish", "shark", "anglerfish", "karambwan", "manta ray", "dark crab",
		"bread", "cake", "cheese", "potato", "meat", "cooked meat"
	));

	public List<MaterialAcquisitionHint> build(String selectedItemName, MaterialsChecklistBuilder.RecipeChecklist preferredRecipe, boolean ironmanMode)
	{
		List<MaterialAcquisitionHint> hints = new ArrayList<>();
		if (preferredRecipe == null)
		{
			return hints;
		}

		for (MaterialsChecklistBuilder.ChecklistEntry entry : preferredRecipe.getEntries())
		{
			String name = entry.getName();
			if (name == null || name.trim().isEmpty())
			{
				continue;
			}

			hints.add(new MaterialAcquisitionHint(name, entry.getQuantity(), hintFor(name, ironmanMode), name));
		}

		return hints;
	}

	private static String hintFor(String materialName, boolean ironmanMode)
	{
		String normalized = normalize(materialName);
		if (!ironmanMode && isTradeFriendly(normalized))
		{
			return tradeHint(normalized);
		}
		if (DOSE_SUFFIX.matcher(materialName.trim()).matches())
		{
			return "Make with Herblore or decant from doses";
		}
		if (HERBS.contains(normalized))
		{
			return "Farming, herb drops, or herb packs";
		}
		if (normalized.matches(".*\\bbar$"))
		{
			return barHint(normalized);
		}
		if (normalized.matches(".*\\bore$"))
		{
			return "Mine ore rocks or obtain from drops/rewards";
		}
		if (normalized.matches(".*\\blogs?$") || normalized.equals("redwood") || normalized.equals("kindling"))
		{
			return "Cut from trees or obtain from PvM/rewards";
		}
		if (GEMS.contains(normalized) || normalized.endsWith(" gem"))
		{
			return "Mine, gem rocks, drops, or rewards";
		}
		if (normalized.endsWith("bone") || normalized.endsWith("bones"))
		{
			return "Monster drops";
		}
		if (FISH_AND_FOOD.contains(normalized) || normalized.startsWith("raw "))
		{
			return "Fishing, cooking, shops, or drops";
		}
		if (normalized.endsWith("roots"))
		{
			return "Farming, tree roots, or item lookup sources";
		}
		if (normalized.equals("coconut milk"))
		{
			return "Fill a vial from a coconut";
		}
		if (normalized.endsWith("(unf)") || normalized.endsWith(" potion unf") || normalized.endsWith("unfinished potion"))
		{
			return "Make with Herblore from a herb and vial";
		}
		if (normalized.contains("weapon poison"))
		{
			return "Make with Herblore or check item lookup";
		}
		if (normalized.equals("amethyst") || normalized.equals("amethyst arrowtips"))
		{
			return "Mine amethyst or craft from amethyst";
		}
		if (normalized.equals("arrow shaft") || normalized.equals("arrow shafts"))
		{
			return "Fletch from logs or obtain from shops/rewards";
		}
		if (normalized.equals("feather") || normalized.equals("feathers"))
		{
			return "Shops, bird drops, or rewards";
		}
		if (isLikelyTool(normalized))
		{
			return "Tool from shops, spawns, or your toolkit";
		}

		return "Use item lookup for sources";
	}

	private static boolean isTradeFriendly(String normalized)
	{
		return HERBS.contains(normalized) || normalized.matches(".*\\bbar$") || normalized.matches(".*\\bore$")
			|| GEMS.contains(normalized) || normalized.endsWith(" gem") || normalized.matches(".*\\blogs?$")
			|| FISH_AND_FOOD.contains(normalized) || normalized.startsWith("raw ");
	}

	private static String tradeHint(String normalized)
	{
		if (HERBS.contains(normalized))
		{
			return "Grand Exchange, farming, herb drops, or herb packs";
		}
		if (normalized.matches(".*\\bbar$"))
		{
			return "Grand Exchange, smithing, drops, or rewards";
		}
		if (normalized.matches(".*\\bore$"))
		{
			return "Grand Exchange, mining, drops, or rewards";
		}
		if (normalized.matches(".*\\blogs?$"))
		{
			return "Grand Exchange, trees, PvM, or rewards";
		}
		if (GEMS.contains(normalized) || normalized.endsWith(" gem"))
		{
			return "Grand Exchange, mining, gem rocks, drops, or rewards";
		}
		return "Grand Exchange, skilling, shops, or drops";
	}

	private static String barHint(String normalized)
	{
		if (normalized.equals("runite bar"))
		{
			return "Smith from runite ore + coal, or obtain from drops/rewards";
		}
		if (normalized.equals("adamantite bar"))
		{
			return "Smith from adamantite ore + coal, or obtain from drops/rewards";
		}
		if (normalized.equals("mithril bar"))
		{
			return "Smith from mithril ore + coal, or obtain from drops/rewards";
		}
		if (normalized.equals("steel bar"))
		{
			return "Smith from iron ore + coal, or obtain from drops/rewards";
		}
		if (normalized.equals("iron bar"))
		{
			return "Smith from iron ore, or obtain from drops/rewards";
		}
		if (normalized.equals("bronze bar"))
		{
			return "Smith from copper + tin ore, or obtain from drops/rewards";
		}
		return "Smith from ore, or obtain from drops/rewards";
	}

	private static boolean isLikelyTool(String normalized)
	{
		return normalized.equals("hammer") || normalized.equals("chisel") || normalized.equals("knife")
			|| normalized.equals("pestle and mortar") || normalized.equals("needle")
			|| normalized.equals("anvil") || normalized.equals("furnace") || normalized.equals("range");
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ENGLISH)
			.replaceAll("[_\\s]+", " ")
			.replaceAll("\\s+\\((unf)\\)$", "($1)");
	}
}

package com.wikiitemhelper;

import java.util.List;
import java.util.Locale;

public class WikiItemResult
{
	private static final BestSourceBuilder BEST_SOURCE_BUILDER = new BestSourceBuilder();
	private static final MaterialsChecklistBuilder MATERIALS_CHECKLIST_BUILDER = new MaterialsChecklistBuilder();

	private final String title;
	private final String pageUrl;
	private final WikiItemSummary summary;

	public WikiItemResult(String title, String pageUrl, WikiItemSummary summary)
	{
		this.title = title;
		this.pageUrl = pageUrl;
		this.summary = summary;
	}

	public static WikiItemResult notFound(String title)
	{
		return new WikiItemResult(title, null, WikiItemSummary.empty());
	}

	public String getPageUrl()
	{
		return pageUrl;
	}

	public String getTitle()
	{
		return title;
	}

	public WikiItemSummary getSummary()
	{
		return summary;
	}

	public String toDisplayText()
	{
		return toDisplayText(false, null);
	}

	public String toDisplayText(boolean ironmanMode, List<SourceLocation> sourceLocations)
	{
		StringBuilder text = new StringBuilder();
		text.append(title).append("\n\n");
		if (!summary.isStructuredDataFound())
		{
			text.append("Raw wiki lookup succeeded, but no structured sources were found.\n\n");
		}
		if (!WikiItemSummary.NO_CLEAR_DATA_FOUND.equals(summary.getHighAlch()))
		{
			text.append("High alch: ").append(summary.getHighAlch()).append("\n\n");
		}

		BestSourceBuilder.BestSourceResult bestSources = BEST_SOURCE_BUILDER.buildResult(summary, title, ironmanMode);
		BestSourceBuilder.CreationSplit creationSplit = BestSourceBuilder.splitCreation(summary.getCreation(), title, ironmanMode);
		String bestSourcesText = bestSources.toDisplayText();
		if (!bestSourcesText.isEmpty())
		{
			text.append(bestSourcesText).append("\n\n");
		}
		appendMaterialsChecklist(text, MATERIALS_CHECKLIST_BUILDER.build(title, summary.getCreationRecipes(), summary.getCreation()));

		if (ironmanMode)
		{
			text.append("Ironman sources:\n").append(filterIronman(summary.getSources())).append("\n\n");
			appendDrops(text, "Other drops:", filterIronman(summary.getDrops()), summary.getDropSources(), bestSources);
			appendSectionIfUseful(text, "Other shops:", BestSourceBuilder.removeBestShops(summary.getShops(), bestSources, true));
			appendSectionIfUseful(text, "Other creation / made by:", BestSourceBuilder.removeBestCreation(summary.getCreation(), bestSources, title, true));
			appendVariantSummary(text, creationSplit);
			text.append("Summary:\n").append(filterIronman(summary.getGeneralSummary()));
		}
		else
		{
			text.append("Summary:\n").append(summary.getGeneralSummary()).append("\n\n");
			appendSectionIfUseful(text, "Other creation / made by:", BestSourceBuilder.removeBestCreation(summary.getCreation(), bestSources, title, false));
			appendVariantSummary(text, creationSplit);
			text.append("Item sources / obtained from:\n").append(summary.getSources()).append("\n\n");
			appendSectionIfUseful(text, "Other shops:", BestSourceBuilder.removeBestShops(summary.getShops(), bestSources, false));
			appendDrops(text, "Other drops:", summary.getDrops(), summary.getDropSources(), bestSources);
		}

		if (sourceLocations != null && !sourceLocations.isEmpty())
		{
			text.append("\n\nKnown locations:");
			for (SourceLocation sourceLocation : sourceLocations)
			{
				text.append("\n").append(sourceLocation.getName()).append(": ").append(sourceLocation.getDescription());
			}
		}

		return text.toString();
	}

	private static void appendSectionIfUseful(StringBuilder text, String heading, String body)
	{
		if (body == null || WikiItemSummary.NO_CLEAR_DATA_FOUND.equals(body))
		{
			return;
		}

		text.append(heading).append("\n").append(body).append("\n\n");
	}

	private static void appendVariantSummary(StringBuilder text, BestSourceBuilder.CreationSplit creationSplit)
	{
		if (creationSplit.hasVariantRecipes())
		{
			text.append("Variant recipes available: ").append(creationSplit.getVariantRecipes().size()).append("\n\n");
		}
	}

	private static void appendMaterialsChecklist(StringBuilder text, MaterialsChecklistBuilder.MaterialsChecklist checklist)
	{
		if (checklist.isEmpty())
		{
			return;
		}

		text.append("Materials checklist:\n\n");
		List<MaterialsChecklistBuilder.RecipeChecklist> recipes = checklist.getRecipes();
		appendRecipeChecklist(text, recipes.get(0), recipes.size() == 1 ? "Recipe" : "Recipe 1");
		if (recipes.size() > 1)
		{
			text.append("Other recipes available: ").append(recipes.size() - 1).append("\n");
		}
		text.append("\n");
	}

	private static void appendRecipeChecklist(StringBuilder text, MaterialsChecklistBuilder.RecipeChecklist recipe, String label)
	{
		text.append(label);
		if (!recipe.getTitle().isEmpty())
		{
			text.append(": ").append(recipe.getTitle());
		}
		text.append("\n");
		for (MaterialsChecklistBuilder.ChecklistEntry entry : recipe.getEntries())
		{
			text.append("[ ] ").append(entry.toPlainText()).append("\n");
		}
	}

	private static void appendDrops(StringBuilder text, String heading, String dropsText, List<DropSource> dropSources, BestSourceBuilder.BestSourceResult bestSources)
	{
		if (dropSources == null || dropSources.isEmpty())
		{
			text.append(heading).append("\n").append(dropsText).append("\n\n");
			return;
		}

		List<DropSource> remainingDrops = BestSourceBuilder.removeBestDropSources(dropSources, bestSources);
		text.append(heading).append("\n");
		if (remainingDrops.isEmpty())
		{
			text.append("No additional drops found\n\n");
			return;
		}

		for (int i = 0; i < remainingDrops.size(); i++)
		{
			if (i > 0)
			{
				text.append("\n\n");
			}
			text.append(remainingDrops.get(i).getDisplayText());
		}
		text.append("\n\n");
	}

	private static String filterIronman(String value)
	{
		if (value == null || WikiItemSummary.NO_CLEAR_DATA_FOUND.equals(value))
		{
			return WikiItemSummary.NO_CLEAR_DATA_FOUND;
		}

		StringBuilder filtered = new StringBuilder();
		for (String line : value.split("\\R"))
		{
			String normalized = line.toLowerCase(Locale.ENGLISH);
			if (normalized.contains("grand exchange") || normalized.contains("tradeable")
				|| normalized.contains("trade with") || normalized.contains("traded with")
				|| normalized.contains("buy from other players") || normalized.contains("sold by other players"))
			{
				continue;
			}

			if (filtered.length() > 0)
			{
				filtered.append('\n');
			}
			filtered.append(line);
		}

		String result = filtered.toString().trim();
		return result.isEmpty() ? WikiItemSummary.NO_CLEAR_DATA_FOUND : result;
	}
}

