package com.wikiitemhelper;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ItemSearchSelector
{
	private static final Logger log = LoggerFactory.getLogger(ItemSearchSelector.class);
	private static final int EXACT_SCORE = 1000;
	private static final int OPTIONAL_POTION_EXACT_SCORE = 950;
	private static final int STARTS_WITH_SCORE = 700;
	private static final int CONTAINS_WORDS_SCORE = 500;
	private static final String[] VARIANT_WORDS = {"divine", "ornament", "ornament kit", "trimmed", "cosmetic"};

	public SearchDecision decide(String rawQuery, List<String> candidateTitles)
	{
		String normalizedQuery = normalize(rawQuery);
		String queryWithoutPotion = removeTrailingPotion(normalizedQuery);
		log.debug("WikiItemHelper item search raw query: '{}'", rawQuery);
		log.debug("WikiItemHelper item search normalized query: '{}'", normalizedQuery);
		log.debug("WikiItemHelper item search candidate titles: {}", candidateTitles);

		List<ScoredCandidate> scoredCandidates = new ArrayList<>();
		for (String title : candidateTitles)
		{
			ScoredCandidate scoredCandidate = score(rawQuery, normalizedQuery, queryWithoutPotion, title);
			if (scoredCandidate.score > 0)
			{
				scoredCandidates.add(scoredCandidate);
			}
			log.debug(
				"WikiItemHelper item search candidate score: title='{}', normalized='{}', score={}, exact={}, optionalPotionExact={}, variantPenalty={}",
				title,
				scoredCandidate.normalizedTitle,
				scoredCandidate.score,
				scoredCandidate.exact,
				scoredCandidate.optionalPotionExact,
				scoredCandidate.variantPenalty
			);
		}

		scoredCandidates.sort(Comparator
			.comparingInt((ScoredCandidate candidate) -> candidate.score).reversed()
			.thenComparingInt(candidate -> candidate.variantPenalty)
			.thenComparing(candidate -> candidate.title.toLowerCase(Locale.ENGLISH)));

		if (scoredCandidates.isEmpty())
		{
			log.debug("WikiItemHelper item search final decision: selection list, no scored candidates");
			return SearchDecision.selectionList(Collections.emptyList());
		}

		ScoredCandidate best = scoredCandidates.get(0);
		boolean tiedTop = scoredCandidates.size() > 1 && scoredCandidates.get(1).score == best.score
			&& scoredCandidates.get(1).variantPenalty == best.variantPenalty;
		if (!tiedTop && (best.exact || best.optionalPotionExact))
		{
			log.debug("WikiItemHelper item search final decision: direct open '{}'", best.title);
			return SearchDecision.directOpen(best.title);
		}

		List<String> orderedTitles = new ArrayList<>();
		for (ScoredCandidate scoredCandidate : scoredCandidates)
		{
			orderedTitles.add(scoredCandidate.title);
		}
		log.debug("WikiItemHelper item search final decision: selection list {}", orderedTitles);
		return SearchDecision.selectionList(orderedTitles);
	}

	private static ScoredCandidate score(String rawQuery, String normalizedQuery, String queryWithoutPotion, String title)
	{
		String normalizedTitle = normalize(title);
		String titleWithoutPotion = removeTrailingPotion(normalizedTitle);
		boolean queryMentionsVariant = mentionsVariant(normalizedQuery);
		boolean titleMentionsVariant = mentionsVariant(normalizedTitle);
		int variantPenalty = titleMentionsVariant && !queryMentionsVariant ? 60 : 0;

		if (normalizedTitle.equals(normalizedQuery))
		{
			return new ScoredCandidate(title, normalizedTitle, EXACT_SCORE - variantPenalty, true, false, variantPenalty);
		}

		if (!queryWithoutPotion.isEmpty() && (normalizedTitle.equals(queryWithoutPotion) || titleWithoutPotion.equals(normalizedQuery)
			|| titleWithoutPotion.equals(queryWithoutPotion)))
		{
			return new ScoredCandidate(title, normalizedTitle, OPTIONAL_POTION_EXACT_SCORE - variantPenalty, false, true, variantPenalty);
		}

		int score = 0;
		if (normalizedTitle.startsWith(normalizedQuery) || (!queryWithoutPotion.isEmpty() && normalizedTitle.startsWith(queryWithoutPotion)))
		{
			score = STARTS_WITH_SCORE;
		}
		else if (containsAllQueryWords(normalizedTitle, normalizedQuery))
		{
			score = CONTAINS_WORDS_SCORE;
		}

		return new ScoredCandidate(title, normalizedTitle, Math.max(0, score - variantPenalty), false, false, variantPenalty);
	}

	static String normalize(String value)
	{
		return value == null ? "" : value.toLowerCase(Locale.ENGLISH)
			.replaceAll("[^a-z0-9+]+", " ")
			.replaceAll("\\s+", " ")
			.trim();
	}

	static String removeTrailingPotion(String normalizedValue)
	{
		return normalizedValue == null ? "" : normalizedValue.replaceFirst("\\s+potion$", "").trim();
	}

	private static boolean containsAllQueryWords(String normalizedTitle, String normalizedQuery)
	{
		for (String token : normalizedQuery.split("\\s+"))
		{
			if (!token.isEmpty() && !normalizedTitle.contains(token))
			{
				return false;
			}
		}

		return true;
	}

	private static boolean mentionsVariant(String normalizedValue)
	{
		for (String variantWord : VARIANT_WORDS)
		{
			if (normalizedValue.contains(variantWord))
			{
				return true;
			}
		}

		return false;
	}

	private static class ScoredCandidate
	{
		private final String title;
		private final String normalizedTitle;
		private final int score;
		private final boolean exact;
		private final boolean optionalPotionExact;
		private final int variantPenalty;

		private ScoredCandidate(String title, String normalizedTitle, int score, boolean exact, boolean optionalPotionExact, int variantPenalty)
		{
			this.title = title;
			this.normalizedTitle = normalizedTitle;
			this.score = score;
			this.exact = exact;
			this.optionalPotionExact = optionalPotionExact;
			this.variantPenalty = variantPenalty;
		}
	}

	public static class SearchDecision
	{
		private final String directOpenTitle;
		private final List<String> selectionTitles;

		private SearchDecision(String directOpenTitle, List<String> selectionTitles)
		{
			this.directOpenTitle = directOpenTitle;
			this.selectionTitles = Collections.unmodifiableList(new ArrayList<>(selectionTitles));
		}

		public static SearchDecision directOpen(String title)
		{
			return new SearchDecision(title, Collections.emptyList());
		}

		public static SearchDecision selectionList(List<String> titles)
		{
			return new SearchDecision(null, titles);
		}

		public boolean shouldDirectOpen()
		{
			return directOpenTitle != null;
		}

		public String getDirectOpenTitle()
		{
			return directOpenTitle;
		}

		public List<String> getSelectionTitles()
		{
			return selectionTitles;
		}
	}
}

