import javax.inject.Singleton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class WikiItemParser
{
	private static final Logger log = LoggerFactory.getLogger(WikiItemParser.class);
	private static final List<String> CREATION_HEADINGS = Arrays.asList("Creation", "Products", "Made by");
	private static final List<String> SOURCE_HEADINGS = Arrays.asList("Obtaining", "Item sources", "Obtained from", "Sources", "Spawns");
	private static final List<String> ITEM_SOURCE_HEADINGS = Arrays.asList("Item sources", "Sources");
	private static final List<String> SPAWN_HEADINGS = Arrays.asList("Spawns");
	private static final List<String> SHOP_HEADINGS = Arrays.asList("Shop locations", "Shops", "Store locations");
	private static final List<String> DROP_HEADINGS = Arrays.asList("Drops", "Drop sources");
	private static final Pattern TEMPLATE_PARAMETER = Pattern.compile("(?m)^\\|\\s*([^=|]+?)\\s*=\\s*(.*?)\\s*$");
	private static final Pattern ITEM_DROPS_TABLE = Pattern.compile("(?is)<table\\b(?=[^>]*class=\"[^\"]*\\bitem-drops\\b[^\"]*\")[^>]*>.*?</table>");
	private static final Pattern TABLE_ROW = Pattern.compile("(?is)<tr\\b[^>]*>.*?</tr>");
	private static final Pattern TABLE_CELL = Pattern.compile("(?is)<t[dh]\\b[^>]*>.*?</t[dh]>");
	private static final Pattern LINK_TITLE = Pattern.compile("(?is)<a\\b[^>]*\\btitle\\s*=\\s*\"([^\"]+)\"[^>]*>");
	private static final Pattern ATTRIBUTE_VALUE = Pattern.compile("(?is)\\b%s\\s*=\\s*\"([^\"]*)\"");
	private static final int MAX_DROPS = 20;
	private static final int MAX_SUMMARY_LENGTH = 700;
	private static final String PESTLE_AND_MORTAR_PLACEHOLDER = "__WIKI_ITEM_HELPER_PESTLE_AND_MORTAR__";

	public WikiItemSummary parse(String pageContent)
	{
		return parse(pageContent, "");
	}

	public WikiItemSummary parse(String pageContent, String renderedHtml)
	{
		String content = pageContent == null ? "" : pageContent;
		String html = renderedHtml == null ? "" : renderedHtml;
		Map<String, String> rawSections = splitSections(content, false);
		Map<String, String> cleanedSections = splitSections(content, true);

		String rawCreation = findFirstRawWithSubsections(content, CREATION_HEADINGS);
		List<CreationRecipe> creationRecipes = parseCreationRecipes(rawCreation);
		String creation = findCreation(creationRecipes, cleanedSections);
		String sources = findSources(rawSections, cleanedSections);
		String shops = findShops(rawSections, cleanedSections);
		DropParseResult dropParseResult = findDrops(rawSections, cleanedSections, html);
		String highAlch = findHighAlch(content);

		return new WikiItemSummary(
			creation,
			sources,
			shops,
			dropParseResult.displayText,
			creationRecipes,
			dropParseResult.dropSources,
			extractLeadSummary(content),
			highAlch,
			hasStructuredData(creation, sources, shops, dropParseResult.displayText)
		);
	}

	private static String findHighAlch(String content)
	{
		for (String template : extractTemplates(content, "Infobox Item"))
		{
			Map<String, String> params = parseTemplateParameters(template);
			String highAlch = firstUseful(params.get("highalch"), params.get("high alch"), params.get("high_alch"));
			if (highAlch != null)
			{
				return clean(highAlch);
			}
		}

		return "";
	}

	private static Map<String, String> splitSections(String content, boolean clean)
	{
		Map<String, String> sections = new LinkedHashMap<>();
		String currentHeading = "Lead";
		StringBuilder currentBody = new StringBuilder();

		for (String line : content.split("\\R"))
		{
			String heading = parseHeading(line);
			if (heading != null)
			{
				sections.put(currentHeading, clean ? clean(currentBody.toString()) : currentBody.toString().trim());
				currentHeading = heading;
				currentBody.setLength(0);
			}
			else
			{
				currentBody.append(line).append('\n');
			}
		}

		sections.put(currentHeading, clean ? clean(currentBody.toString()) : currentBody.toString().trim());
		return sections;
	}

	private static String parseHeading(String line)
	{
		String trimmed = line.trim();
		if (!trimmed.startsWith("=") || !trimmed.endsWith("="))
		{
			return null;
		}

		String heading = trimmed.replace("=", "").trim();
		return heading.isEmpty() ? null : heading;
	}

	private static String findFirstRawWithSubsections(String content, List<String> headings)
	{
		String[] lines = (content == null ? "" : content).split("\\R");
		StringBuilder section = null;
		int targetLevel = 0;

		for (String line : lines)
		{
			Heading heading = parseHeadingWithLevel(line);
			if (heading != null)
			{
				if (section != null && heading.level <= targetLevel)
				{
					return section.toString().trim();
				}

				if (section == null && containsHeading(headings, heading.name))
				{
					section = new StringBuilder();
					targetLevel = heading.level;
					continue;
				}
			}

			if (section != null)
			{
				section.append(line).append('\n');
			}
		}

		if (section != null)
		{
			return section.toString().trim();
		}

		return "";
	}

	private static Heading parseHeadingWithLevel(String line)
	{
		String trimmed = line.trim();
		Matcher matcher = Pattern.compile("^(=+)\\s*(.*?)\\s*\\1$").matcher(trimmed);
		if (!matcher.matches())
		{
			return null;
		}

		String name = matcher.group(2).trim();
		return name.isEmpty() ? null : new Heading(matcher.group(1).length(), name);
	}

	private static boolean containsHeading(List<String> headings, String value)
	{
		for (String heading : headings)
		{
			if (heading.equalsIgnoreCase(value))
			{
				return true;
			}
		}

		return false;
	}

	private static String findCreation(List<CreationRecipe> creationRecipes, Map<String, String> cleanedSections)
	{
		String recipes = describeRecipes(creationRecipes, 3);
		if (!recipes.isEmpty())
		{
			return recipes;
		}

		return findFirstClean(cleanedSections, CREATION_HEADINGS);
	}

	private static String findSources(Map<String, String> rawSections, Map<String, String> cleanedSections)
	{
		String raw = findFirstRaw(rawSections, SOURCE_HEADINGS);
		String cleaned = findFirstClean(cleanedSections, SOURCE_HEADINGS);
		String spawnRaw = raw + "\n" + findFirstRaw(rawSections, SPAWN_HEADINGS);
		String spawns = describeSpawnLocations(spawnRaw);
		String drops = describeDropSourceTemplate(raw);

		List<String> parts = new ArrayList<>();
		addIfUseful(parts, cleaned);
		addIfUseful(parts, spawns);
		addIfUseful(parts, drops);
		return joinOrNoData(parts);
	}

	private static String findShops(Map<String, String> rawSections, Map<String, String> cleanedSections)
	{
		String raw = findFirstRaw(rawSections, SHOP_HEADINGS);
		String shops = describeStoreLocations(raw);
		if (!shops.isEmpty())
		{
			return shops;
		}

		return findFirstClean(cleanedSections, SHOP_HEADINGS);
	}

	private static DropParseResult findDrops(Map<String, String> rawSections, Map<String, String> cleanedSections, String renderedHtml)
	{
		DropParseResult htmlDrops = describeRenderedDropTables(renderedHtml);
		if (!htmlDrops.displayText.isEmpty())
		{
			return htmlDrops;
		}

		String raw = findFirstRaw(rawSections, DROP_HEADINGS);
		String drops = describeDropSourceTemplate(raw);
		if (!drops.isEmpty())
		{
			return DropParseResult.textOnly(drops);
		}

		raw = findFirstRaw(rawSections, ITEM_SOURCE_HEADINGS);
		drops = describeDropSourceTemplate(raw);
		if (!drops.isEmpty())
		{
			return DropParseResult.textOnly(drops);
		}

		return DropParseResult.textOnly(findFirstClean(cleanedSections, DROP_HEADINGS));
	}

	private static String findFirstRaw(Map<String, String> sections, List<String> headings)
	{
		for (String heading : headings)
		{
			for (Map.Entry<String, String> section : sections.entrySet())
			{
				if (section.getKey().equalsIgnoreCase(heading) && !section.getValue().trim().isEmpty())
				{
					return section.getValue();
				}
			}
		}

		return "";
	}

	private static String findFirstClean(Map<String, String> sections, List<String> headings)
	{
		for (String heading : headings)
		{
			for (Map.Entry<String, String> section : sections.entrySet())
			{
				if (section.getKey().equalsIgnoreCase(heading) && !section.getValue().isEmpty())
				{
					return section.getValue();
				}
			}
		}

		return WikiItemSummary.NO_CLEAR_DATA_FOUND;
	}

	private static List<CreationRecipe> parseCreationRecipes(String section)
	{
		List<CreationRecipe> recipes = new ArrayList<>();
		for (String template : extractTemplates(section, "Recipe"))
		{
			Map<String, String> params = parseTemplateParameters(template);
			recipes.add(new CreationRecipe(
				clean(params.get("skill1")),
				clean(params.get("skill1lvl")),
				parseNumberedEntries(params, "mat", "mat"),
				parseNamedEntries(params.get("tools")),
				parseNamedEntries(params.get("facilities")),
				parseNumberedEntries(params, "output", "output"),
				clean(params.get("skill1exp"))
			));
		}

		return recipes;
	}

	private static String describeRecipes(List<CreationRecipe> creationRecipes, int limit)
	{
		List<String> recipes = new ArrayList<>();
		for (CreationRecipe recipe : creationRecipes)
		{
			List<String> parts = new ArrayList<>();
			String skill = recipe.getSkill();
			String level = recipe.getLevel();
			if (skill != null)
			{
				parts.add(level == null ? "Skill: " + skill : "Level " + level + " " + skill);
			}

			String materials = describeEntries(recipe.getMaterials(), "materials");
			addIfUseful(parts, materials);
			String tools = describeEntries(recipe.getTools(), "tools");
			addIfUseful(parts, tools);
			String facilities = describeEntries(recipe.getFacilities(), "facility");
			addIfUseful(parts, facilities);
			String output = describeEntries(recipe.getOutputs(), "output");
			addIfUseful(parts, output);
			if (recipe.getXp() != null)
			{
				parts.add("XP: " + recipe.getXp());
			}

			if (!parts.isEmpty())
			{
				recipes.add(String.join("\n  ", parts));
			}

			if (recipes.size() == limit)
			{
				break;
			}
		}

		return String.join("\n\n", recipes);
	}

	private static List<CreationRecipe.Entry> parseNumberedEntries(Map<String, String> params, String valuePrefix, String quantityPrefix)
	{
		List<CreationRecipe.Entry> values = new ArrayList<>();
		for (int i = 1; i <= 6; i++)
		{
			String value = params.get(valuePrefix + i);
			if (value == null)
			{
				continue;
			}

			String quantity = params.get(quantityPrefix + i + "quantity");
			values.add(new CreationRecipe.Entry(clean(value), clean(quantity)));
		}

		return values;
	}

	private static List<CreationRecipe.Entry> parseNamedEntries(String value)
	{
		List<CreationRecipe.Entry> entries = new ArrayList<>();
		String cleaned = clean(value);
		if (cleaned.isEmpty())
		{
			return entries;
		}

		cleaned = cleaned.replaceAll("(?i)\\bpestle\\s+and\\s+mortar\\b", PESTLE_AND_MORTAR_PLACEHOLDER);
		for (String part : cleaned.split("\\s*(?:,|;|\\band\\b)\\s*"))
		{
			String name = part.trim().replace(PESTLE_AND_MORTAR_PLACEHOLDER, "Pestle and mortar");
			if (!name.isEmpty())
			{
				entries.add(new CreationRecipe.Entry(name, null));
			}
		}

		return entries;
	}

	private static String describeEntries(List<CreationRecipe.Entry> entries, String label)
	{
		List<String> values = new ArrayList<>();
		for (CreationRecipe.Entry entry : entries)
		{
			if (entry.getName() != null)
			{
				values.add((entry.getQuantity() == null ? "" : entry.getQuantity() + " ") + entry.getName());
			}
		}

		return values.isEmpty() ? "" : capitalize(label) + ": " + String.join(", ", values);
	}

	private static String capitalize(String value)
	{
		return value.isEmpty() ? value : value.substring(0, 1).toUpperCase() + value.substring(1);
	}

	private static String describeSpawnLocations(String section)
	{
		List<String> locations = new ArrayList<>();
		for (String template : extractTemplates(section, "ItemSpawnLine"))
		{
			Map<String, String> params = parseTemplateParameters(template);
			String location = params.get("location");
			if (location != null)
			{
				locations.add(clean(location));
			}

			if (locations.size() == 5)
			{
				break;
			}
		}

		return locations.isEmpty() ? "" : "Spawns: " + String.join("; ", locations);
	}

	private static String describeStoreLocations(String section)
	{
		Matcher matcher = Pattern.compile("\\{\\{Store locations list\\|([^}|]+)").matcher(section);
		if (matcher.find())
		{
			return "Shop location table found on wiki for " + clean(matcher.group(1)) + ".";
		}

		return "";
	}

	private static String describeDropSourceTemplate(String section)
	{
		Matcher matcher = Pattern.compile("\\{\\{Drop sources\\|([^}|]+)").matcher(section);
		if (matcher.find())
		{
			return "Drop source table found on wiki for " + clean(matcher.group(1)) + ".";
		}

		return "";
	}

	private static DropParseResult describeRenderedDropTables(String renderedHtml)
	{
		if (renderedHtml.isEmpty())
		{
			log.debug("WikiItemHelper found 0 rendered drop rows");
			return DropParseResult.empty();
		}

		List<String> drops = new ArrayList<>();
		List<DropSource> dropSources = new ArrayList<>();
		int totalRows = 0;
		Matcher tableMatcher = ITEM_DROPS_TABLE.matcher(renderedHtml);
		while (tableMatcher.find())
		{
			Matcher rowMatcher = TABLE_ROW.matcher(tableMatcher.group());
			while (rowMatcher.find())
			{
				String row = rowMatcher.group();
				if (row.toLowerCase().contains("<th"))
				{
					continue;
				}

				List<String> cells = extractCells(row);
				if (cells.isEmpty())
				{
					continue;
				}

				totalRows++;
				if (drops.size() < MAX_DROPS)
				{
					String formattedDrop = formatDropRow(cells);
					drops.add(formattedDrop);
					String sourceName = getCell(cells, 0);
					if (!sourceName.isEmpty())
					{
						dropSources.add(new DropSource(sourceName, extractSourcePageTitle(row, sourceName), formattedDrop));
					}
				}
			}

			if (!drops.isEmpty())
			{
				break;
			}
		}

		log.debug("WikiItemHelper found {} rendered drop rows", totalRows);
		if (drops.isEmpty())
		{
			return DropParseResult.empty();
		}

		if (totalRows > drops.size())
		{
			drops.add("...and " + (totalRows - drops.size()) + " more drops.");
		}

		return new DropParseResult(String.join("\n\n", drops), dropSources);
	}

	private static String extractSourcePageTitle(String row, String fallback)
	{
		Matcher matcher = LINK_TITLE.matcher(row);
		return matcher.find() ? decodeHtml(matcher.group(1)) : fallback;
	}

	private static List<String> extractCells(String row)
	{
		List<String> cells = new ArrayList<>();
		Matcher cellMatcher = TABLE_CELL.matcher(row);
		while (cellMatcher.find())
		{
			String cell = cellMatcher.group();
			String rarity = findAttribute(cell, "data-drop-oneover");
			if (rarity == null)
			{
				rarity = findAttribute(cell, "data-drop-fraction");
			}

			cells.add(rarity == null ? cleanHtml(cell) : decodeHtml(rarity));
		}

		return cells;
	}

	private static String formatDropRow(List<String> cells)
	{
		String source = getCell(cells, 0);
		String level = getCell(cells, 1);
		String quantity = getCell(cells, 2);
		String rarity = getCell(cells, 3);
		StringBuilder drop = new StringBuilder();
		if (!source.isEmpty())
		{
			drop.append(source);
		}
		else
		{
			drop.append("Unknown drop source");
		}
		if (!level.isEmpty())
		{
			drop.append("\n  Level: ").append(level);
		}
		if (!quantity.isEmpty())
		{
			drop.append("\n  Qty: ").append(quantity);
		}
		if (!rarity.isEmpty())
		{
			drop.append("\n  Rarity: ").append(rarity);
		}

		return drop.toString();
	}

	private static String getCell(List<String> cells, int index)
	{
		return cells.size() > index ? cells.get(index) : "";
	}

	private static String findAttribute(String html, String attributeName)
	{
		Pattern pattern = Pattern.compile(String.format(ATTRIBUTE_VALUE.pattern(), Pattern.quote(attributeName)));
		Matcher matcher = pattern.matcher(html);
		return matcher.find() ? matcher.group(1) : null;
	}

	private static String cleanHtml(String html)
	{
		return decodeHtml(html
			.replaceAll("(?is)<script\\b.*?</script>", "")
			.replaceAll("(?is)<style\\b.*?</style>", "")
			.replaceAll("(?is)<img\\b[^>]*>", "")
			.replaceAll("(?is)<[^>]+>", " ")
			.replaceAll("\\s+", " ")
			.trim());
	}

	private static String decodeHtml(String text)
	{
		return text
			.replace("&nbsp;", " ")
			.replace("&#160;", " ")
			.replace("&amp;", "&")
			.replace("&lt;", "<")
			.replace("&gt;", ">")
			.replace("&quot;", "\"")
			.replace("&#039;", "'")
			.replace("&#39;", "'")
			.replace("&times;", "x")
			.replace("×", "x")
			.replaceAll("\\s+", " ")
			.trim();
	}

	private static String extractLeadSummary(String content)
	{
		Map<String, String> sections = splitSections(content, false);
		String lead = sections.get("Lead");
		if (lead == null || lead.trim().isEmpty())
		{
			return WikiItemSummary.NO_CLEAR_DATA_FOUND;
		}

		lead = clean(removeTopLevelTemplates(lead));
		return lead.length() <= MAX_SUMMARY_LENGTH ? lead : lead.substring(0, MAX_SUMMARY_LENGTH) + "...";
	}

	private static boolean hasStructuredData(String creation, String sources, String shops, String drops)
	{
		return isUseful(creation) || isUseful(sources) || isUseful(shops) || isUseful(drops);
	}

	private static boolean isUseful(String value)
	{
		return value != null && !value.trim().isEmpty() && !WikiItemSummary.NO_CLEAR_DATA_FOUND.equals(value);
	}

	private static void addNamedParam(List<String> parts, Map<String, String> params, String name, String label)
	{
		String value = params.get(name);
		if (value != null)
		{
			parts.add(label + ": " + clean(value));
		}
	}

	private static void addIfUseful(List<String> parts, String value)
	{
		if (isUseful(value))
		{
			parts.add(value);
		}
	}

	private static String firstUseful(String... values)
	{
		for (String value : values)
		{
			if (value != null && !value.trim().isEmpty())
			{
				return value;
			}
		}

		return null;
	}

	private static String joinOrNoData(List<String> parts)
	{
		return parts.isEmpty() ? WikiItemSummary.NO_CLEAR_DATA_FOUND : String.join("\n", parts);
	}

	private static List<String> extractTemplates(String text, String templateName)
	{
		List<String> templates = new ArrayList<>();
		String marker = "{{" + templateName;
		int index = 0;
		while (index < text.length())
		{
			int start = text.indexOf(marker, index);
			if (start < 0)
			{
				break;
			}

			int depth = 0;
			for (int i = start; i < text.length() - 1; i++)
			{
				String pair = text.substring(i, i + 2);
				if ("{{".equals(pair))
				{
					depth++;
					i++;
				}
				else if ("}}".equals(pair))
				{
					depth--;
					i++;
					if (depth == 0)
					{
						templates.add(text.substring(start, i + 1));
						index = i + 1;
						break;
					}
				}
			}

			if (start == index)
			{
				index = start + marker.length();
			}
		}

		return templates;
	}

	private static Map<String, String> parseTemplateParameters(String template)
	{
		Map<String, String> params = new LinkedHashMap<>();
		String body = stripOuterTemplateBraces(template);
		Matcher matcher = TEMPLATE_PARAMETER.matcher(body);
		while (matcher.find())
		{
			params.put(matcher.group(1).trim(), matcher.group(2).trim());
		}

		for (String part : splitTopLevel(body, '|'))
		{
			int equalsIndex = part.indexOf('=');
			if (equalsIndex <= 0)
			{
				continue;
			}

			String name = part.substring(0, equalsIndex).trim();
			String value = part.substring(equalsIndex + 1).trim();
			if (!name.isEmpty() && !params.containsKey(name))
			{
				params.put(name, value);
			}
		}

		return params;
	}

	private static String stripOuterTemplateBraces(String template)
	{
		String trimmed = template == null ? "" : template.trim();
		if (trimmed.startsWith("{{") && trimmed.endsWith("}}"))
		{
			return trimmed.substring(2, trimmed.length() - 2);
		}

		return trimmed;
	}

	private static List<String> splitTopLevel(String text, char separator)
	{
		List<String> parts = new ArrayList<>();
		StringBuilder current = new StringBuilder();
		int templateDepth = 0;
		int linkDepth = 0;

		for (int i = 0; i < text.length(); i++)
		{
			if (i < text.length() - 1)
			{
				String pair = text.substring(i, i + 2);
				if ("{{".equals(pair))
				{
					templateDepth++;
					current.append(pair);
					i++;
					continue;
				}
				if ("}}".equals(pair))
				{
					templateDepth--;
					current.append(pair);
					i++;
					continue;
				}
				if ("[[".equals(pair))
				{
					linkDepth++;
					current.append(pair);
					i++;
					continue;
				}
				if ("]]".equals(pair))
				{
					linkDepth--;
					current.append(pair);
					i++;
					continue;
				}
			}

			char character = text.charAt(i);
			if (character == separator && templateDepth <= 1 && linkDepth == 0)
			{
				parts.add(current.toString());
				current.setLength(0);
			}
			else
			{
				current.append(character);
			}
		}

		parts.add(current.toString());
		return parts;
	}

	private static String removeTopLevelTemplates(String text)
	{
		StringBuilder cleaned = new StringBuilder();
		int templateDepth = 0;

		for (int i = 0; i < text.length(); i++)
		{
			if (i < text.length() - 1)
			{
				String pair = text.substring(i, i + 2);
				if ("{{".equals(pair))
				{
					templateDepth++;
					i++;
					continue;
				}
				if ("}}".equals(pair) && templateDepth > 0)
				{
					templateDepth--;
					i++;
					continue;
				}
			}

			if (templateDepth == 0)
			{
				cleaned.append(text.charAt(i));
			}
		}

		return cleaned.toString();
	}

	private static String clean(String wikiText)
	{
		if (wikiText == null)
		{
			return "";
		}

		return wikiText
			.replaceAll("(?s)<!--.*?-->", "")
			.replaceAll("\\[\\[File:[^]]+]]", "")
			.replaceAll("\\{\\{FloorNumber\\|uk=([^}|]+)}}", "$1")
			.replaceAll("\\{\\{SCP\\|([^}|]+)\\|([^}|]+)}}", "$1 $2")
			.replaceAll("\\{\\{[^{}]*}}", "")
			.replaceAll("\\[\\[([^]|]+)\\|([^]]+)]]", "$2")
			.replaceAll("\\[\\[([^]]+)]]", "$1")
			.replaceAll("'''", "")
			.replaceAll("''", "")
			.replaceAll("<[^>]+>", "")
			.replaceAll("\\s+", " ")
			.trim();
	}

	private static class DropParseResult
	{
		private final String displayText;
		private final List<DropSource> dropSources;

		private DropParseResult(String displayText, List<DropSource> dropSources)
		{
			this.displayText = displayText;
			this.dropSources = dropSources;
		}

		private static DropParseResult empty()
		{
			return textOnly("");
		}

		private static DropParseResult textOnly(String displayText)
		{
			return new DropParseResult(displayText, Collections.emptyList());
		}
	}

	private static class Heading
	{
		private final int level;
		private final String name;

		private Heading(int level, String name)
		{
			this.level = level;
			this.name = name;
		}
	}
}

