	private static void scrollResultArea(MouseWheelEvent event)
	{
		Component source = (Component) event.getSource();
		JScrollPane scrollPane = findScrollableAncestorScrollPane(source);
		if (scrollPane == null)
		{
			log.warn("No scrollable ancestor JScrollPane found for result body mouse wheel event");
			return;
		}

		JScrollBar verticalScrollBar = scrollPane.getVerticalScrollBar();
		int oldValue = verticalScrollBar.getValue();
		int minimum = verticalScrollBar.getMinimum();
		int visible = verticalScrollBar.getVisibleAmount();
		int maximum = verticalScrollBar.getMaximum() - visible;
		int unitIncrement = verticalScrollBar.getUnitIncrement(event.getPreciseWheelRotation() < 0 ? -1 : 1);
		int amount = (int) Math.round(event.getPreciseWheelRotation() * RESULT_SCROLL_UNIT_INCREMENT);
		int newValue = Math.max(minimum, Math.min(maximum, oldValue + amount));

		verticalScrollBar.setValue(newValue);
		int actualValue = verticalScrollBar.getValue();
		log.debug(
			"Result body wheel: rotation={}, old={}, new={}, actual={}, min={}, max={}, visible={}, unitIncrement={}, pane={}, view={}",
			event.getPreciseWheelRotation(),
			oldValue,
			newValue,
			actualValue,
			minimum,
			maximum,
			visible,
			unitIncrement,
			scrollPane.getClass().getName(),
			scrollPane.getViewport().getView() == null ? "null" : scrollPane.getViewport().getView().getClass().getName()
		);

		if (actualValue != oldValue)
		{
			event.consume();
		}
	}

	private static JScrollPane findScrollableAncestorScrollPane(Component source)
	{
		JScrollPane scrollablePane = null;
		Component current = source;
		while (current != null)
		{
			if (current instanceof JScrollPane)
			{
				JScrollPane pane = (JScrollPane) current;
				JScrollBar bar = pane.getVerticalScrollBar();
				int visible = bar.getVisibleAmount();
				int maximum = bar.getMaximum() - visible;
				log.debug(
					"Ancestor JScrollPane: pane={}, view={}, value={}, min={}, max={}, visible={}",
					pane.getClass().getName(),
					pane.getViewport().getView() == null ? "null" : pane.getViewport().getView().getClass().getName(),
					bar.getValue(),
					bar.getMinimum(),
					maximum,
					visible
				);

				if (maximum > bar.getMinimum())
				{
					scrollablePane = pane;
				}
			}

			current = current.getParent();
		}

		return scrollablePane;
	}

	private void search()
	{
		String itemName = searchField.getText().trim();
		if (itemName.isEmpty())
		{
			showText("Enter an item name first.");
			return;
		}

		addRecentSearch(itemName);
		selectedFromSearchResults = false;
		backButton.setEnabled(false);
		backButton.setVisible(false);
		searchButton.setEnabled(false);
		openWikiButton.setEnabled(false);
		showText("Searching...");

		new SwingWorker<SearchOutcome, Void>()
		{
			@Override
			protected SearchOutcome doInBackground() throws IOException
			{
				List<String> itemNames = wikiClient.searchItems(itemName);
				ItemSearchSelector.SearchDecision searchDecision = ITEM_SEARCH_SELECTOR.decide(itemName, itemNames);
				if (searchDecision.shouldDirectOpen())
				{
					String selectedItemName = searchDecision.getDirectOpenTitle();
					log.debug("WikiItemHelper selected item name: {}", selectedItemName);
					return SearchOutcome.item(wikiClient.lookupItem(selectedItemName));
				}

				return SearchOutcome.itemList(itemName, searchDecision.getSelectionTitles());
			}

			@Override
			protected void done()
			{
				SwingUtilities.invokeLater(() ->
				{
					searchButton.setEnabled(true);
					try
					{
						SearchOutcome outcome = get();
						if (outcome.result != null)
						{
							currentResult = outcome.result;
							renderCurrentResult();
							openWikiButton.setEnabled(currentResult.getPageUrl() != null);
						}
						else
						{
							currentResult = null;
							openWikiButton.setEnabled(false);
							showItemSearchResults(outcome.searchTerm, outcome.itemNames);
						}
					}
					catch (Exception ex)
					{
						currentResult = null;
						showText("Unable to load wiki data. Try again later.");
					}
				});
			}
		}.execute();
	}

	void lookupItemFromMenu(String itemName)
