	private void selectItem(String itemName)
	{
		log.debug("WikiItemHelper selected item name: {}", itemName);
		addRecentSearch(itemName);
		selectedFromSearchResults = lastSearchItemNames.contains(itemName);
		backButton.setEnabled(selectedFromSearchResults);
		backButton.setVisible(selectedFromSearchResults);
		searchButton.setEnabled(false);
		openWikiButton.setEnabled(false);
		showText("Loading " + itemName + "...");

		new SwingWorker<WikiItemResult, Void>()
		{
			private boolean loadedFromCache;

			@Override
			protected WikiItemResult doInBackground() throws IOException
			{
				loadedFromCache = wikiClient.isItemCached(itemName);
				return wikiClient.lookupItem(itemName);
			}

			@Override
			protected void done()
			{
				SwingUtilities.invokeLater(() ->
				{
					searchButton.setEnabled(true);
					try
					{
						currentResult = get();
						renderCurrentResult();
						if (loadedFromCache)
						{
							addStatusLine("Loaded from cache.");
						}
						openWikiButton.setEnabled(currentResult.getPageUrl() != null);
					}
					catch (Exception ex)
					{
						currentResult = null;
						showText("Unable to load wiki data. Try again later.");
					}
				});
			}
		}.execute();
	}

	private void showText(String text)
	{
		resultContainer.removeAll();
		resultArea.setText(text);
		resultArea.setCaretPosition(0);
		addMouseWheelListenerRecursively(resultArea, resultWheelListener);
		resultContainer.add(resultArea, BorderLayout.CENTER);
		resultContainer.revalidate();
		resultContainer.repaint();
		resetAncestorScrollPanesToTop(resultArea);
		resetAncestorScrollPanesToTop(this);
	}

	private void addStatusLine(String text)
	{
		if (resultContainer.getComponentCount() == 0 || !(resultContainer.getComponent(0) instanceof JPanel))
		{
			return;
		}

		JPanel resultPanel = (JPanel) resultContainer.getComponent(0);
		addTextBlock(resultPanel, "\n" + text);
		resultPanel.revalidate();
		resultPanel.repaint();
	}

	private static void addMouseWheelListenerRecursively(Component component, MouseWheelListener listener)
	{
		if (!hasMouseWheelListener(component, listener))
		{
			component.addMouseWheelListener(listener);
		}

		if (!(component instanceof Container))
		{
			return;
		}

		for (Component child : ((Container) component).getComponents())
		{
			addMouseWheelListenerRecursively(child, listener);
		}
	}

	private static boolean hasMouseWheelListener(Component component, MouseWheelListener listener)
	{
		for (MouseWheelListener existingListener : component.getMouseWheelListeners())
		{
			if (existingListener == listener)
			{
				return true;
			}
		}

		return false;
	}

	private static void resetAncestorScrollPanesToTop(Component source)
	{
		SwingUtilities.invokeLater(() ->
		{
			resetAncestorScrollPanesNow(source);
			SwingUtilities.invokeLater(() -> resetAncestorScrollPanesNow(source));
		});
	}

	private static void resetAncestorScrollPanesNow(Component source)
	{
		Component current = source;
		while (current != null)
		{
			if (current instanceof JScrollPane)
			{
				JScrollBar verticalScrollBar = ((JScrollPane) current).getVerticalScrollBar();
				verticalScrollBar.setValue(verticalScrollBar.getMinimum());
			}

			current = current.getParent();
		}
	}

	private void showItemSearchResults(String searchTerm, List<String> itemNames)
	{
		lastSearchTerm = searchTerm;
		lastSearchItemNames = new ArrayList<>(itemNames);
		selectedFromSearchResults = false;
		backButton.setEnabled(false);
		backButton.setVisible(false);

		if (itemNames.isEmpty())
		{
			showText("No matching items found.");
			return;
		}

		JPanel itemListPanel = new JPanel();
		itemListPanel.setLayout(new BoxLayout(itemListPanel, BoxLayout.Y_AXIS));
		itemListPanel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		itemListPanel.add(new JLabel("Did you mean?"));

		for (String itemName : itemNames)
		{
			JButton itemButton = new JButton(itemName);
			itemButton.setAlignmentX(LEFT_ALIGNMENT);
			itemButton.addActionListener(event -> selectItem(itemName));
			itemListPanel.add(itemButton);
		}

		resultContainer.removeAll();
		addMouseWheelListenerRecursively(itemListPanel, resultWheelListener);
		resultContainer.add(itemListPanel, BorderLayout.CENTER);
		resultContainer.revalidate();
		resultContainer.repaint();
		resetAncestorScrollPanesToTop(itemListPanel);
	}

	private void showLastSearchResults()
	{
		if (lastSearchTerm == null || lastSearchItemNames.isEmpty())
		{
			return;
		}

		currentResult = null;
		openWikiButton.setEnabled(false);
		showItemSearchResults(lastSearchTerm, lastSearchItemNames);
	}

	private void renderCurrentResult()
	{
		if (currentResult == null)
		{
			return;
		}

		showItemResult(currentResult, ironmanMode.isSelected());
		backButton.setEnabled(selectedFromSearchResults);
		backButton.setVisible(selectedFromSearchResults);
	}

	private void showItemResult(WikiItemResult result, boolean ironman)
	{
		WikiItemSummary summary = result.getSummary();
		JPanel resultPanel = new JPanel();
		resultPanel.setLayout(new BoxLayout(resultPanel, BoxLayout.Y_AXIS));
		resultPanel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		addTextBlock(resultPanel, result.getTitle() + "\n");
		addItemFactsSection(resultPanel, summary);
		addPinnedItemAction(resultPanel, result.getTitle());
		if (!summary.isStructuredDataFound())
		{
			addTextBlock(resultPanel, "Raw wiki lookup succeeded, but no structured sources were found.\n");
		}

		BestSourceBuilder.BestSourceResult bestSources = BEST_SOURCE_BUILDER.buildResult(summary, result.getTitle(), ironman);
		BestSourceBuilder.CreationSplit creationSplit = BestSourceBuilder.splitCreation(summary.getCreation(), result.getTitle(), ironman);
		if (!bestSources.isEmpty())
		{
			addBestSourcesSection(resultPanel, bestSources);
		}
		if (config.showCreationSection())
		{
			addMaterialsChecklistSection(resultPanel, result.getTitle(), MATERIALS_CHECKLIST_BUILDER.build(result.getTitle(), summary.getCreationRecipes(), summary.getCreation()), ironman);
		}

		if (ironman)
		{
			addSection(resultPanel, "Ironman sources:", filterIronman(summary.getSources()));
			if (config.showDropsSection())
			{
				addDropSection(resultPanel, "Other drops:", filterIronman(summary.getDrops()), BestSourceBuilder.removeBestDropSources(summary.getDropSources(), bestSources), !summary.getDropSources().isEmpty());
			}
			if (config.showShopsSection())
			{
				addSectionIfUseful(resultPanel, "Other shops:", BestSourceBuilder.removeBestShops(summary.getShops(), bestSources, true));
			}
			if (config.showCreationSection())
			{
				addSectionIfUseful(resultPanel, "Other creation / made by:", BestSourceBuilder.removeBestCreation(summary.getCreation(), bestSources, result.getTitle(), true));
				addVariantRecipesSection(resultPanel, creationSplit);
			}
			if (config.showSummarySection())
			{
				addSection(resultPanel, "Summary:", filterIronman(summary.getGeneralSummary()));
			}
		}
		else
		{
			if (config.showSummarySection())
			{
				addSection(resultPanel, "Summary:", summary.getGeneralSummary());
			}
			if (config.showCreationSection())
			{
				addSectionIfUseful(resultPanel, "Other creation / made by:", BestSourceBuilder.removeBestCreation(summary.getCreation(), bestSources, result.getTitle(), false));
				addVariantRecipesSection(resultPanel, creationSplit);
			}
			addSection(resultPanel, "Item sources / obtained from:", summary.getSources());
			if (config.showShopsSection())
			{
				addSectionIfUseful(resultPanel, "Other shops:", BestSourceBuilder.removeBestShops(summary.getShops(), bestSources, false));
			}
			if (config.showDropsSection())
			{
				addDropSection(resultPanel, "Other drops:", summary.getDrops(), BestSourceBuilder.removeBestDropSources(summary.getDropSources(), bestSources), !summary.getDropSources().isEmpty());
			}
		}

		resultContainer.removeAll();
		addMouseWheelListenerRecursively(resultPanel, resultWheelListener);
		resultContainer.add(resultPanel, BorderLayout.CENTER);
		resultContainer.revalidate();
		resultContainer.repaint();
		resetAncestorScrollPanesToTop(resultPanel);
		resetAncestorScrollPanesToTop(this);
	}

	private void addPinnedItemAction(JPanel parent, String itemName)
	{
		JPanel actionPanel = new JPanel();
		actionPanel.setLayout(new BoxLayout(actionPanel, BoxLayout.Y_AXIS));
		actionPanel.setAlignmentX(LEFT_ALIGNMENT);
		actionPanel.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));

		boolean pinned = pinnedItemsManager.isPinned(itemName);
		JButton pinButton = new JButton(pinned ? "Unpin item" : "Pin item");
		pinButton.setAlignmentX(LEFT_ALIGNMENT);
		pinButton.setFocusPainted(false);
		pinButton.setMargin(new Insets(2, 6, 2, 6));
		if (!pinned)
		{
			JComboBox<String> groupSelector = new JComboBox<>(pinnedItemsManager.getGroupNames().toArray(new String[0]));
			groupSelector.setMaximumRowCount(8);
			groupSelector.setMaximumSize(new Dimension(Integer.MAX_VALUE, groupSelector.getPreferredSize().height));
			pinButton.addActionListener(event ->
			{
				Object selectedGroup = groupSelector.getSelectedItem();
				pinnedItemsManager.addPinnedItem(selectedGroup == null ? PinnedItemsManager.DEFAULT_GROUP : selectedGroup.toString(), itemName);
				renderCurrentResult();
			});

			JPanel groupRow = new JPanel(new BorderLayout(4, 0));
			groupRow.setAlignmentX(LEFT_ALIGNMENT);
			groupRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, groupSelector.getPreferredSize().height));
			groupRow.add(new JLabel("Group"), BorderLayout.WEST);
			groupRow.add(groupSelector, BorderLayout.CENTER);

			actionPanel.add(pinButton);
			actionPanel.add(groupRow);
		}
		else
		{
			pinButton.addActionListener(event ->
			{
				pinnedItemsManager.removePinnedItem(itemName);
				renderCurrentResult();
			});
			actionPanel.add(pinButton);
		}
		parent.add(actionPanel);
	}

	private void addItemFactsSection(JPanel parent, WikiItemSummary summary)
	{
		if (WikiItemSummary.NO_CLEAR_DATA_FOUND.equals(summary.getHighAlch()))
		{
			return;
		}

		addTextBlock(parent, "High alch: " + summary.getHighAlch() + "\n");
	}

	private void showPinnedItemsDialog()
	{
		JDialog dialog = new JDialog(getDialogOwner(), "Pinned items", false);
		dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
		dialog.setContentPane(createPinnedItemsDialogContent(dialog));
		dialog.pack();
		dialog.setLocationRelativeTo(this);
		dialog.setVisible(true);
	}

	private JPanel createPinnedItemsDialogContent(JDialog dialog)
	{
		JPanel content = new JPanel(new BorderLayout(0, 6));
		content.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		content.add(createPinnedItemsListPanel(dialog), BorderLayout.CENTER);
		JPanel actions = new JPanel(new BorderLayout(4, 0));
		JTextField groupName = new JTextField(14);
		JButton addGroup = new JButton("Add group");
		addGroup.setFocusPainted(false);
		addGroup.setMargin(new Insets(2, 6, 2, 6));
		addGroup.addActionListener(event ->
		{
			if (pinnedItemsManager.addGroup(groupName.getText()))
			{
				dialog.setContentPane(createPinnedItemsDialogContent(dialog));
				dialog.revalidate();
				dialog.repaint();
			}
		});
		actions.add(groupName, BorderLayout.CENTER);
		actions.add(addGroup, BorderLayout.EAST);
		content.add(actions, BorderLayout.SOUTH);
		return content;
	}

	private JComponent createPinnedItemsListPanel(JDialog dialog)
	{
		List<PinnedItemsManager.PinnedItemGroup> groups = pinnedItemsManager.getPinnedGroups();
		if (groups.isEmpty())
		{
			JPanel listPanel = new JPanel();
			listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
			listPanel.add(new JLabel("No pinned items yet."));
			JScrollPane scrollPane = new JScrollPane(listPanel);
			scrollPane.setPreferredSize(new Dimension(330, 70));
			return scrollPane;
		}

		JTabbedPane tabs = new JTabbedPane();
		for (PinnedItemsManager.PinnedItemGroup group : groups)
		{
			JPanel listPanel = new JPanel(new BorderLayout(0, 6));
			listPanel.setBorder(BorderFactory.createEmptyBorder(6, 4, 4, 4));
			JPanel rowsPanel = new JPanel(new GridLayout(0, 1, 0, 4));
			if (group.getItems().isEmpty())
			{
				rowsPanel.add(new JLabel("No items in this group."));
			}
			for (String itemName : group.getItems())
			{
				rowsPanel.add(createPinnedItemRow(dialog, itemName));
			}
			listPanel.add(rowsPanel, BorderLayout.NORTH);
			if (!PinnedItemsManager.DEFAULT_GROUP.equalsIgnoreCase(group.getName()))
			{
				JButton removeGroupButton = new JButton("Remove group");
				removeGroupButton.setFocusPainted(false);
				removeGroupButton.setMargin(new Insets(2, 6, 2, 6));
				removeGroupButton.addActionListener(event ->
				{
					pinnedItemsManager.removeGroup(group.getName());
					dialog.setContentPane(createPinnedItemsDialogContent(dialog));
					dialog.revalidate();
					dialog.repaint();
				});
				JPanel groupActions = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
				groupActions.add(removeGroupButton);
				listPanel.add(groupActions, BorderLayout.SOUTH);
			}
			JScrollPane scrollPane = new JScrollPane(listPanel);
			scrollPane.getVerticalScrollBar().setUnitIncrement(16);
