	private static String indent(String text)
	{
		StringBuilder indented = new StringBuilder();
		for (String line : text.split("\\R"))
		{
			if (!line.trim().isEmpty())
			{
				indented.append("  ").append(line.trim()).append('\n');
			}
		}

		return indented.toString();
	}

