	private static String filterIronman(String value)
	{
		if (value == null || WikiItemSummary.NO_CLEAR_DATA_FOUND.equals(value))
		{
			return WikiItemSummary.NO_CLEAR_DATA_FOUND;
		}

		StringBuilder filtered = new StringBuilder();
		for (String line : value.split("\\R"))
		{
			String normalized = line.toLowerCase(Locale.ENGLISH);
			if (normalized.contains("grand exchange") || normalized.contains("tradeable")
				|| normalized.contains("trade with") || normalized.contains("traded with")
				|| normalized.contains("buy from other players") || normalized.contains("sold by other players"))
			{
				continue;
			}

			if (filtered.length() > 0)
			{
				filtered.append('\n');
			}
			filtered.append(line);
		}

		String result = filtered.toString().trim();
		return result.isEmpty() ? WikiItemSummary.NO_CLEAR_DATA_FOUND : result;
	}

	private void showLocationsDialog(DropSource dropSource)
	{
		String sourceName = dropSource.getSourceName();
		String pageTitle = dropSource.getSourceWikiPageTitle();
		log.debug("WikiItemHelper source location button clicked: source='{}', page='{}'", sourceName, pageTitle);

		JDialog dialog = new JDialog(getDialogOwner(), "Locations: " + sourceName, false);
		dialog.setLayout(new BorderLayout(8, 8));
		dialog.setPreferredSize(LOCATION_DIALOG_SIZE);

		JLabel titleLabel = new JLabel(sourceName);
		titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD));
		titleLabel.setBorder(BorderFactory.createEmptyBorder(10, 10, 0, 10));
		dialog.add(titleLabel, BorderLayout.NORTH);

		JPanel contentPanel = new JPanel(new BorderLayout());
		contentPanel.setBorder(BorderFactory.createEmptyBorder(6, 10, 6, 10));
		contentPanel.add(new JLabel("Loading locations..."), BorderLayout.NORTH);
		JScrollPane contentScrollPane = new JScrollPane(contentPanel);
		contentScrollPane.setBorder(BorderFactory.createEmptyBorder());
		contentScrollPane.getVerticalScrollBar().setUnitIncrement(16);
		dialog.add(contentScrollPane, BorderLayout.CENTER);

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 4));
		JButton openWiki = new JButton("Open wiki page");
		JButton close = new JButton("Close");
		openWiki.setEnabled(false);
		close.addActionListener(event -> dialog.dispose());
		buttons.add(openWiki);
		buttons.add(close);
		dialog.add(buttons, BorderLayout.SOUTH);
		dialog.pack();
		dialog.setLocationRelativeTo(this);
		dialog.setVisible(true);

		new SwingWorker<LocationDialogData, Void>()
		{
			@Override
			protected LocationDialogData doInBackground() throws IOException
			{
				LocationLookupResult result = wikiClient.lookupSourceLocations(sourceName);
				return new LocationDialogData(result, loadLocationImage(result));
			}

			@Override
			protected void done()
			{
				SwingUtilities.invokeLater(() ->
				{
					try
					{
						LocationDialogData dialogData = get();
						LocationLookupResult result = dialogData.result;
						titleLabel.setText(result.getSourceWikiPageTitle());
						contentPanel.removeAll();
						contentPanel.add(buildLocationDialogContent(result, dialogData.image), BorderLayout.NORTH);
						openWiki.setEnabled(result.getWikiUrl() != null);
						openWiki.addActionListener(event -> openWikiUrl(result.getWikiUrl(), contentPanel));
					}
					catch (Exception ex)
					{
						log.warn("WikiItemHelper source location lookup failed for '{}'", sourceName, ex);
						contentPanel.removeAll();
						contentPanel.add(new JLabel("Location lookup failed. Check logs."), BorderLayout.NORTH);
						openWiki.setEnabled(false);
					}
					contentPanel.revalidate();
					contentPanel.repaint();
				});
			}
		}.execute();
	}

	private BufferedImage loadLocationImage(LocationLookupResult result)
	{
		String imageUrl = result.getMapImageUrl();
		if (imageUrl == null || imageUrl.trim().isEmpty())
		{
			return null;
		}

		boolean thumbnailUrl = isThumbnailImageUrl(imageUrl);
		String resolvedImageUrl = thumbnailUrl ? resolveLargerThumbnailUrl(imageUrl) : imageUrl;
		log.debug(
			"WikiItemHelper source location image URL: original={}, isThumbnail={}, resolved={}",
			imageUrl,
			thumbnailUrl,
			resolvedImageUrl
		);

		BufferedImage cached = locationImageCache.get(imageUrl);
		if (cached != null)
		{
			log.debug("WikiItemHelper source location image cache hit for '{}'", imageUrl);
			return cached;
		}

		if (!resolvedImageUrl.equals(imageUrl))
		{
			cached = locationImageCache.get(resolvedImageUrl);
			if (cached != null)
			{
				log.debug("WikiItemHelper source location image cache hit for '{}'", resolvedImageUrl);
				locationImageCache.put(imageUrl, cached);
				return cached;
			}
		}

		BufferedImage image = readLocationImage(resolvedImageUrl);
		if (image == null && !resolvedImageUrl.equals(imageUrl))
		{
			image = readLocationImage(imageUrl);
		}
		if (image != null)
		{
			locationImageCache.put(imageUrl, image);
			locationImageCache.put(resolvedImageUrl, image);
			log.debug("WikiItemHelper source location image pixels: url={}, width={}, height={}", resolvedImageUrl, image.getWidth(), image.getHeight());
		}

		return image;
	}

	private BufferedImage readLocationImage(String imageUrl)
	{
		try
		{
			return ImageIO.read(new URI(imageUrl).toURL());
		}
		catch (IOException | RuntimeException | URISyntaxException ex)
		{
			log.debug("WikiItemHelper source location image failed to load for '{}'", imageUrl, ex);
			return null;
		}
	}

	private static boolean isThumbnailImageUrl(String imageUrl)
	{
		return imageUrl.contains("/images/thumb/") && imageUrl.matches("(?i).*/\\d+px-[^/]+(?:\\?.*)?$");
	}

	private static String resolveLargerThumbnailUrl(String imageUrl)
	{
		return imageUrl.replaceFirst("(?i)/(\\d+)px-([^/?]+)(\\?.*)?$", "/800px-$2$3");
	}

	private Component buildLocationDialogContent(LocationLookupResult result, BufferedImage image)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));

		if (image != null)
		{
			ScaledLocationImage scaledImage = scaleLocationImage(image);
			log.debug(
				"WikiItemHelper source location image display size: originalWidth={}, originalHeight={}, displayedWidth={}, displayedHeight={}",
				image.getWidth(),
				image.getHeight(),
				scaledImage.width,
				scaledImage.height
			);
			JLabel imageLabel = new JLabel(new ImageIcon(scaledImage.image));
			imageLabel.setAlignmentX(LEFT_ALIGNMENT);
			panel.add(imageLabel);

			if (result.getMapImageSource() != null && !result.getMapImageSource().trim().isEmpty())
			{
				JLabel source = new JLabel("Map source: " + result.getMapImageSource());
				source.setAlignmentX(LEFT_ALIGNMENT);
				panel.add(source);
			}

			if (result.getMapImageCaption() != null && !result.getMapImageCaption().trim().isEmpty())
			{
				JLabel caption = new JLabel("<html><body style='width:" + LOCATION_IMAGE_MAX_WIDTH + "px'>" + result.getMapImageCaption() + "</body></html>");
				caption.setAlignmentX(LEFT_ALIGNMENT);
				panel.add(caption);
			}
		}

		if (result.getLocationNames().isEmpty())
		{
			JLabel empty = new JLabel("No clear locations found");
			empty.setAlignmentX(LEFT_ALIGNMENT);
			panel.add(empty);
			return panel;
		}

		for (String location : result.getLocationNames())
		{
			JLabel locationLabel = new JLabel(location);
			locationLabel.setAlignmentX(LEFT_ALIGNMENT);
			panel.add(locationLabel);
		}

		if (result.getNotes() != null && !result.getNotes().trim().isEmpty())
		{
			JTextArea notes = createTextArea("\n" + result.getNotes());
			notes.setAlignmentX(LEFT_ALIGNMENT);
			panel.add(notes);
		}

		return panel;
	}

	private ScaledLocationImage scaleLocationImage(BufferedImage image)
	{
		int width = image.getWidth();
		int height = image.getHeight();
		if (width <= 0 || height <= 0 || width <= LOCATION_IMAGE_MAX_WIDTH)
		{
			return new ScaledLocationImage(image, width, height);
		}

		int scaledHeight = Math.max(1, (int) Math.round((double) height * LOCATION_IMAGE_MAX_WIDTH / width));
		return new ScaledLocationImage(image.getScaledInstance(LOCATION_IMAGE_MAX_WIDTH, scaledHeight, Image.SCALE_SMOOTH), LOCATION_IMAGE_MAX_WIDTH, scaledHeight);
	}

	private Frame getDialogOwner()
	{
		Window window = SwingUtilities.getWindowAncestor(this);
		return window instanceof Frame ? (Frame) window : null;
	}

	private void openWikiUrl(String wikiUrl, JPanel statusPanel)
	{
		if (wikiUrl == null || !Desktop.isDesktopSupported())
		{
			return;
		}

		try
		{
			Desktop.getDesktop().browse(new URI(wikiUrl));
		}
		catch (IOException | URISyntaxException ignored)
		{
			statusPanel.removeAll();
			statusPanel.add(new JLabel("Could not open the wiki page."), BorderLayout.NORTH);
			statusPanel.revalidate();
			statusPanel.repaint();
		}
	}

	private void addRecentSearch(String searchTerm)
	{
		String normalized = searchTerm.trim();
		if (normalized.isEmpty())
		{
			return;
		}

		recentSearches.removeIf(existing -> existing.equalsIgnoreCase(normalized));
		recentSearches.add(0, normalized);
		while (recentSearches.size() > MAX_RECENT_SEARCHES)
		{
			recentSearches.remove(recentSearches.size() - 1);
		}

		refreshRecentSearches();
		saveRecentSearches();
	}

	private void refreshRecentSearches()
	{
		recentSearchPanel.removeAll();
		recentSearchPanel.setVisible(!recentSearches.isEmpty());
		clearRecentButton.setEnabled(!recentSearches.isEmpty());
		if (!recentSearches.isEmpty())
		{
			JPanel header = new JPanel(new BorderLayout(4, 0));
			header.setAlignmentX(LEFT_ALIGNMENT);
			JLabel recentLabel = new JLabel("Recent");
			recentLabel.setFont(recentLabel.getFont().deriveFont(Font.BOLD));
			header.add(recentLabel, BorderLayout.WEST);
			clearRecentButton.setFocusPainted(false);
			clearRecentButton.setMargin(new Insets(1, 6, 1, 6));
			header.add(clearRecentButton, BorderLayout.EAST);
			recentSearchPanel.add(header);

			for (String searchTerm : recentSearches)
			{
				JButton recentButton = new JButton(searchTerm);
				recentButton.setAlignmentX(LEFT_ALIGNMENT);
				recentButton.setFocusPainted(false);
				recentButton.setHorizontalAlignment(JButton.LEFT);
				recentButton.setMargin(new Insets(1, 6, 1, 6));
				recentButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
				recentButton.addActionListener(event ->
				{
					searchField.setText(searchTerm);
					search();
				});
				recentSearchPanel.add(recentButton);
			}
		}

		Dimension preferredSize = recentSearchPanel.getPreferredSize();
		recentSearchPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Math.min(120, preferredSize.height)));
		recentSearchPanel.revalidate();
		recentSearchPanel.repaint();
	}

	private void loadRecentSearches()
	{
		recentSearches.clear();
		if (!config.rememberRecentSearches())
		{
			return;
		}

		for (String line : config.recentSearches().split("\\R"))
		{
			String searchTerm = line.trim();
			if (!searchTerm.isEmpty())
			{
				recentSearches.add(searchTerm);
			}
			if (recentSearches.size() >= MAX_RECENT_SEARCHES)
			{
				break;
			}
		}
	}

	private void saveRecentSearches()
	{
		if (config.rememberRecentSearches())
		{
			configManager.setConfiguration("wikiitemhelper", "recentSearches", String.join("\n", recentSearches));
		}
	}

	private void clearRecentSearches()
	{
		recentSearches.clear();
		configManager.setConfiguration("wikiitemhelper", "recentSearches", "");
		refreshRecentSearches();
	}

	private void openCurrentWikiPage()
	{
		if (currentResult == null || currentResult.getPageUrl() == null || !Desktop.isDesktopSupported())
		{
			return;
		}

		try
		{
			Desktop.getDesktop().browse(new URI(currentResult.getPageUrl()));
		}
		catch (IOException | URISyntaxException ignored)
		{
			showText(resultArea.getText() + "\n\nCould not open the wiki page.");
		}
	}

