package com.wikiitemhelper;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.runelite.client.config.ConfigManager;

public class PinnedItemsManager
{
	static final int MAX_PINNED_ITEMS = 50;
	static final int MAX_GROUPS = 12;
	static final String CONFIG_GROUP = "wikiitemhelper";
	static final String CONFIG_KEY = "pinnedItems";
	static final String DEFAULT_GROUP = "Favorites";

	private final Supplier<String> serializedItemsSupplier;
	private final Consumer<String> serializedItemsConsumer;

	public PinnedItemsManager(WikiItemHelperConfig config, ConfigManager configManager)
	{
		this(config::pinnedItems, serializedItems -> configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY, serializedItems));
	}

	PinnedItemsManager(Supplier<String> serializedItemsSupplier, Consumer<String> serializedItemsConsumer)
	{
		this.serializedItemsSupplier = serializedItemsSupplier;
		this.serializedItemsConsumer = serializedItemsConsumer;
	}

	public List<String> getPinnedItems()
	{
		List<String> items = new ArrayList<>();
		for (PinnedItemGroup group : getPinnedGroups())
		{
			items.addAll(group.getItems());
		}
		return items;
	}

	public List<PinnedItemGroup> getPinnedGroups()
	{
		return parseGroups(serializedItemsSupplier.get());
	}

	public List<String> getGroupNames()
	{
		List<String> groupNames = new ArrayList<>();
		for (PinnedItemGroup group : getPinnedGroups())
		{
			groupNames.add(group.getName());
		}
		if (groupNames.isEmpty())
		{
			groupNames.add(DEFAULT_GROUP);
		}
		return groupNames;
	}

	public boolean isPinned(String itemName)
	{
		String normalized = normalize(itemName);
		if (normalized.isEmpty())
		{
			return false;
		}

		for (String pinnedItem : getPinnedItems())
		{
			if (normalize(pinnedItem).equals(normalized))
			{
				return true;
			}
		}

		return false;
	}

	public boolean addPinnedItem(String itemName)
	{
		return addPinnedItem(DEFAULT_GROUP, itemName);
	}

	public boolean addPinnedItem(String groupName, String itemName)
	{
		String displayName = cleanDisplayName(itemName);
		if (displayName.isEmpty())
		{
			return false;
		}

		List<PinnedItemGroup> groups = new ArrayList<>(getPinnedGroups());
		String normalized = normalize(displayName);
		for (PinnedItemGroup group : groups)
		{
			for (String pinnedItem : group.getItems())
			{
				if (normalize(pinnedItem).equals(normalized))
				{
					return false;
				}
			}
		}

		if (getTotalPinnedItems(groups) >= MAX_PINNED_ITEMS)
		{
			return false;
		}

		PinnedItemGroup targetGroup = findOrCreateGroup(groups, groupName);
		if (targetGroup == null)
		{
			return false;
		}

		targetGroup.getMutableItems().add(displayName);
		saveGroups(groups);
		return true;
	}

	public boolean removePinnedItem(String itemName)
	{
		String normalized = normalize(itemName);
		if (normalized.isEmpty())
		{
			return false;
		}

		List<PinnedItemGroup> groups = new ArrayList<>(getPinnedGroups());
		boolean removed = false;
		for (PinnedItemGroup group : groups)
		{
			removed |= group.getMutableItems().removeIf(pinnedItem -> normalize(pinnedItem).equals(normalized));
		}
		if (removed)
		{
			saveGroups(groups);
		}

		return removed;
	}

	public boolean addGroup(String groupName)
	{
		List<PinnedItemGroup> groups = new ArrayList<>(getPinnedGroups());
		if (findGroup(groups, groupName) != null || groups.size() >= MAX_GROUPS)
		{
			return false;
		}

		groups.add(new PinnedItemGroup(cleanGroupName(groupName), new ArrayList<>()));
		saveGroups(groups);
		return true;
	}

	public boolean removeGroup(String groupName)
	{
		String normalizedGroup = normalize(groupName);
		if (normalizedGroup.isEmpty() || normalize(DEFAULT_GROUP).equals(normalizedGroup))
		{
			return false;
		}

		List<PinnedItemGroup> groups = new ArrayList<>(getPinnedGroups());
		boolean removed = groups.removeIf(group -> normalize(group.getName()).equals(normalizedGroup));
		if (removed)
		{
			saveGroups(groups);
		}

		return removed;
	}

	private void saveGroups(List<PinnedItemGroup> groups)
	{
		serializedItemsConsumer.accept(serializeGroups(groups));
	}

	static List<String> parse(String serializedItems)
	{
		List<String> pinnedItems = new ArrayList<>();
		for (PinnedItemGroup group : parseGroups(serializedItems))
		{
			pinnedItems.addAll(group.getItems());
		}
		return pinnedItems;
	}

	static List<PinnedItemGroup> parseGroups(String serializedItems)
	{
		if (serializedItems == null || serializedItems.trim().isEmpty())
		{
			return Collections.emptyList();
		}

		List<PinnedItemGroup> groups = new ArrayList<>();
		PinnedItemGroup currentGroup = new PinnedItemGroup(DEFAULT_GROUP, new ArrayList<>());
		Set<String> seen = new LinkedHashSet<>();
		boolean sawGroupHeader = false;
		for (String line : serializedItems.split("\\R"))
		{
			String trimmed = line.trim();
			if (trimmed.startsWith("[") && trimmed.endsWith("]"))
			{
				addGroupIfUseful(groups, currentGroup, sawGroupHeader);
				sawGroupHeader = true;
				currentGroup = new PinnedItemGroup(cleanGroupName(trimmed.substring(1, trimmed.length() - 1)), new ArrayList<>());
				continue;
			}

			String itemName = cleanDisplayName(trimmed);
			String normalized = normalize(itemName);
			if (normalized.isEmpty() || !seen.add(normalized))
			{
				continue;
			}

			currentGroup.getMutableItems().add(itemName);
			if (seen.size() >= MAX_PINNED_ITEMS)
			{
				break;
			}
		}
		addGroupIfUseful(groups, currentGroup, sawGroupHeader);

		return groups;
	}

	static String serialize(List<String> pinnedItems)
	{
		List<PinnedItemGroup> groups = new ArrayList<>();
		groups.add(new PinnedItemGroup(DEFAULT_GROUP, new ArrayList<>(pinnedItems)));
		return serializeGroups(groups);
	}

	static String serializeGroups(List<PinnedItemGroup> groups)
	{
		List<String> lines = new ArrayList<>();
		Set<String> seen = new LinkedHashSet<>();
		int groupCount = 0;
		for (PinnedItemGroup group : groups)
		{
			String groupName = cleanGroupName(group.getName());
			List<String> cleanedItems = new ArrayList<>();
			for (String pinnedItem : group.getItems())
			{
				String itemName = cleanDisplayName(pinnedItem);
				String normalized = normalize(itemName);
				if (normalized.isEmpty() || !seen.add(normalized))
				{
					continue;
				}

				cleanedItems.add(itemName);
				if (seen.size() >= MAX_PINNED_ITEMS)
				{
					break;
				}
			}

			if (groupCount >= MAX_GROUPS)
			{
				break;
			}
			lines.add("[" + groupName + "]");
			lines.addAll(cleanedItems);
			groupCount++;
			if (seen.size() >= MAX_PINNED_ITEMS)
			{
				break;
			}
		}

		return String.join("\n", lines);
	}

	private static void addGroupIfUseful(List<PinnedItemGroup> groups, PinnedItemGroup group, boolean keepEmptyGroups)
	{
		if (group == null || groups.size() >= MAX_GROUPS)
		{
			return;
		}
		if (group.getItems().isEmpty() && !keepEmptyGroups)
		{
			return;
		}

		groups.add(group);
	}

	private static PinnedItemGroup findOrCreateGroup(List<PinnedItemGroup> groups, String groupName)
	{
		PinnedItemGroup group = findGroup(groups, groupName);
		if (group != null)
		{
			return group;
		}
		if (groups.size() >= MAX_GROUPS)
		{
			return null;
		}

		PinnedItemGroup newGroup = new PinnedItemGroup(cleanGroupName(groupName), new ArrayList<>());
		groups.add(newGroup);
		return newGroup;
	}

	private static PinnedItemGroup findGroup(List<PinnedItemGroup> groups, String groupName)
	{
		String normalizedGroup = normalize(cleanGroupName(groupName));
		for (PinnedItemGroup group : groups)
		{
			if (normalize(group.getName()).equals(normalizedGroup))
			{
				return group;
			}
		}

		return null;
	}

	private static int getTotalPinnedItems(List<PinnedItemGroup> groups)
	{
		int total = 0;
		for (PinnedItemGroup group : groups)
		{
			total += group.getItems().size();
		}
		return total;
	}

	private static String cleanDisplayName(String itemName)
	{
		return itemName == null ? "" : itemName.trim();
	}

	private static String cleanGroupName(String groupName)
	{
		String cleaned = cleanDisplayName(groupName).replace("[", "").replace("]", "");
		return cleaned.isEmpty() ? DEFAULT_GROUP : cleaned;
	}

	private static String normalize(String itemName)
	{
		return cleanDisplayName(itemName).toLowerCase(Locale.ENGLISH);
	}

	public static class PinnedItemGroup
	{
		private final String name;
		private final List<String> items;

		PinnedItemGroup(String name, List<String> items)
		{
			this.name = cleanGroupName(name);
			this.items = items == null ? new ArrayList<>() : items;
		}

		public String getName()
		{
			return name;
		}

		public List<String> getItems()
		{
			return Collections.unmodifiableList(items);
		}

		private List<String> getMutableItems()
		{
			return items;
		}
	}
}

package com.wikiitemhelper;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class MaterialsChecklistBuilder
{
	private static final Logger log = LoggerFactory.getLogger(MaterialsChecklistBuilder.class);
	private static final Pattern LEADING_QUANTITY = Pattern.compile("^(\\d+)\\s+(.+)$");
	private static final Pattern DOSE_SUFFIX = Pattern.compile("(?i)\\s*\\([1-4]\\)\\s*$");
	private static final Pattern LEVEL_LINE = Pattern.compile("(?i)^Level\\s+(\\S+)\\s+(.+)$");
	private static final Pattern SKILL_LINE = Pattern.compile("(?i)^Skill:\\s*(.+)$");
	private static final Pattern MATERIALS_LINE = Pattern.compile("(?i)^Materials:\\s*(.+)$");
	private static final Pattern TOOLS_LINE = Pattern.compile("(?i)^Tools:\\s*(.+)$");
	private static final Pattern FACILITY_LINE = Pattern.compile("(?i)^Facilit(?:y|ies):\\s*(.+)$");
	private static final Pattern OUTPUT_LINE = Pattern.compile("(?i)^Output:\\s*(.+)$");

	public MaterialsChecklist build(String currentItemName, List<CreationRecipe> creationRecipes)
	{
		return build(currentItemName, creationRecipes, "");
	}

	public MaterialsChecklist build(String currentItemName, List<CreationRecipe> creationRecipes, String creationText)
	{
		if (currentItemName == null || currentItemName.trim().isEmpty() || creationRecipes == null || creationRecipes.isEmpty())
		{
			return buildFromCreationText(currentItemName, creationText);
		}

		String current = normalizeItemName(currentItemName);
		String currentWithoutDose = normalizeItemName(stripDoseSuffix(currentItemName));
		debugAntidote(currentItemName, "normalized selected item name={}, withoutDose={}", current, currentWithoutDose);
		List<RecipeChecklist> recipes = new ArrayList<>();
		for (CreationRecipe recipe : creationRecipes)
		{
			if (!outputsCurrentItem(currentItemName, recipe, current, currentWithoutDose))
			{
				continue;
			}

			List<ChecklistEntry> entries = new ArrayList<>();
			addMaterialEntries(entries, recipe.getMaterials());
			addToolOrFacilityEntries(entries, recipe.getTools());
			addToolOrFacilityEntries(entries, recipe.getFacilities());
			debugAntidote(currentItemName, "parsed materials={}", checklistText(entries));
			if (!entries.isEmpty())
			{
				recipes.add(new RecipeChecklist(recipeTitle(recipe), entries));
			}
		}

		return recipes.isEmpty() ? buildFromCreationText(currentItemName, creationText) : new MaterialsChecklist(collapseNearDuplicateRecipes(recipes));
	}

	private static MaterialsChecklist buildFromCreationText(String currentItemName, String creationText)
	{
		if (creationText == null || creationText.trim().isEmpty() || WikiItemSummary.NO_CLEAR_DATA_FOUND.equals(creationText))
		{
			return MaterialsChecklist.empty();
		}

		String current = normalizeItemName(currentItemName);
		String currentWithoutDose = normalizeItemName(stripDoseSuffix(currentItemName));
		debugAntidote(currentItemName, "normalized selected item name={}, withoutDose={} using creation text fallback", current, currentWithoutDose);
		List<RecipeChecklist> recipes = new ArrayList<>();
		for (String block : creationText.split("\\R\\s*\\R"))
		{
			RecipeChecklist recipe = parseTextRecipe(block, current, currentWithoutDose);
			if (recipe != null)
			{
				recipes.add(recipe);
			}
		}

		return recipes.isEmpty() ? MaterialsChecklist.empty() : new MaterialsChecklist(collapseNearDuplicateRecipes(recipes));
	}

	private static RecipeChecklist parseTextRecipe(String block, String current, String currentWithoutDose)
	{
		String skill = "";
		String level = "";
		String materials = "";
		String tools = "";
		String facilities = "";
		String output = "";

		for (String line : block.split("\\R"))
		{
			String trimmed = line.trim();
			Matcher levelMatcher = LEVEL_LINE.matcher(trimmed);
			Matcher skillMatcher = SKILL_LINE.matcher(trimmed);
			Matcher materialsMatcher = MATERIALS_LINE.matcher(trimmed);
			Matcher toolsMatcher = TOOLS_LINE.matcher(trimmed);
			Matcher facilityMatcher = FACILITY_LINE.matcher(trimmed);
			Matcher outputMatcher = OUTPUT_LINE.matcher(trimmed);
			if (levelMatcher.matches())
			{
				level = levelMatcher.group(1).trim();
				skill = levelMatcher.group(2).trim();
			}
			else if (skillMatcher.matches())
			{
				skill = skillMatcher.group(1).trim();
			}
			else if (materialsMatcher.matches())
			{
				materials = materialsMatcher.group(1).trim();
			}
			else if (toolsMatcher.matches())
			{
				tools = toolsMatcher.group(1).trim();
			}
			else if (facilityMatcher.matches())
			{
				facilities = facilityMatcher.group(1).trim();
			}
			else if (outputMatcher.matches())
			{
				output = outputMatcher.group(1).trim();
			}
		}

		if (output.isEmpty() || !textOutputsCurrentItem(output, current, currentWithoutDose))
		{
			return null;
		}

		List<ChecklistEntry> entries = new ArrayList<>();
		addMaterialEntryText(entries, materials);
		addToolOrFacilityEntryText(entries, tools);
		addToolOrFacilityEntryText(entries, facilities);
		if (entries.isEmpty())
		{
			return null;
		}

		return new RecipeChecklist(recipeTitle(skill, level), entries);
	}

	private static boolean outputsCurrentItem(String currentItemName, CreationRecipe recipe, String current, String currentWithoutDose)
	{
		for (CreationRecipe.Entry output : recipe.getOutputs())
		{
			String outputName = output.getName();
			String normalizedOutput = normalizeItemName(outputName);
			String normalizedOutputWithoutDose = normalizeItemName(stripDoseSuffix(outputName));
			boolean matches = normalizedOutput.equals(current) || normalizedOutputWithoutDose.equals(currentWithoutDose);
			debugAntidote(
				currentItemName,
				"recipe output item name={}, normalizedOutput={}, outputWithoutDose={}, outputMatchesSelected={}",
				outputName,
				normalizedOutput,
				normalizedOutputWithoutDose,
				matches
			);
			if (matches)
			{
				return true;
			}
		}

		return false;
	}

	private static boolean textOutputsCurrentItem(String outputText, String current, String currentWithoutDose)
	{
		for (String output : splitMaterialNames(outputText))
		{
			String normalizedOutput = normalizeItemName(output);
			if (normalizedOutput.equals(current) || normalizeItemName(stripDoseSuffix(output)).equals(currentWithoutDose))
			{
				return true;
			}
		}

		return false;
	}

	private static void addMaterialEntries(List<ChecklistEntry> checklist, List<CreationRecipe.Entry> entries)
	{
		for (CreationRecipe.Entry entry : entries)
		{
			if (entry.getName() == null || entry.getName().trim().isEmpty())
			{
				continue;
			}

			for (String materialName : splitMaterialNames(entry.getName()))
			{
				addMaterialEntry(checklist, materialName, entry.getQuantity());
			}
		}
	}

	private static void addMaterialEntry(List<ChecklistEntry> checklist, String materialName, String quantity)
	{
		String name = materialName.trim();
		String materialQuantity = quantity;
		if (materialQuantity == null)
		{
			Matcher matcher = LEADING_QUANTITY.matcher(name);
			if (matcher.matches())
			{
				materialQuantity = matcher.group(1);
				name = matcher.group(2).trim();
			}
			else
			{
				materialQuantity = "1";
			}
		}

		if (!name.isEmpty())
		{
			checklist.add(new ChecklistEntry(name, materialQuantity));
		}
	}

	private static void addMaterialEntryText(List<ChecklistEntry> checklist, String text)
	{
		for (String material : splitMaterialNames(text))
		{
			addMaterialEntry(checklist, material, null);
		}
	}

	private static void addToolOrFacilityEntryText(List<ChecklistEntry> checklist, String text)
	{
		for (String entry : splitMaterialNames(text))
		{
			if (!entry.trim().isEmpty())
			{
				checklist.add(new ChecklistEntry(entry.trim(), null));
			}
		}
	}

	private static void addToolOrFacilityEntries(List<ChecklistEntry> checklist, List<CreationRecipe.Entry> entries)
	{
		for (CreationRecipe.Entry entry : entries)
		{
			if (entry.getName() != null && !entry.getName().trim().isEmpty())
			{
				checklist.add(new ChecklistEntry(entry.getName(), null));
			}
		}
	}

	private static List<String> splitMaterialNames(String text)
	{
		List<String> parts = new ArrayList<>();
		StringBuilder current = new StringBuilder();
		int parenthesesDepth = 0;
		for (int i = 0; i < text.length(); i++)
		{
			char character = text.charAt(i);
			if (character == '(')
			{
				parenthesesDepth++;
			}
			else if (character == ')' && parenthesesDepth > 0)
			{
				parenthesesDepth--;
			}

			if ((character == ',' || character == ';') && parenthesesDepth == 0)
			{
				addSplitPart(parts, current);
				current.setLength(0);
			}
			else
			{
				current.append(character);
			}
		}

		addSplitPart(parts, current);
		return parts;
	}

	private static void addSplitPart(List<String> parts, StringBuilder current)
	{
		String value = current.toString().trim();
		if (!value.isEmpty())
		{
			parts.add(value);
		}
	}

	private static String recipeTitle(CreationRecipe recipe)
	{
		return recipeTitle(recipe.getSkill(), recipe.getLevel());
	}

	private static String recipeTitle(String skill, String level)
	{
		if (skill == null || skill.trim().isEmpty())
		{
			return "";
		}

		return level == null || level.trim().isEmpty() ? skill : level + " " + skill;
	}

	private static List<RecipeChecklist> collapseNearDuplicateRecipes(List<RecipeChecklist> recipes)
	{
		List<RecipeChecklist> preferred = new ArrayList<>();
		for (RecipeChecklist recipe : recipes)
		{
			String identity = checklistIdentity(recipe);
			boolean added = false;
			for (int i = 0; i < preferred.size(); i++)
			{
				RecipeChecklist existing = preferred.get(i);
				if (checklistIdentity(existing).equals(identity))
				{
					if (checklistDisplayScore(recipe) < checklistDisplayScore(existing))
					{
						debugAntidoteRecipe(recipe, "recipe replaced previous entry during deduplication");
						preferred.set(i, recipe);
					}
					else
					{
						debugAntidoteRecipe(recipe, "recipe removed by deduplication");
					}
					added = true;
					break;
				}
			}

			if (!added)
			{
				preferred.add(recipe);
			}
		}

		return preferred;
	}

	private static String checklistText(List<ChecklistEntry> entries)
	{
		List<String> text = new ArrayList<>();
		for (ChecklistEntry entry : entries)
		{
			text.add(entry.toPlainText());
		}

		return text.toString();
	}

	private static void debugAntidote(String currentItemName, String message, Object... args)
	{
		if (currentItemName != null && currentItemName.equalsIgnoreCase("Antidote++"))
		{
			log.debug("WikiItemHelper Antidote++ checklist debug: " + message, args);
		}
	}

	private static void debugAntidoteRecipe(RecipeChecklist recipe, String message)
	{
		for (ChecklistEntry entry : recipe.getEntries())
		{
			if (entry.getName() != null && entry.getName().toLowerCase(Locale.ENGLISH).contains("antidote++"))
			{
				log.debug("WikiItemHelper Antidote++ checklist debug: {} recipeTitle={}, entries={}", message, recipe.getTitle(), recipe.toPlainText());
				return;
			}
		}
	}

	private static String checklistIdentity(RecipeChecklist recipe)
	{
		List<String> entries = new ArrayList<>();
		for (ChecklistEntry entry : recipe.getEntries())
		{
			String canonical = canonicalMaterialIdentity(entry.getName());
			if (!canonical.isEmpty())
			{
				entries.add(canonical + ":" + (entry.getQuantity() == null ? "" : entry.getQuantity()));
			}
		}

		Collections.sort(entries);
		return normalizeItemName(recipe.getTitle()) + "|" + String.join("+", entries);
	}

	private static int checklistDisplayScore(RecipeChecklist recipe)
	{
		int score = 0;
		for (ChecklistEntry entry : recipe.getEntries())
		{
			String name = entry.getName() == null ? "" : entry.getName().toLowerCase(Locale.ENGLISH);
			score += name.length();
			if (name.contains("potion (unf)") || name.contains("unfinished potion"))
			{
				score += 1000;
			}
		}

		return score;
	}

	private static String canonicalMaterialIdentity(String value)
	{
		return normalizeItemName(value)
			.replaceFirst("(?i)\\s+potion\\s+unf$", "")
			.replaceFirst("(?i)\\s+unfinished\\s+potion$", "")
			.trim();
	}

	private static String normalizeItemName(String value)
	{
		if (value == null)
		{
			return "";
		}

		return value
			.replaceFirst("(?i)^\\d+\\s+", "")
			.toLowerCase(Locale.ENGLISH)
			.replaceAll("[^a-z0-9+]+", " ")
			.trim();
	}

	private static String stripDoseSuffix(String value)
	{
		return value == null ? "" : DOSE_SUFFIX.matcher(value).replaceFirst("");
	}

	public static class MaterialsChecklist
	{
		private final List<RecipeChecklist> recipes;

		private MaterialsChecklist(List<RecipeChecklist> recipes)
		{
			this.recipes = Collections.unmodifiableList(new ArrayList<>(recipes));
		}

		private static MaterialsChecklist empty()
		{
			return new MaterialsChecklist(Collections.emptyList());
		}

		public boolean isEmpty()
		{
			return recipes.isEmpty();
		}

		public List<RecipeChecklist> getRecipes()
		{
			return recipes;
		}
	}

	public static class RecipeChecklist
	{
		private final String title;
		private final List<ChecklistEntry> entries;

		private RecipeChecklist(String title, List<ChecklistEntry> entries)
		{
			this.title = title;
			this.entries = Collections.unmodifiableList(new ArrayList<>(entries));
		}

		public String getTitle()
		{
			return title;
		}

		public List<ChecklistEntry> getEntries()
		{
			return entries;
		}

		public String toPlainText()
		{
			List<String> lines = new ArrayList<>();
			for (ChecklistEntry entry : entries)
			{
				lines.add(entry.toPlainText());
			}

			return String.join("\n", lines);
		}
	}

	public static class ChecklistEntry
	{
		private final String name;
		private final String quantity;

		private ChecklistEntry(String name, String quantity)
		{
			this.name = name;
			this.quantity = quantity;
		}

		public String getName()
		{
			return name;
		}

		public String getQuantity()
		{
			return quantity;
		}

		public String toPlainText()
		{
			return quantity == null || quantity.trim().isEmpty() ? name : name + " x" + quantity;
		}
	}
}

package com.wikiitemhelper;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class BestSourceReasonBuilder
{
	private static final int MAX_TAGS = 4;
	private static final Pattern LEVEL_LINE = Pattern.compile("(?im)^\\s*Level\\s+(\\d+)\\s+(.+?)\\s*$");
	private static final String[] BOSS_TERMS = {
		"king black dragon", "zulrah", "vorkath", "corporeal beast", "kalphite queen", "venenatis", "callisto", "vet'ion",
		"vetion", "scorpia", "chaos elemental", "chaos fanatic", "thermonuclear smoke devil", "abyssal sire",
		"cerberus", "hydra", "alchemical hydra", "nightmare", "nex", "duke sucellus", "vardorvis", "whisperer",
		"leviathan", "muspah", "hespori", "sarachnis", "skotizo", "jad", "zuk", "general graardor", "commander zilyana",
		"kree'arra", "k'ril tsutsaroth"
	};
	private static final String[] REWARD_TERMS = {
		"reward", "minigame", "pyramid plunder", "barbarian assault", "wintertodt", "tempoross", "guardians of the rift",
		"tithe farm", "sepulchre", "chambers of xeric", "theatre of blood", "tombs of amascut"
	};
	private static final String[] CONTAINER_TERMS = {
		"casket", "chest", "crate", "impling jar", "jar", "coffer", "nest", "sack", "pouch", "box", "barrel"
	};
	private static final String[] SKILLING_TERMS = {
		"impling", "pickpocket", "thieving", "hunter", "fishing", "mining", "woodcutting", "farming", "agility"
	};
	private static final String[] WILDERNESS_TERMS = {
		"wilderness", "revenant", "callisto", "venenatis", "vet'ion", "vetion", "chaos elemental", "chaos fanatic",
		"scorpia", "crazy archaeologist", "rogue's chest"
	};
	private static final String[] TRADE_TERMS = {
		"grand exchange", "player trading", "trade with", "traded with", "buy from other players", "sold by other players"
	};

	public List<String> creationTags(String displayText, boolean ironmanMode)
	{
		List<String> tags = new ArrayList<>();
		addTag(tags, "Craftable");

		Matcher levelMatcher = LEVEL_LINE.matcher(nullToEmpty(displayText));
		if (levelMatcher.find())
		{
			int level = parseInt(levelMatcher.group(1));
			String skill = cleanSkill(levelMatcher.group(2));
			if (level > 0 && !skill.isEmpty())
			{
				addTag(tags, "Requires " + level + " " + skill);
				if (level < 50)
				{
					addTag(tags, "Low requirement");
				}
				else if (level >= 80)
				{
					addTag(tags, "High requirement");
				}
			}
		}

		addIronmanFriendly(tags, displayText, ironmanMode);
		return limit(tags);
	}

	public List<String> shopTags(String displayText, boolean ironmanMode)
	{
		List<String> tags = new ArrayList<>();
		addTag(tags, "Shop source");
		addTag(tags, "No combat required");

		String normalized = normalize(displayText);
		if ((normalized.contains("quest") && (normalized.contains("requires") || normalized.contains("completion")))
			|| normalized.contains("after completing"))
		{
			addTag(tags, "Requires quest");
		}

		addIronmanFriendly(tags, displayText, ironmanMode);
		return limit(tags);
	}

	public List<String> dropTags(BestSourceBuilder.BestDrop drop, boolean ironmanMode)
	{
		List<String> tags = new ArrayList<>();
		String sourceName = drop == null ? "" : drop.getSourceName();
		String displayText = drop == null ? "" : drop.getDisplayText();
		String combined = normalize(sourceName + " " + displayText);

		if (containsAny(combined, CONTAINER_TERMS))
		{
			addTag(tags, "Container source");
		}
		else if (containsAny(combined, REWARD_TERMS))
		{
			addTag(tags, "Reward source");
		}
		else if (containsAny(combined, SKILLING_TERMS))
		{
			addTag(tags, "Skilling source");
		}
		else if (!sourceName.trim().isEmpty())
		{
			addTag(tags, "Direct monster drop");
		}

		if (containsAny(combined, BOSS_TERMS))
		{
			addTag(tags, "Boss drop");
		}

		Double rarityScore = BestSourceBuilder.parseRarityScore(extractRarity(displayText));
		if (rarityScore != null)
		{
			if (rarityScore <= 64D)
			{
				addTag(tags, "Common drop");
			}
			else if (rarityScore > 512D)
			{
				addTag(tags, "Rare drop");
			}
		}

		if (containsAny(combined, WILDERNESS_TERMS))
		{
			addTag(tags, "Wilderness source");
		}
		if (combined.contains("slayer"))
		{
			addTag(tags, "Requires Slayer");
		}
		addIronmanFriendly(tags, displayText, ironmanMode);
		if (drop != null && drop.getSource() != null)
		{
			addTag(tags, "Location available");
		}

		return limit(tags);
	}

	private static String extractRarity(String displayText)
	{
		int separator = nullToEmpty(displayText).lastIndexOf(" - ");
		return separator < 0 ? "" : displayText.substring(separator + 3).trim();
	}

	private static void addIronmanFriendly(List<String> tags, String text, boolean ironmanMode)
	{
		if (ironmanMode && !containsAny(normalize(text), TRADE_TERMS))
		{
			addTag(tags, "Ironman-friendly");
		}
	}

	private static void addTag(List<String> tags, String tag)
	{
		if (tags.size() >= MAX_TAGS || tags.contains(tag))
		{
			return;
		}

		tags.add(tag);
	}

	private static List<String> limit(List<String> tags)
	{
		return tags.size() <= MAX_TAGS ? tags : new ArrayList<>(tags.subList(0, MAX_TAGS));
	}

	private static boolean containsAny(String value, String[] terms)
	{
		for (String term : terms)
		{
			if (value.contains(term))
			{
				return true;
			}
		}

		return false;
	}

	private static String normalize(String value)
	{
		return nullToEmpty(value).toLowerCase(Locale.ENGLISH);
	}

	private static String cleanSkill(String value)
	{
		return nullToEmpty(value).replaceAll("\\s+", " ").trim();
	}

	private static int parseInt(String value)
	{
		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException ex)
		{
			return 0;
		}
	}

	private static String nullToEmpty(String value)
	{
		return value == null ? "" : value;
	}
}

package com.wikiitemhelper;

import com.google.gson.JsonArray;
