@Singleton
public class WikiClient
{
	private static final Logger log = LoggerFactory.getLogger(WikiClient.class);
	private static final String API_URL = "https://oldschool.runescape.wiki/api.php";
	private static final String USER_AGENT = "WikiItemHelper RuneLite external plugin (https://runelite.net/plugin-hub)";
	private static final String API_RESPONSE_TYPE = "MediaWiki revision wikitext via action=query&prop=revisions&rvprop=content&rvslots=main";
	private static final String PARSE_RESPONSE_TYPE = "Rendered MediaWiki HTML via action=parse&prop=text";
	private static final String ITEM_SEARCH_RESPONSE_TYPE = "MediaWiki item search via action=query&list=search&srsearch=intitle plus hastemplate:Infobox Item";
	private static final String LOCATION_RESPONSE_TYPE = "MediaWiki source location lookup via action=query&prop=revisions&rvprop=content&rvslots=main";
	private static final String MAP_VERSION_RESPONSE_TYPE = "MediaWiki map version via action=query&meta=allmessages";
	private static final String DEFAULT_MAP_VERSION = "2026-03-04_a";
	private static final String FULLSCREEN_MAP_SOURCE = "wiki fullscreen map";
	private static final int ITEM_SEARCH_LIMIT = 50;
	private static final int MAX_SOURCE_LOCATIONS = 12;
	private static final Pattern TEMPLATE_PARAMETER = Pattern.compile("(?m)^\\|\\s*([^=|]+?)\\s*=\\s*(.*?)\\s*$");
	private static final Pattern WIKI_LINK = Pattern.compile("\\[\\[([^]|#]+)(?:#[^]|]+)?(?:\\|([^]]+))?]]");
	private static final Pattern IMAGE_TAG = Pattern.compile("(?is)<img\\b[^>]*>");
	private static final Pattern KARTOGRAPHER_MAP_LINK = Pattern.compile("(?is)<a\\b(?=[^>]*\\bmw-kartographer-maplink\\b)[^>]*>\\s*Show map\\s*</a>");
	private static final Pattern ATTRIBUTE_VALUE = Pattern.compile("(?is)\\b%s\\s*=\\s*\"([^\"]*)\"");
	private static final String[] STRONG_IMAGE_TERMS = {"safespot location", "battlefield map", "dungeon map", "safespot", "safe spot", "locations", "location", "map"};
	private static final String[] PREFERRED_IMAGE_TERMS = {"lair", "cave", "canyon", "settlement", "battlefield", "dungeon"};
	private static final String[] REJECTED_IMAGE_TERMS = {
		"map icon", "fairy ring icon", "minimap icon", "icon", "logo", "crest", "symbol", "members", "member", "star",
		"chathead", "render", "detail", "inventory", "sprite", "transparent", "drops", "equipment"
	};
	private static final int MIN_LOCATION_IMAGE_WIDTH = 150;
	private static final int MIN_LOCATION_IMAGE_HEIGHT = 120;
	private static final int MIN_LOCATION_IMAGE_SCORE = 10;

	private final OkHttpClient httpClient;
	private final WikiItemParser parser;
	private final Map<String, WikiItemResult> cache = new ConcurrentHashMap<>();
	private final Map<String, List<String>> itemSearchCache = new ConcurrentHashMap<>();
	private final Map<String, LocationLookupResult> sourceLocationCache = new ConcurrentHashMap<>();
	private volatile String mapVersionCache;

	@Inject
	WikiClient(OkHttpClient httpClient, WikiItemParser parser)
	{
		this.httpClient = httpClient;
		this.parser = parser;
	}

	public WikiItemResult lookupItem(String itemName) throws IOException
	{
		String key = itemName.trim().toLowerCase();
		WikiItemResult cached = cache.get(key);
		if (cached != null)
		{
			log.debug("WikiItemHelper item lookup cache hit for '{}'", itemName);
			return cached;
		}

		WikiItemResult result = fetchItem(itemName.trim());
		cache.put(key, result);
		return result;
	}

	boolean isItemCached(String itemName)
	{
		return itemName != null && cache.containsKey(itemName.trim().toLowerCase(Locale.ENGLISH));
	}

	public List<String> searchItems(String rawSearchTerm) throws IOException
	{
		String searchTerm = rawSearchTerm.trim();
		log.debug("WikiItemHelper raw item search term: '{}'", rawSearchTerm);
		if (searchTerm.isEmpty())
		{
			return new ArrayList<>();
		}

		String key = searchTerm.toLowerCase(Locale.ENGLISH);
		List<String> cached = itemSearchCache.get(key);
		if (cached != null)
		{
			log.debug("WikiItemHelper item search cache hit for '{}'", searchTerm);
			log.debug("WikiItemHelper item candidates found: {}", cached.size());
			log.debug("WikiItemHelper filtered item names: {}", cached);
			return new ArrayList<>(cached);
		}

		Set<String> itemNames = new LinkedHashSet<>(fetchItemSearch(searchTerm));
		String alternatePotionSearch = alternatePotionSearch(searchTerm);
		if (alternatePotionSearch != null)
		{
			log.debug("WikiItemHelper item search alternate potion term: '{}'", alternatePotionSearch);
			itemNames.addAll(fetchItemSearch(alternatePotionSearch));
		}

		List<String> itemNameList = new ArrayList<>(itemNames);
		itemSearchCache.put(key, Collections.unmodifiableList(new ArrayList<>(itemNameList)));
		log.debug("WikiItemHelper item candidates found: {}", itemNameList.size());
		log.debug("WikiItemHelper filtered item names: {}", itemNameList);
		return itemNameList;
	}

	private List<String> fetchItemSearch(String searchTerm) throws IOException
	{
		log.debug("WikiItemHelper requesting OSRS Wiki response type: {}", ITEM_SEARCH_RESPONSE_TYPE);
		HttpUrl url = HttpUrl.parse(API_URL).newBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("list", "search")
			.addQueryParameter("srsearch", buildItemSearchQuery(searchTerm))
			.addQueryParameter("srnamespace", "0")
			.addQueryParameter("srlimit", Integer.toString(ITEM_SEARCH_LIMIT))
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.code() != HttpURLConnection.HTTP_OK)
			{
				throw new IOException("Wiki item search API returned " + response.code());
			}

			ResponseBody body = response.body();
			if (body == null)
			{
				throw new IOException("Wiki item search API returned an empty response");
			}

			return parseItemSearchResponse(searchTerm, body.string());
		}
	}

	private static String alternatePotionSearch(String searchTerm)
	{
		String normalized = searchTerm.trim().replaceAll("\\s+", " ");
		if (!normalized.toLowerCase(Locale.ENGLISH).endsWith(" potion"))
		{
			return null;
		}

		String withoutPotion = normalized.substring(0, normalized.length() - " potion".length()).trim();
		return withoutPotion.isEmpty() ? null : withoutPotion;
	}

	public LocationLookupResult lookupSourceLocations(String sourceName) throws IOException
	{
		String trimmedSourceName = sourceName.trim();
		String key = trimmedSourceName.toLowerCase(Locale.ENGLISH);
		LocationLookupResult cached = sourceLocationCache.get(key);
		if (cached != null)
		{
			log.debug("WikiItemHelper source location cache hit for '{}'", trimmedSourceName);
			return cached;
		}

		log.debug("WikiItemHelper source location clicked: {}", trimmedSourceName);
		LocationLookupResult result = fetchSourceLocations(trimmedSourceName);
		sourceLocationCache.put(key, result);
		return result;
	}

	private WikiItemResult fetchItem(String itemName) throws IOException
	{
		log.debug("WikiItemHelper requesting OSRS Wiki response type: {}", API_RESPONSE_TYPE);

		HttpUrl url = buildItemLookupUrl(itemName);

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.code() != HttpURLConnection.HTTP_OK)
			{
				throw new IOException("Wiki API returned " + response.code());
			}

			ResponseBody body = response.body();
			if (body == null)
			{
				throw new IOException("Wiki API returned an empty response");
			}

			return parseResponse(itemName, body.string());
		}
	}

	static HttpUrl buildItemLookupUrl(String itemName)
	{
		return HttpUrl.parse(API_URL).newBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("prop", "revisions")
			.addQueryParameter("titles", itemName)
			.addQueryParameter("rvprop", "content")
			.addQueryParameter("rvslots", "main")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.build();
	}

	private LocationLookupResult fetchSourceLocations(String sourceName) throws IOException
	{
		log.debug("WikiItemHelper requesting OSRS Wiki response type: {}", LOCATION_RESPONSE_TYPE);

		HttpUrl url = HttpUrl.parse(API_URL).newBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("prop", "revisions")
			.addQueryParameter("titles", sourceName)
			.addQueryParameter("rvprop", "content")
			.addQueryParameter("rvslots", "main")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.build();
		log.debug("WikiItemHelper source location API URL: {}", url);

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.code() != HttpURLConnection.HTTP_OK)
			{
				throw new IOException("Wiki source location API returned " + response.code());
			}

			ResponseBody body = response.body();
			if (body == null)
			{
				throw new IOException("Wiki source location API returned an empty response");
			}

			LocationLookupResult textResult = parseSourceLocationResponse(sourceName, body.string());
			LocationImageCandidate imageCandidate = null;
			boolean fullscreenMapFound = false;
			boolean fallbackImageUsed = false;
			try
			{
				String renderedHtml = fetchRenderedHtml(textResult.getSourceWikiPageTitle());
				String mapVersion = DEFAULT_MAP_VERSION;
				try
				{
					mapVersion = fetchMapVersion();
				}
				catch (IOException ex)
				{
					log.debug("WikiItemHelper map version lookup failed; using default '{}'", DEFAULT_MAP_VERSION, ex);
				}
				imageCandidate = findFullscreenMapImage(renderedHtml, mapVersion);
				fullscreenMapFound = imageCandidate != null;
				log.debug(
					"WikiItemHelper source page '{}' fullscreen map found: {}, extracted map source: {}",
					textResult.getSourceWikiPageTitle(),
					fullscreenMapFound,
					imageCandidate == null ? null : imageCandidate.url
				);
				if (imageCandidate == null)
				{
					fallbackImageUsed = true;
					imageCandidate = findBestLocationImage(renderedHtml);
				}
			}
			catch (IOException ex)
			{
				log.debug("WikiItemHelper source location image lookup failed for '{}'", textResult.getSourceWikiPageTitle(), ex);
			}
			log.debug(
				"WikiItemHelper source location image for '{}': url={}, caption={}, fallbackImageLogicUsed={}",
				textResult.getSourceWikiPageTitle(),
				imageCandidate == null ? null : imageCandidate.url,
				imageCandidate == null ? null : imageCandidate.caption,
				fallbackImageUsed
			);
			return new LocationLookupResult(
				textResult.getSourceName(),
				textResult.getSourceWikiPageTitle(),
				textResult.getLocationNames(),
				textResult.getNotes(),
				textResult.getWikiUrl(),
				imageCandidate == null ? null : imageCandidate.url,
				imageCandidate == null ? null : imageCandidate.caption,
				imageCandidate == null ? null : imageCandidate.source
			);
		}
	}

	private String fetchMapVersion() throws IOException
	{
		if (mapVersionCache != null)
		{
			return mapVersionCache;
		}

		log.debug("WikiItemHelper requesting OSRS Wiki response type: {}", MAP_VERSION_RESPONSE_TYPE);
		HttpUrl url = HttpUrl.parse(API_URL).newBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("meta", "allmessages")
			.addQueryParameter("ammessages", "kartographer-map-version")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.code() != HttpURLConnection.HTTP_OK)
			{
				throw new IOException("Wiki map version API returned " + response.code());
			}

			ResponseBody body = response.body();
			if (body == null)
			{
				throw new IOException("Wiki map version API returned an empty response");
			}

			mapVersionCache = parseMapVersionResponse(body.string());
			return mapVersionCache;
		}
	}

	private WikiItemResult parseResponse(String requestedTitle, String json) throws IOException
	{
		JsonObject root = new JsonParser().parse(json).getAsJsonObject();
		JsonObject query = root.getAsJsonObject("query");
		JsonArray pages = query.getAsJsonArray("pages");
		if (pages == null || pages.size() == 0)
		{
			return WikiItemResult.notFound(requestedTitle);
		}

		JsonObject page = pages.get(0).getAsJsonObject();
		if (page.has("missing"))
		{
			return WikiItemResult.notFound(requestedTitle);
		}

		String title = getString(page, "title", requestedTitle);
		String content = extractContent(page);
		log.debug("WikiItemHelper returned page content for '{}': {}", title, firstChars(content, 2000));
		String renderedHtml = content.contains("{{Drop sources") ? fetchRenderedHtml(title) : "";
		WikiItemSummary summary = parser.parse(content, renderedHtml);
		return new WikiItemResult(title, buildPageUrl(title), summary);
	}

	private String fetchRenderedHtml(String title) throws IOException
	{
		log.debug("WikiItemHelper requesting OSRS Wiki response type: {}", PARSE_RESPONSE_TYPE);

		HttpUrl url = HttpUrl.parse(API_URL).newBuilder()
			.addQueryParameter("action", "parse")
			.addQueryParameter("page", title)
			.addQueryParameter("prop", "text")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.code() != HttpURLConnection.HTTP_OK)
			{
				throw new IOException("Wiki parse API returned " + response.code());
			}

			ResponseBody body = response.body();
			if (body == null)
			{
				throw new IOException("Wiki parse API returned an empty response");
			}

			JsonObject root = new JsonParser().parse(body.string()).getAsJsonObject();
			JsonObject parse = root.getAsJsonObject("parse");
			return parse == null ? "" : getString(parse, "text", "");
		}
	}

	static List<String> parseItemSearchResponse(String rawSearchTerm, String json)
	{
		String searchTerm = rawSearchTerm.trim();
		Set<String> itemNames = new LinkedHashSet<>();
		JsonObject root = new JsonParser().parse(json).getAsJsonObject();
		JsonObject query = root.getAsJsonObject("query");
		if (query == null)
		{
			return new ArrayList<>();
		}

		JsonArray searchResults = query.getAsJsonArray("search");
		if (searchResults == null)
		{
			return new ArrayList<>();
		}

		for (JsonElement resultElement : searchResults)
		{
			JsonObject result = resultElement.getAsJsonObject();
			if (result.has("ns") && result.get("ns").getAsInt() != 0)
			{
				continue;
			}

			String title = getString(result, "title", "").trim();
			if (isLikelyItemSearchResult(searchTerm, title))
			{
				itemNames.add(title);
			}
		}

		return new ArrayList<>(itemNames);
	}

	static LocationLookupResult parseSourceLocationResponse(String requestedSourceName, String json)
	{
		JsonObject root = new JsonParser().parse(json).getAsJsonObject();
		JsonObject query = root.getAsJsonObject("query");
		if (query == null)
		{
			return new LocationLookupResult(requestedSourceName, requestedSourceName, Collections.emptyList(), null, buildPageUrl(requestedSourceName));
		}

		JsonArray pages = query.getAsJsonArray("pages");
		if (pages == null || pages.size() == 0)
		{
			return new LocationLookupResult(requestedSourceName, requestedSourceName, Collections.emptyList(), null, buildPageUrl(requestedSourceName));
		}

		JsonObject page = pages.get(0).getAsJsonObject();
		if (page.has("missing"))
		{
			log.debug("WikiItemHelper source page missing for '{}'", requestedSourceName);
			return new LocationLookupResult(requestedSourceName, requestedSourceName, Collections.emptyList(), null, buildPageUrl(requestedSourceName));
		}

		String title = getString(page, "title", requestedSourceName);
		String content = extractContent(page);
		List<String> locations = parseLocationNames(content);
		log.debug("WikiItemHelper source location table/section found for '{}': {}", title, !locations.isEmpty());
		log.debug("WikiItemHelper parsed source locations for '{}': {}", title, locations);
		return new LocationLookupResult(requestedSourceName, title, locations, null, buildPageUrl(title));
	}

	static List<String> parseLocationNames(String pageContent)
	{
		String content = pageContent == null ? "" : pageContent;
		LinkedHashSet<String> locations = new LinkedHashSet<>();
		addLocationCandidates(locations, extractTemplateParameter(content, "location"));
		addLocationCandidates(locations, extractTemplateParameter(content, "locations"));
		addLocationCandidates(locations, extractLocationSection(content));

		return new ArrayList<>(locations);
	}

