	static String parseMapVersionResponse(String json)
	{
		JsonObject root = new JsonParser().parse(json).getAsJsonObject();
		JsonObject query = root.getAsJsonObject("query");
		if (query == null)
		{
			return DEFAULT_MAP_VERSION;
		}

		JsonArray allMessages = query.getAsJsonArray("allmessages");
		if (allMessages == null)
		{
			return DEFAULT_MAP_VERSION;
		}

		for (JsonElement messageElement : allMessages)
		{
			JsonObject message = messageElement.getAsJsonObject();
			String content = getString(message, "content", "").trim();
			if (!content.isEmpty())
			{
				return content;
			}
		}

		return DEFAULT_MAP_VERSION;
	}

	private static LocationImageCandidate findFullscreenMapImage(String renderedHtml, String mapVersion)
	{
		if (renderedHtml == null || renderedHtml.trim().isEmpty())
		{
			return null;
		}

		List<FullscreenMapLink> mapLinks = new ArrayList<>();
		Matcher matcher = KARTOGRAPHER_MAP_LINK.matcher(renderedHtml);
		while (matcher.find())
		{
			FullscreenMapLink mapLink = parseFullscreenMapLink(matcher.group());
			if (mapLink != null)
			{
				mapLinks.add(mapLink);
			}
		}

		if (mapLinks.isEmpty())
		{
			return null;
		}

		FullscreenMapLink primary = mapLinks.get(0);
		List<FullscreenMapLink> matchingMapLinks = new ArrayList<>();
		for (FullscreenMapLink mapLink : mapLinks)
		{
			if (mapLink.mapId == primary.mapId && mapLink.plane == primary.plane)
			{
				matchingMapLinks.add(mapLink);
			}
		}

		int displayZoom = chooseFullerMapZoom(primary.zoom, matchingMapLinks);
		String tileUrl = buildFullscreenMapTileUrl(mapVersion, primary.mapId, primary.plane, displayZoom, primary.lat, primary.lon);
		if (tileUrl == null)
		{
			return null;
		}

		log.debug(
			"WikiItemHelper fullscreen map tile selected: mapId={}, plane={}, wikiZoom={}, displayZoom={}, relatedLinks={}, originalMapTileUrl={}",
			primary.mapId,
			primary.plane,
			primary.zoom,
			displayZoom,
			matchingMapLinks.size(),
			tileUrl
		);
		return new LocationImageCandidate(tileUrl, null, 1000, null, FULLSCREEN_MAP_SOURCE);
	}

	private static FullscreenMapLink parseFullscreenMapLink(String link)
	{
		try
		{
			return new FullscreenMapLink(
				Integer.parseInt(firstUseful(findAttribute(link, "data-mapid"), "0", "").trim()),
				Integer.parseInt(firstUseful(findAttribute(link, "data-plane"), "0", "").trim()),
				Math.max(-3, Math.min(3, Integer.parseInt(firstUseful(findAttribute(link, "data-zoom"), "2", "").trim()))),
				Double.parseDouble(findAttribute(link, "data-lat").trim()),
				Double.parseDouble(findAttribute(link, "data-lon").trim())
			);
		}
		catch (NullPointerException | NumberFormatException ex)
		{
			return null;
		}
	}

	private static int chooseFullerMapZoom(int requestedZoom, List<FullscreenMapLink> relatedLinks)
	{
		int clampedZoom = Math.max(-3, Math.min(3, requestedZoom));
		if (relatedLinks.size() <= 1)
		{
			return clampedZoom;
		}

		for (int zoom = clampedZoom; zoom >= -3; zoom--)
		{
			FullscreenMapTile firstTile = fullscreenMapTileFor(relatedLinks.get(0), zoom);
			boolean allSameTile = true;
			for (FullscreenMapLink relatedLink : relatedLinks)
			{
				if (!firstTile.equals(fullscreenMapTileFor(relatedLink, zoom)))
				{
					allSameTile = false;
					break;
				}
			}

			if (allSameTile)
			{
				return zoom;
			}
		}

		return clampedZoom;
	}

	private static String buildFullscreenMapTileUrl(String mapVersion, int mapId, int plane, int zoom, double lat, double lon)
	{
		FullscreenMapTile tile = fullscreenMapTileFor(new FullscreenMapLink(mapId, plane, zoom, lat, lon), zoom);
		return "https://maps.runescape.wiki/osrs/versions/" + mapVersion.trim()
			+ "/tiles/rendered/" + mapId
			+ "/" + zoom
			+ "/" + plane + "_" + tile.x + "_" + tile.invertedY + ".png";
	}

	private static FullscreenMapTile fullscreenMapTileFor(FullscreenMapLink link, int zoom)
	{
		double scale = Math.pow(2, zoom);
		int tileX = (int) Math.floor(link.lon * scale / 256D);
		int leafletTileY = (int) Math.floor(-link.lat * scale / 256D);
		return new FullscreenMapTile(tileX, -leafletTileY - 1);
	}

	private static LocationImageCandidate findBestLocationImage(String renderedHtml)
	{
		if (renderedHtml == null || renderedHtml.trim().isEmpty())
		{
			return null;
		}

		LocationImageCandidate best = null;
		Matcher matcher = IMAGE_TAG.matcher(renderedHtml);
		while (matcher.find())
		{
			String imageTag = matcher.group();
			String src = findAttribute(imageTag, "src");
			if (src == null || src.trim().isEmpty())
			{
				continue;
			}

			int start = matcher.start();
			int end = Math.min(renderedHtml.length(), matcher.end() + 450);
			String context = renderedHtml.substring(start, end);
			String alt = findAttribute(imageTag, "alt");
			String title = findAttribute(imageTag, "title");
			int width = parseImageDimension(findAttribute(imageTag, "width"), src);
			int height = parseImageDimension(findAttribute(imageTag, "height"), null);
			String caption = cleanHtml(firstUseful(extractNearbyCaption(context), alt, title));
			String url = normalizeImageUrl(src);
			LocationImageCandidate candidate = evaluateLocationImage(url, src, alt, title, caption, context, width, height);
			log.debug(
				"WikiItemHelper location image candidate: url={}, width={}, height={}, caption={}, score={}, rejection={}",
				url == null ? src : url,
				width <= 0 ? null : width,
				height <= 0 ? null : height,
				caption,
				candidate.score,
				candidate.rejectionReason
			);

			if (candidate.rejectionReason != null)
			{
				continue;
			}

			if (best == null || candidate.score > best.score)
			{
				best = candidate;
			}
		}

		return best;
	}

	private static LocationImageCandidate evaluateLocationImage(String url, String src, String alt, String title, String caption, String context, int width, int height)
	{
		String filename = extractImageFilename(src);
		String meaningfulText = cleanHtml(filename + " " + nullToEmpty(alt) + " " + nullToEmpty(title) + " " + nullToEmpty(caption));
		String nearbyText = cleanHtml(extractNearbyFigureText(context));
		String normalizedMeaningful = meaningfulText.toLowerCase(Locale.ENGLISH);
		String normalizedNearby = nearbyText.toLowerCase(Locale.ENGLISH);

		if (url == null)
		{
			return LocationImageCandidate.rejected(src, caption, 0, "image URL was not usable");
		}

		int score = 0;
		boolean strongMapSignal = false;
		for (String term : STRONG_IMAGE_TERMS)
		{
			if (normalizedMeaningful.contains(term))
			{
				score += "map".equals(term) ? 12 : 16;
				strongMapSignal = true;
			}
			else if (normalizedNearby.contains(term))
			{
				score += "map".equals(term) ? 4 : 6;
			}
		}

		for (String term : PREFERRED_IMAGE_TERMS)
		{
			if (normalizedMeaningful.contains(term))
			{
				score += 8;
			}
			else if (normalizedNearby.contains(term))
			{
				score += 3;
			}
		}

		for (String term : REJECTED_IMAGE_TERMS)
		{
			if (normalizedMeaningful.contains(term))
			{
				return LocationImageCandidate.rejected(url, caption, score - 30, "rejected image term: " + term);
			}
		}

		if (isSvgOrDataImage(src))
		{
			return LocationImageCandidate.rejected(url, caption, score - 20, "SVG/data image is likely an icon or symbol");
		}

		if (isKnownSmallImage(width, height) && !strongMapSignal)
		{
			return LocationImageCandidate.rejected(url, caption, score - 10, "image was below useful size threshold");
		}

		if (!strongMapSignal && score < MIN_LOCATION_IMAGE_SCORE)
		{
			return LocationImageCandidate.rejected(url, caption, score, "not map/location-like enough");
		}

		return new LocationImageCandidate(url, caption, score, null, null);
	}

	private static String extractNearbyCaption(String html)
	{
		Matcher captionMatcher = Pattern.compile("(?is)<figcaption\\b[^>]*>(.*?)</figcaption>|<div\\b[^>]*class=\"[^\"]*thumbcaption[^\"]*\"[^>]*>(.*?)</div>").matcher(html);
		if (!captionMatcher.find())
		{
			return "";
		}

		return captionMatcher.group(1) == null ? captionMatcher.group(2) : captionMatcher.group(1);
	}

	private static String extractNearbyFigureText(String html)
	{
		Matcher figureMatcher = Pattern.compile("(?is)<figure\\b[^>]*>(.*?)</figure>|<div\\b[^>]*class=\"[^\"]*(?:thumb|gallerybox)[^\"]*\"[^>]*>(.*?)</div>").matcher(html);
		if (!figureMatcher.find())
		{
			return "";
		}

		return figureMatcher.group(1) == null ? figureMatcher.group(2) : figureMatcher.group(1);
	}

	private static String normalizeImageUrl(String src)
	{
		String trimmed = src.trim();
		if (trimmed.startsWith("//"))
		{
			return "https:" + trimmed;
		}
		if (trimmed.startsWith("/"))
		{
			return "https://oldschool.runescape.wiki" + trimmed;
		}
		if (trimmed.startsWith("http://") || trimmed.startsWith("https://"))
		{
			return trimmed;
		}

		return null;
	}

	private static int parseImageDimension(String value, String src)
	{
		if (value != null)
		{
			try
			{
				String digits = value.replaceAll("[^0-9]", "");
				return digits.isEmpty() ? 0 : Integer.parseInt(digits);
			}
			catch (NumberFormatException ignored)
			{
				return 0;
			}
		}

		if (src == null)
		{
			return 0;
		}

		Matcher thumbMatcher = Pattern.compile("(?i)/(\\d+)px-[^/]+$").matcher(src);
		return thumbMatcher.find() ? Integer.parseInt(thumbMatcher.group(1)) : 0;
	}

	private static boolean isKnownSmallImage(int width, int height)
	{
		return (width > 0 && width < MIN_LOCATION_IMAGE_WIDTH) || (height > 0 && height < MIN_LOCATION_IMAGE_HEIGHT);
	}

	private static boolean isSvgOrDataImage(String src)
	{
		String normalized = src.toLowerCase(Locale.ENGLISH);
		return normalized.contains(".svg") || normalized.startsWith("data:image");
	}

	private static String extractImageFilename(String src)
	{
		String withoutQuery = src.split("\\?", 2)[0];
		int slashIndex = withoutQuery.lastIndexOf('/');
		String filename = slashIndex >= 0 ? withoutQuery.substring(slashIndex + 1) : withoutQuery;
		if (filename.matches("(?i)\\d+px-.+"))
		{
			filename = filename.replaceFirst("(?i)^\\d+px-", "");
		}
		try
		{
			filename = URLDecoder.decode(filename, StandardCharsets.UTF_8.name());
		}
		catch (IllegalArgumentException | UnsupportedEncodingException ignored)
		{
			// Keep the raw filename if the URL escape sequence is malformed.
		}

		return filename.replace('_', ' ');
	}

	private static String extractTemplateParameter(String content, String parameterName)
	{
		Matcher matcher = TEMPLATE_PARAMETER.matcher(content);
		while (matcher.find())
		{
			if (matcher.group(1).trim().equalsIgnoreCase(parameterName))
			{
				return matcher.group(2).trim();
			}
		}

		return "";
	}

	private static String findAttribute(String html, String attributeName)
	{
		Pattern pattern = Pattern.compile(String.format(ATTRIBUTE_VALUE.pattern(), Pattern.quote(attributeName)));
		Matcher matcher = pattern.matcher(html);
		return matcher.find() ? matcher.group(1) : null;
	}

	private static String cleanHtml(String html)
	{
		return decodeHtml(nullToEmpty(html)
			.replaceAll("(?is)<script\\b.*?</script>", "")
			.replaceAll("(?is)<style\\b.*?</style>", "")
			.replaceAll("(?is)<[^>]+>", " ")
			.replaceAll("\\s+", " ")
			.trim());
	}

	private static String decodeHtml(String text)
	{
		return text
			.replace("&nbsp;", " ")
			.replace("&#160;", " ")
			.replace("&amp;", "&")
			.replace("&lt;", "<")
			.replace("&gt;", ">")
			.replace("&quot;", "\"")
			.replace("&#039;", "'")
			.replace("&#39;", "'")
			.replaceAll("\\s+", " ")
			.trim();
	}

	private static String firstUseful(String first, String second, String third)
	{
		if (first != null && !first.trim().isEmpty())
		{
			return first;
		}
		if (second != null && !second.trim().isEmpty())
		{
			return second;
		}

		return third;
	}

	private static String nullToEmpty(String value)
	{
		return value == null ? "" : value;
	}

	private static String extractLocationSection(String content)
	{
		Matcher matcher = Pattern.compile("(?im)^==+\\s*Locations?\\s*==+\\s*$").matcher(content);
		if (!matcher.find())
		{
			return "";
		}

		int start = matcher.end();
		Matcher nextHeading = Pattern.compile("(?m)^==+\\s*[^=].*==+\\s*$").matcher(content);
		if (nextHeading.find(start))
		{
			return content.substring(start, nextHeading.start());
		}

		return content.substring(start);
	}

	private static void addLocationCandidates(Set<String> locations, String text)
	{
		if (text == null || text.trim().isEmpty() || locations.size() >= MAX_SOURCE_LOCATIONS)
		{
			return;
		}

		Matcher linkMatcher = WIKI_LINK.matcher(text);
		while (linkMatcher.find() && locations.size() < MAX_SOURCE_LOCATIONS)
		{
			addCleanLocation(locations, linkMatcher.group(2) == null ? linkMatcher.group(1) : linkMatcher.group(2));
		}

		if (!locations.isEmpty() || text.contains("[["))
		{
			return;
		}

		for (String part : text.split("(?i)<br\\s*/?>|,|;|\\n|\\*"))
		{
			if (locations.size() >= MAX_SOURCE_LOCATIONS)
			{
				break;
			}
			addCleanLocation(locations, part);
		}
	}

	private static void addCleanLocation(Set<String> locations, String rawLocation)
	{
		String cleaned = cleanWikiText(rawLocation);
		if (!cleaned.isEmpty() && !cleaned.equalsIgnoreCase("Unknown") && !cleaned.equalsIgnoreCase("N/A"))
		{
			locations.add(cleaned);
		}
	}

	private static String cleanWikiText(String wikiText)
	{
		return wikiText
			.replaceAll("(?s)<!--.*?-->", "")
			.replaceAll("\\{\\{FloorNumber\\|uk=([^}|]+)}}", "$1")
			.replaceAll("\\{\\{[^{}]*}}", "")
			.replaceAll("\\[\\[([^]|]+)\\|([^]]+)]]", "$2")
			.replaceAll("\\[\\[([^]]+)]]", "$1")
			.replaceAll("'''", "")
			.replaceAll("''", "")
			.replaceAll("<[^>]+>", " ")
			.replaceAll("\\s+", " ")
			.trim();
	}

	private static String buildItemSearchQuery(String searchTerm)
	{
		return "intitle:\"" + searchTerm.replace("\"", " ") + "\" hastemplate:\"Infobox Item\"";
	}

	private static boolean isLikelyItemSearchResult(String searchTerm, String title)
	{
		if (title.isEmpty() || title.contains("/") || title.contains(":"))
		{
			return false;
		}

		String normalizedTitle = title.toLowerCase(Locale.ENGLISH);
		if (normalizedTitle.endsWith(" guide") || normalizedTitle.contains(" guide/")
			|| normalizedTitle.contains("quest") || normalizedTitle.contains("slayer task")
			|| normalizedTitle.contains("strategy") || normalizedTitle.equals("dragon slayer i")
			|| normalizedTitle.equals("dragon slayer ii"))
		{
			return false;
		}

		String normalizedSearchTerm = searchTerm.toLowerCase(Locale.ENGLISH);
		for (String token : normalizedSearchTerm.split("\\s+"))
		{
			if (!token.isEmpty() && !normalizedTitle.contains(token))
			{
				return false;
			}
		}

		return true;
	}

	private static String extractContent(JsonObject page)
	{
		JsonArray revisions = page.getAsJsonArray("revisions");
		if (revisions == null || revisions.size() == 0)
		{
			return "";
		}

		JsonObject revision = revisions.get(0).getAsJsonObject();
		JsonObject slots = revision.getAsJsonObject("slots");
		if (slots != null)
		{
			JsonObject main = slots.getAsJsonObject("main");
			if (main != null)
			{
				return getString(main, "content", "");
			}
		}

		return getString(revision, "content", "");
	}

	private static String getString(JsonObject object, String name, String fallback)
	{
		JsonElement element = object.get(name);
		return element == null || element.isJsonNull() ? fallback : element.getAsString();
	}

	static String buildPageUrl(String title)
	{
		return "https://oldschool.runescape.wiki/w/" + URLEncoder.encode(title.replace(' ', '_'), StandardCharsets.UTF_8);
	}

	private static String firstChars(String value, int length)
	{
		if (value == null)
		{
			return "";
		}

		return value.length() <= length ? value : value.substring(0, length);
	}

