package com.wikiitemhelper;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class BestSourceBuilder
{
	private static final Logger log = LoggerFactory.getLogger(BestSourceBuilder.class);
	private static final int MAX_CREATION_ENTRIES = 2;
	private static final int MAX_SHOP_ENTRIES = 2;
	private static final int MAX_DROP_ENTRIES = 3;
	private static final Pattern RARITY_LINE = Pattern.compile("(?im)^\\s*Rarity:\\s*(.+?)\\s*$");
	private static final Pattern RARITY_FRACTION = Pattern.compile("(?i)(?:~\\s*)?(?:(\\d+(?:\\.\\d+)?)\\s*x\\s*)?(\\d+(?:\\.\\d+)?)\\s*/\\s*(\\d+(?:\\.\\d+)?)");
	private static final Pattern OUTPUT_LINE = Pattern.compile("(?im)^\\s*Output:\\s*(.+?)\\s*$");
	private static final Pattern MATERIALS_LINE = Pattern.compile("(?im)^\\s*Materials:\\s*(.+?)\\s*$");
	private static final Pattern LEVEL_LINE = Pattern.compile("(?im)^\\s*Level\\s+(\\S+)\\s+(.+?)\\s*$");
	private static final Pattern SKILL_LINE = Pattern.compile("(?im)^\\s*Skill:\\s*(.+?)\\s*$");
	private static final BestSourceReasonBuilder REASON_BUILDER = new BestSourceReasonBuilder();
	private static final String[] VAGUE_REWARD_TERMS = {
		"reward casket", "clue scroll", "mystery box", "impling jar", "brimstone chest", "crystal chest", "generic chest"
	};
	private static final String[] WILDERNESS_TERMS = {
		"revenant", "wilderness", "callisto", "venenatis", "vet'ion", "vetion", "chaos elemental", "chaos fanatic", "scorpia", "crazy archaeologist"
	};

	public String build(WikiItemSummary summary, boolean ironmanMode)
	{
		return buildResult(summary, "", ironmanMode).toDisplayText();
	}

	public BestSourceResult buildResult(WikiItemSummary summary, boolean ironmanMode)
	{
		return buildResult(summary, "", ironmanMode);
	}

	public BestSourceResult buildResult(WikiItemSummary summary, String itemName, boolean ironmanMode)
	{
		CreationSplit creationSplit = splitCreation(summary.getCreation(), itemName, ironmanMode);
		List<BestEntry> creation = chooseCreation(creationSplit.getNormalCreationText(), ironmanMode);
		List<BestEntry> shops = chooseShops(summary.getShops(), ironmanMode);
		List<BestDrop> drops = chooseDrops(summary.getDropSources(), summary.getDrops(), ironmanMode);

		return new BestSourceResult(ironmanMode, creation, shops, drops);
	}

	static String removeBestCreation(String creationText, BestSourceResult bestSources, boolean ironmanMode)
	{
		return removeBestCreation(creationText, bestSources, "", ironmanMode);
	}

	static String removeBestCreation(String creationText, BestSourceResult bestSources, String itemName, boolean ironmanMode)
	{
		String filtered = ironmanMode ? filterIronman(creationText) : creationText;
		CreationSplit creationSplit = splitCreation(filtered, itemName, false);
		String normalCreationText = creationSplit.getNormalCreationText();
		if (!isUseful(normalCreationText) || bestSources.getCreationEntries().isEmpty())
		{
			return normalCreationText;
		}

		List<String> remaining = new ArrayList<>();
		for (String block : normalCreationText.split("\\R\\s*\\R"))
		{
			if (!bestSources.includesCreationBlock(block))
			{
				remaining.add(block.trim());
			}
		}

		return remaining.isEmpty() ? WikiItemSummary.NO_CLEAR_DATA_FOUND : String.join("\n\n", remaining);
	}

	static CreationSplit splitCreation(String creationText, String itemName, boolean ironmanMode)
	{
		String filtered = ironmanMode ? filterIronman(creationText) : creationText;
		if (!isUseful(filtered))
		{
			return CreationSplit.empty();
		}

		List<String> normal = new ArrayList<>();
		List<VariantRecipe> variants = new ArrayList<>();
		for (String block : filtered.split("\\R\\s*\\R"))
		{
			String trimmed = block.trim();
			if (trimmed.isEmpty())
			{
				continue;
			}

			VariantRecipe variantRecipe = parseVariantRecipe(trimmed, itemName);
			if (variantRecipe == null)
			{
				debugAntidote(itemName, "recipe kept as normal creation block");
				normal.add(trimmed);
			}
			else
			{
				debugAntidote(itemName, "recipe hidden as variant output={}, materials={}", variantRecipe.getOutputName(), variantRecipe.getMaterialsText());
				variants.add(variantRecipe);
			}
		}

		return new CreationSplit(normal.isEmpty() ? WikiItemSummary.NO_CLEAR_DATA_FOUND : String.join("\n\n", normal), variants);
	}

	static String removeBestShops(String shopsText, BestSourceResult bestSources, boolean ironmanMode)
	{
		String filtered = ironmanMode ? filterIronman(shopsText) : shopsText;
		if (!isUseful(filtered) || bestSources.getShopEntries().isEmpty())
		{
			return filtered;
		}

		List<String> remaining = new ArrayList<>();
		for (String line : filtered.split("\\R|;"))
		{
			String trimmed = cleanSentence(line);
			if (!trimmed.isEmpty() && !bestSources.includesShop(trimmed))
			{
				remaining.add(trimmed);
			}
		}

		return remaining.isEmpty() ? WikiItemSummary.NO_CLEAR_DATA_FOUND : String.join("\n", remaining);
	}

	static List<DropSource> removeBestDropSources(List<DropSource> dropSources, BestSourceResult bestSources)
	{
		if (dropSources == null || dropSources.isEmpty() || bestSources.getDropEntries().isEmpty())
		{
			return dropSources == null ? Collections.emptyList() : dropSources;
		}

		List<DropSource> remaining = new ArrayList<>();
		for (DropSource dropSource : dropSources)
		{
			if (!bestSources.includesDrop(dropSource))
			{
				remaining.add(dropSource);
			}
		}

		return remaining;
	}

	private static List<BestEntry> chooseCreation(String creationText, boolean ironmanMode)
	{
		String filtered = ironmanMode ? filterIronman(creationText) : creationText;
		if (!isUseful(filtered))
		{
			return Collections.emptyList();
		}

		List<CreationCandidate> candidates = new ArrayList<>();
		for (String block : filtered.split("\\R\\s*\\R"))
		{
			String compact = compactCreation(block);
			if (!compact.isEmpty())
			{
				addPreferredCreationCandidate(candidates, new CreationCandidate(block, compact, creationIdentity(block), creationDisplayScore(block)));
			}
		}

		List<BestEntry> entries = new ArrayList<>();
		for (CreationCandidate candidate : candidates)
		{
				entries.add(new BestEntry(candidate.compactText, candidate.identity, REASON_BUILDER.creationTags(candidate.compactText, ironmanMode)));
			if (entries.size() == MAX_CREATION_ENTRIES)
			{
				break;
			}
		}
		return entries;
	}

	private static void addPreferredCreationCandidate(List<CreationCandidate> candidates, CreationCandidate candidate)
	{
		for (int i = 0; i < candidates.size(); i++)
		{
			CreationCandidate existing = candidates.get(i);
			if (existing.identity.equals(candidate.identity))
			{
				if (candidate.displayScore < existing.displayScore)
				{
					candidates.set(i, candidate);
				}
				else
				{
					debugAntidoteBlock(candidate.block, "creation candidate removed by Best sources deduplication");
				}
				return;
			}
		}

		candidates.add(candidate);
	}

	private static String compactCreation(String block)
	{
		List<String> lines = new ArrayList<>();
		for (String line : block.split("\\R"))
		{
			String trimmed = line.trim();
			if (trimmed.isEmpty() || startsWithAny(trimmed, "Output:", "XP:"))
			{
				continue;
			}

			lines.add(trimmed);
			if (lines.size() == 3)
			{
				break;
			}
		}

		return String.join("\n", lines);
	}

	private static VariantRecipe parseVariantRecipe(String block, String currentItemName)
	{
		if (currentItemName == null || currentItemName.trim().isEmpty())
		{
			return null;
		}

		String outputText = findLineValue(OUTPUT_LINE, block);
		String materialsText = findLineValue(MATERIALS_LINE, block);
		if (outputText.isEmpty() || materialsText.isEmpty())
		{
			return null;
		}

		String current = normalizeItemName(currentItemName);
		if (current.isEmpty())
		{
			return null;
		}

		List<String> outputs = splitItems(outputText);
		List<String> materials = splitItems(materialsText);
		boolean currentIsMaterial = false;
		for (String material : materials)
		{
			if (normalizeItemName(material).equals(current))
			{
				currentIsMaterial = true;
				break;
			}
		}
		if (!currentIsMaterial)
		{
			return null;
		}

		for (String output : outputs)
		{
			String normalizedOutput = normalizeItemName(output);
			if (normalizedOutput.equals(current))
			{
				return null;
			}
			if (isVariantOutput(current, normalizedOutput))
			{
				return new VariantRecipe(cleanItemLabel(output), compactMaterials(materials));
			}
		}

		return null;
	}

	private static boolean isVariantOutput(String currentItemName, String outputItemName)
	{
		if (!outputItemName.startsWith(currentItemName + " "))
		{
			return false;
		}

		String suffix = outputItemName.substring(currentItemName.length()).trim();
		return suffix.startsWith("p") || suffix.startsWith("kp") || suffix.contains("poison")
			|| suffix.contains("charged") || suffix.contains("uncharged") || suffix.contains("imbued")
			|| suffix.contains("noted") || suffix.contains("ornament") || suffix.contains("trimmed")
			|| suffix.contains("cosmetic");
	}

	private static String findLineValue(Pattern pattern, String text)
	{
		Matcher matcher = pattern.matcher(text);
		return matcher.find() ? matcher.group(1).trim() : "";
	}

	private static List<String> splitItems(String text)
	{
		List<String> items = new ArrayList<>();
		for (String item : text.split(","))
		{
			String cleaned = cleanItemLabel(item);
			if (!cleaned.isEmpty())
			{
				items.add(cleaned);
			}
		}

		return items;
	}

	private static String compactMaterials(List<String> materials)
	{
		List<String> compact = new ArrayList<>();
		for (String material : materials)
		{
			compact.add(material.replaceFirst("(?i)^\\d+\\s+", ""));
		}

		return String.join(" + ", compact);
	}

	private static String cleanItemLabel(String value)
	{
		return value
			.replaceAll("(?i)\\s*\\([^)]*noted[^)]*\\)", "")
			.replaceAll("\\s+", " ")
			.trim();
	}

	private static String normalizeItemName(String value)
	{
		return cleanItemLabel(value)
			.replaceFirst("(?i)^\\d+\\s+", "")
			.toLowerCase(Locale.ENGLISH)
			.replaceAll("[^a-z0-9+]+", " ")
			.trim();
	}

	private static List<BestEntry> chooseShops(String shopsText, boolean ironmanMode)
	{
		String filtered = ironmanMode ? filterIronman(shopsText) : shopsText;
		if (!isUseful(filtered))
		{
			return Collections.emptyList();
		}

		List<BestEntry> entries = new ArrayList<>();
		for (String line : filtered.split("\\R|;"))
		{
			String trimmed = cleanSentence(line);
			if (!trimmed.isEmpty())
			{
				entries.add(new BestEntry(trimmed, normalizeIdentity(trimmed), REASON_BUILDER.shopTags(trimmed, ironmanMode)));
			}
			if (entries.size() == MAX_SHOP_ENTRIES)
			{
				break;
			}
		}

		return entries;
	}

	private static List<BestDrop> chooseDrops(List<DropSource> dropSources, String dropsText, boolean ironmanMode)
	{
		List<DropCandidate> candidates = new ArrayList<>();
		if (dropSources != null && !dropSources.isEmpty())
		{
			for (DropSource dropSource : dropSources)
			{
				addDropCandidate(candidates, dropSource, dropSource.getSourceName(), dropSource.getDisplayText(), ironmanMode);
			}
		}
		else if (isUseful(dropsText))
		{
			for (String block : dropsText.split("\\R\\s*\\R"))
			{
				String[] lines = block.split("\\R", 2);
				addDropCandidate(candidates, null, lines[0], block, ironmanMode);
			}
		}

		candidates.sort(Comparator
			.comparingInt((DropCandidate candidate) -> candidate.vagueReward ? 1 : 0)
			.thenComparingInt(candidate -> candidate.rarityScore == null ? 1 : 0)
			.thenComparingDouble(BestSourceBuilder::adjustedRarityScore)
			.thenComparing(candidate -> candidate.name.toLowerCase(Locale.ENGLISH)));

		List<BestDrop> entries = new ArrayList<>();
		for (DropCandidate candidate : candidates)
		{
			BestDrop entry = new BestDrop(formatDrop(candidate), candidate.name, candidate.source, candidate.dropIdentity);
			entries.add(entry.withTags(REASON_BUILDER.dropTags(entry, ironmanMode)));
			if (entries.size() == MAX_DROP_ENTRIES)
			{
				break;
			}
		}

		return entries;
	}

	private static void addDropCandidate(List<DropCandidate> candidates, DropSource source, String name, String displayText, boolean ironmanMode)
	{
		String filteredText = ironmanMode ? filterIronman(displayText) : displayText;
		if (!isUseful(name) || !isUseful(filteredText))
		{
			return;
		}

		String normalizedName = name.toLowerCase(Locale.ENGLISH);
		if (normalizedName.contains("grand exchange") || normalizedName.contains("player trading"))
		{
			return;
		}

		String rarity = extractRarity(filteredText);
		candidates.add(new DropCandidate(
			name.trim(),
			rarity,
			parseRarityScore(rarity),
			containsAny(normalizedName, VAGUE_REWARD_TERMS),
			containsAny(normalizedName, WILDERNESS_TERMS),
			source,
			dropIdentity(source, name)
		));
	}

	private static String formatDrop(DropCandidate candidate)
	{
		if (candidate.rarity == null || candidate.rarity.trim().isEmpty())
		{
			return candidate.name;
		}

		return candidate.name + " - " + candidate.rarity;
	}

	private static double adjustedRarityScore(DropCandidate candidate)
	{
		if (candidate.rarityScore == null)
		{
			return Double.MAX_VALUE;
		}

		return candidate.wilderness ? candidate.rarityScore * 3D : candidate.rarityScore;
	}

	private static String extractRarity(String displayText)
	{
		Matcher matcher = RARITY_LINE.matcher(displayText);
		return matcher.find() ? matcher.group(1).trim() : "";
	}

	static Double parseRarityScore(String rarity)
	{
		if (rarity == null || rarity.trim().isEmpty())
		{
			return null;
		}

		Double best = null;
		Matcher matcher = RARITY_FRACTION.matcher(rarity.replace("&times;", "x").replace('\u00D7', 'x').replace(",", ""));
		while (matcher.find())
		{
			double rolls = parseDouble(matcher.group(1), 1D);
			double numerator = parseDouble(matcher.group(2), 1D);
			double denominator = parseDouble(matcher.group(3), 0D);
			if (denominator <= 0D)
			{
				continue;
			}

			double chance = rolls * numerator / denominator;
			if (chance <= 0D)
			{
				continue;
			}

			double score = 1D / chance;
			if (best == null || score < best)
			{
				best = score;
			}
		}

		return best;
	}

	private static double parseDouble(String value, double fallback)
	{
		if (value == null || value.trim().isEmpty())
		{
			return fallback;
		}

		try
		{
			return Double.parseDouble(value.trim());
		}
		catch (NumberFormatException ex)
		{
			return fallback;
		}
	}

	private static String filterIronman(String value)
	{
		if (!isUseful(value))
		{
			return WikiItemSummary.NO_CLEAR_DATA_FOUND;
		}

		StringBuilder filtered = new StringBuilder();
		for (String line : value.split("\\R"))
		{
			String normalized = line.toLowerCase(Locale.ENGLISH);
			if (normalized.contains("grand exchange") || normalized.contains("tradeable")
				|| normalized.contains("trade with") || normalized.contains("traded with")
				|| normalized.contains("buy from other players") || normalized.contains("sold by other players"))
			{
				continue;
			}

			if (filtered.length() > 0)
			{
				filtered.append('\n');
			}
			filtered.append(line);
		}

		String result = filtered.toString().trim();
		return result.isEmpty() ? WikiItemSummary.NO_CLEAR_DATA_FOUND : result;
	}

	private static String cleanSentence(String value)
	{
		String trimmed = value.trim();
		return trimmed.endsWith(".") ? trimmed.substring(0, trimmed.length() - 1) : trimmed;
	}

	private static String dropIdentity(DropSource dropSource, String fallbackName)
	{
		if (dropSource == null)
		{
			return normalizeIdentity(fallbackName);
		}

		String pageTitle = dropSource.getSourceWikiPageTitle();
		return normalizeIdentity(pageTitle == null || pageTitle.trim().isEmpty() ? dropSource.getSourceName() : pageTitle);
	}

	private static String normalizeBlock(String value)
	{
		return normalizeIdentity(value).replace(" output ", " ").replace(" xp ", " ");
	}

	private static String creationIdentity(String block)
	{
		String materials = findLineValue(MATERIALS_LINE, block);
		String output = findLineValue(OUTPUT_LINE, block);
		if (materials.isEmpty() || output.isEmpty())
		{
			return normalizeBlock(block);
		}

		return creationSkillIdentity(block) + "|out:" + canonicalOutputItems(output) + "|mat:" + canonicalItems(materials);
	}

	private static String creationSkillIdentity(String block)
	{
		Matcher levelMatcher = LEVEL_LINE.matcher(block);
		if (levelMatcher.find())
		{
			return "level:" + normalizeIdentity(levelMatcher.group(1)) + "|skill:" + normalizeIdentity(levelMatcher.group(2));
		}

		Matcher skillMatcher = SKILL_LINE.matcher(block);
		if (skillMatcher.find())
		{
			return "skill:" + normalizeIdentity(skillMatcher.group(1));
		}

		return "skill:";
	}

	private static String canonicalItems(String text)
	{
		List<String> items = new ArrayList<>();
		for (String item : splitItems(text))
		{
			String canonical = canonicalMaterialIdentity(item);
			if (!canonical.isEmpty())
			{
				items.add(canonical);
			}
		}
		Collections.sort(items);
		return String.join("+", items);
	}

	private static String canonicalOutputItems(String text)
	{
		List<String> items = new ArrayList<>();
		for (String item : splitItems(text))
		{
			String canonical = canonicalMaterialIdentity(item).replaceFirst("(?i)\\s+[1-4]$", "").trim();
			if (!canonical.isEmpty())
			{
				items.add(canonical);
			}
		}
		Collections.sort(items);
		return String.join("+", items);
	}

	private static String canonicalMaterialIdentity(String value)
	{
		return normalizeItemName(value)
			.replaceFirst("(?i)\\s+potion\\s+unf$", "")
			.replaceFirst("(?i)\\s+unfinished\\s+potion$", "")
			.trim();
	}

	private static int creationDisplayScore(String block)
	{
		String materials = findLineValue(MATERIALS_LINE, block).toLowerCase(Locale.ENGLISH);
		int score = block.length();
		if (materials.contains("potion (unf)") || materials.contains("unfinished potion"))
		{
			score += 1000;
		}
		return score;
	}

	private static String normalizeIdentity(String value)
	{
		return value == null ? "" : value.toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9]+", " ").trim();
	}

	private static boolean isUseful(String value)
	{
		return value != null && !value.trim().isEmpty() && !WikiItemSummary.NO_CLEAR_DATA_FOUND.equals(value);
	}

	private static boolean startsWithAny(String value, String... prefixes)
	{
		for (String prefix : prefixes)
		{
			if (value.startsWith(prefix))
			{
				return true;
			}
		}

		return false;
	}

	private static boolean containsAny(String value, String[] terms)
	{
		for (String term : terms)
		{
			if (value.contains(term))
			{
				return true;
			}
		}

		return false;
	}

	private static void debugAntidote(String itemName, String message, Object... args)
	{
		if (itemName != null && itemName.equalsIgnoreCase("Antidote++"))
		{
			log.debug("WikiItemHelper Antidote++ creation debug: " + message, args);
		}
	}

	private static void debugAntidoteBlock(String block, String message)
	{
		if (block != null && block.toLowerCase(Locale.ENGLISH).contains("antidote++"))
		{
			log.debug("WikiItemHelper Antidote++ creation debug: {} block={}", message, block);
		}
	}

	private static class DropCandidate
	{
		private final String name;
		private final String rarity;
		private final Double rarityScore;
		private final boolean vagueReward;
		private final boolean wilderness;
		private final DropSource source;
		private final String dropIdentity;

		private DropCandidate(String name, String rarity, Double rarityScore, boolean vagueReward, boolean wilderness, DropSource source, String dropIdentity)
		{
			this.name = name;
			this.rarity = rarity;
			this.rarityScore = rarityScore;
			this.vagueReward = vagueReward;
			this.wilderness = wilderness;
			this.source = source;
			this.dropIdentity = dropIdentity;
		}
	}

	public static class BestSourceResult
	{
		private final boolean ironmanMode;
		private final List<BestEntry> creationEntries;
		private final List<BestEntry> shopEntries;
		private final List<BestDrop> dropEntries;

		private BestSourceResult(boolean ironmanMode, List<BestEntry> creationEntries, List<BestEntry> shopEntries, List<BestDrop> dropEntries)
		{
			this.ironmanMode = ironmanMode;
			this.creationEntries = Collections.unmodifiableList(new ArrayList<>(creationEntries));
			this.shopEntries = Collections.unmodifiableList(new ArrayList<>(shopEntries));
			this.dropEntries = Collections.unmodifiableList(new ArrayList<>(dropEntries));
		}

		public boolean isEmpty()
		{
			return creationEntries.isEmpty() && shopEntries.isEmpty() && dropEntries.isEmpty();
		}

		public String getTitle()
		{
			return ironmanMode ? "Best Ironman sources:" : "Best sources:";
		}

		public List<BestEntry> getCreationEntries()
		{
			return creationEntries;
		}

		public List<BestEntry> getShopEntries()
		{
			return shopEntries;
		}

		public List<BestDrop> getDropEntries()
		{
			return dropEntries;
		}

		public boolean includesCreationBlock(String block)
		{
			String normalized = creationIdentity(block);
			for (BestEntry entry : creationEntries)
			{
				if (entry.identity.equals(normalized))
				{
					return true;
				}
			}

			return false;
		}

		public boolean includesShop(String shop)
		{
			String normalized = normalizeIdentity(shop);
			for (BestEntry entry : shopEntries)
			{
				if (entry.identity.equals(normalized))
				{
					return true;
				}
			}

			return false;
		}

		public boolean includesDrop(DropSource dropSource)
		{
			String identity = dropIdentity(dropSource, dropSource.getSourceName());
			for (BestDrop entry : dropEntries)
			{
				if (entry.dropIdentity.equals(identity))
				{
					return true;
				}
			}

			return false;
		}

		public String toDisplayText()
		{
			if (isEmpty())
			{
				return "";
			}

			StringBuilder text = new StringBuilder();
			text.append(getTitle());
			appendGroup(text, "Crafting:", creationEntries);
			appendGroup(text, "Shop:", shopEntries);
			appendGroup(text, "Drops:", dropEntries);
			return text.toString();
		}

		private static void appendGroup(StringBuilder text, String heading, List<? extends BestEntry> entries)
		{
			if (entries.isEmpty())
			{
				return;
			}

			text.append("\n\n").append(heading);
			for (BestEntry entry : entries)
			{
				for (String line : entry.getDisplayText().split("\\R"))
				{
					if (!line.trim().isEmpty())
					{
						text.append("\n  ").append(line.trim());
					}
				}
				if (!entry.getTags().isEmpty())
				{
					text.append("\n  Tags: ").append(String.join(", ", entry.getTags()));
				}
			}
		}
	}

