	public static class BestEntry
	{
		private final String displayText;
		private final String identity;
		private final List<String> tags;

		private BestEntry(String displayText, String identity)
		{
			this(displayText, identity, Collections.emptyList());
		}

		private BestEntry(String displayText, String identity, List<String> tags)
		{
			this.displayText = displayText;
			this.identity = identity;
			this.tags = Collections.unmodifiableList(new ArrayList<>(tags == null ? Collections.emptyList() : tags));
		}

		public String getDisplayText()
		{
			return displayText;
		}

		public List<String> getTags()
		{
			return tags;
		}
