	public static class BestDrop extends BestEntry
	{
		private final String sourceName;
		private final DropSource source;
		private final String dropIdentity;

		private BestDrop(String displayText, String sourceName, DropSource source, String dropIdentity)
		{
			this(displayText, sourceName, source, dropIdentity, Collections.emptyList());
		}

		private BestDrop(String displayText, String sourceName, DropSource source, String dropIdentity, List<String> tags)
		{
			super(displayText, dropIdentity, tags);
			this.sourceName = sourceName;
			this.source = source;
			this.dropIdentity = dropIdentity;
		}

		private BestDrop withTags(List<String> tags)
		{
			return new BestDrop(getDisplayText(), sourceName, source, dropIdentity, tags);
		}

		public String getSourceName()
		{
			return sourceName;
		}

		public DropSource getSource()
		{
			return source;
		}
	}
}

package com.wikiitemhelper;

public class MaterialAcquisitionHint
{
	private final String materialName;
	private final String quantity;
	private final String hintText;
	private final String materialWikiTitle;

	public MaterialAcquisitionHint(String materialName, String quantity, String hintText, String materialWikiTitle)
	{
		this.materialName = materialName;
		this.quantity = blankToNull(quantity);
		this.hintText = hintText == null ? "" : hintText.trim();
		this.materialWikiTitle = blankToNull(materialWikiTitle);
	}

	public String getMaterialName()
	{
		return materialName;
	}

	public String getQuantity()
	{
		return quantity;
	}

	public String getHintText()
	{
		return hintText;
	}

	public String getMaterialWikiTitle()
	{
		return materialWikiTitle;
	}

	public String getDisplayName()
	{
		return quantity == null ? materialName : materialName + " x" + quantity;
	}

	private static String blankToNull(String value)
	{
		return value == null || value.trim().isEmpty() ? null : value.trim();
	}
}
